function compactShortcutHint(keys: string[]): string {
  if (keys.length === 0 || keys[0] === 'Unassigned') return ''
  return keys
    .map((key) => {
      if (key === 'Cmd/Ctrl') return '⌘'
      if (key === 'Shift') return '⇧'
      if (key === 'Alt') return '⌥'
      return key
    })
    .join('')
}

