  useEffect(() => {
    scheduledTasksRef.current = scheduledTasks
  }, [scheduledTasks])

  // ----- Raw Events auto-follow scrolling -------------------------------
  // Mirrors the transcript auto-follow design owned by
  // `useTranscriptScrollState`. The Raw Events panel streams
  // a new entry for every run event; before this fix the effect below
  // unconditionally wrote `scrollTop = scrollHeight` whenever
  // `rawLogs.length` changed, which fought the user any time they tried
  // to scroll up to inspect earlier events during an active run.
  //
  // Three effects implement the policy and intentionally reuse the same
  // `lib/TranscriptScroll` helpers as the transcript so the two surfaces
  // share one truth source:
  //   1. Scroll listener flips `rawEventsAutoFollowRef` based on
  //      distance-from-bottom with hysteresis
  //      (`shouldEngageAutoFollow` / `shouldDisengageAutoFollow`).
  //   2. Wheel/touch/keyboard listeners record real user-initiated
  //      upward scrolls into `rawEventsUserScrolledAwayRef` so the
  //      auto-scroll effect can stand down.
  //   3. The auto-scroll effect (the original site of the bug) is gated
  //      on `rawEventsAutoFollowRef`; when auto-follow is engaged it
  //      writes once to the bottom, when disengaged it leaves the user
  //      where they are.
  //
  // The scroll container is `.raw-events-body` — the inspector tab
  // re-mounts each time `rightTab` flips, so the listener effects are
  // keyed on `rightTab === 'raw'` to (a) bind only when the panel is
  // present in the DOM and (b) re-bind cleanly when the user switches
  // tabs and back.
  useEffect(() => {
    if (rightTab !== 'raw' && rightTab !== 'delegation' && !showGeminiTerminal) return
    const chatId = currentChatIdRef.current
    if (!chatId) return
    rawLogPresentationQueueRef.current?.cancelPending()
    setRawLogs(rawLogSnapshotForChat(chatId, true))
  }, [rightTab, showGeminiTerminal, currentChat?.appChatId])

  useEffect(() => {
    if (rightTab !== 'raw') return
    const scroller = rawLogsEndRef.current?.closest('.raw-events-body') as HTMLElement | null
    if (!scroller) return

    let rafId: number | null = null
    const evaluate = () => {
      rafId = null
      const distanceFromBottom = scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight
      if (shouldEngageAutoFollow(distanceFromBottom)) {
        rawEventsAutoFollowRef.current = true
        // Returning to the bottom clears any prior user scroll-away so
        // the next streamed entry can re-pin without delay.
        rawEventsUserScrolledAwayRef.current = false
      } else if (shouldDisengageAutoFollow(distanceFromBottom)) {
        rawEventsAutoFollowRef.current = false
      }
    }
    const onScroll = () => {
      if (rafId !== null) return
      rafId = requestAnimationFrame(evaluate)
    }
    scroller.addEventListener('scroll', onScroll, { passive: true })
    return () => {
      scroller.removeEventListener('scroll', onScroll)
      if (rafId !== null) cancelAnimationFrame(rafId)
    }
  }, [rightTab])

  // Detect real user-initiated upward scroll attempts on the Raw Events
  // panel. Plain `scroll` events fire for both user input and the
  // browser clamping `scrollTop` when content grows underneath, so the
  // wheel + touch + keyboard listeners below capture the user-intent
  // signal and feed it into `rawEventsUserScrolledAwayRef`. The
  // auto-scroll effect then refuses to fight a deliberate scroll-up.
  useEffect(() => {
    if (rightTab !== 'raw') return
    const scroller = rawLogsEndRef.current?.closest('.raw-events-body') as HTMLElement | null
    if (!scroller) return

    const handleUpwardIntent = (deltaY: number) => {
      // Only upward intent counts: scrolling further down should not
      // flip the flag (it would immediately re-engage anyway).
      if (deltaY >= 0) return
      const distanceFromBottom = scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight
      if (distanceFromBottom > 0) {
        rawEventsUserScrolledAwayRef.current = true
      }
    }

    const onWheel = (event: WheelEvent) => handleUpwardIntent(event.deltaY)

    let lastTouchY: number | null = null
    const onTouchStart = (event: TouchEvent) => {
      lastTouchY = event.touches[0]?.clientY ?? null
    }
    const onTouchMove = (event: TouchEvent) => {
      const currentY = event.touches[0]?.clientY ?? null
      if (currentY === null || lastTouchY === null) return
      // Touch dragging down scrolls up — invert delta to match wheel
      // semantics (negative = upward intent).
      handleUpwardIntent(lastTouchY - currentY)
      lastTouchY = currentY
    }
    const onTouchEnd = () => {
      lastTouchY = null
    }

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'PageUp' || event.key === 'ArrowUp' || event.key === 'Home') {
        handleUpwardIntent(-1)
      }
    }

    scroller.addEventListener('wheel', onWheel, { passive: true })
    scroller.addEventListener('touchstart', onTouchStart, { passive: true })
    scroller.addEventListener('touchmove', onTouchMove, { passive: true })
    scroller.addEventListener('touchend', onTouchEnd, { passive: true })
    scroller.addEventListener('keydown', onKeyDown)

    return () => {
      scroller.removeEventListener('wheel', onWheel)
      scroller.removeEventListener('touchstart', onTouchStart)
      scroller.removeEventListener('touchmove', onTouchMove)
      scroller.removeEventListener('touchend', onTouchEnd)
      scroller.removeEventListener('keydown', onKeyDown)
    }
  }, [rightTab])

  // Auto-scroll the Raw Events panel to the bottom when new events
  // arrive — but only when auto-follow is engaged. `shouldRepinAfterFrame`
  // guards against scrolling while the user has actively scrolled away
  // since the last paint, so a deliberate read-back is never fought.
  // Switching filters / opening the panel also fires this effect, which
  // is the expected "snap to bottom on (re)mount" behaviour.
  useEffect(() => {
    if (rightTab !== 'raw') return
    if (
      !shouldRepinAfterFrame({
        autoFollow: rawEventsAutoFollowRef.current,
        userScrolledAwayInThisFrame: rawEventsUserScrolledAwayRef.current
      })
    ) {
      return
    }
    const rawEventsBody = rawLogsEndRef.current?.closest('.raw-events-body') as HTMLElement | null
    if (rawEventsBody) {
      rawEventsBody.scrollTo({
        top: rawEventsBody.scrollHeight,
        behavior: appearance.reduceMotion ? 'auto' : 'smooth'
      })
      // Clear the per-frame intent flag after a successful auto-scroll
      // so a later wheel event in the same frame can still register.
      rawEventsUserScrolledAwayRef.current = false
    }
  }, [rawLogs.length, rawFilter, rightTab, appearance.reduceMotion])

  useEffect(() => {
    if (showGeminiTerminal) {
      geminiTerminalEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' })
    }
  }, [rawLogs, showGeminiTerminal])

  useEffect(() => {
    const geminiSessionApi = window.api as any
    if (
      typeof geminiSessionApi.onGeminiSessionData !== 'function' &&
      typeof geminiSessionApi.onGeminiSessionExit !== 'function'
    ) {
      return
    }

    if (typeof geminiSessionApi.onGeminiSessionData === 'function') {
      geminiSessionApi.onGeminiSessionData((data: string) => {
        appendThreadRawLogRef.current(currentChatIdRef.current, {
          type: 'stdout',
          content: redactLog(String(data))
        })
      })
    }

    if (typeof geminiSessionApi.onGeminiSessionExit === 'function') {
      geminiSessionApi.onGeminiSessionExit((code: number | null) => {
        persistentSessionActiveRef.current = false
        setPersistentSessionStatus('exited')
        setIsPersistentSessionEnabled(false)
        appendThreadRawLogRef.current(currentChatIdRef.current, {
          type: 'info',
          content: `Persistent Gemini session exited with code ${typeof code === 'number' ? code : 'unknown'}.`
        })
      })
    }

    return () => {
      if (typeof geminiSessionApi.removeGeminiSessionListeners === 'function') {
        geminiSessionApi.removeGeminiSessionListeners()
      }
    }
  }, [])

  useEffect(() => {
    const geminiSessionApi = window.api as any
    if (
      !isPersistentSessionEnabled ||
      !persistentSessionActiveRef.current ||
      typeof geminiSessionApi.resizeGeminiSession !== 'function'
    ) {
      return
    }

    const resizeSession = () => {
      const cols = Math.max(80, Math.floor(window.innerWidth / 8))
      const rows = Math.max(24, Math.floor(window.innerHeight / 18))
      geminiSessionApi.resizeGeminiSession(cols, rows).catch?.(() => {})
    }

    resizeSession()
    window.addEventListener('resize', resizeSession)
    return () => window.removeEventListener('resize', resizeSession)
  }, [isPersistentSessionEnabled])

  const refreshDiff = async (workspacePathOverride?: string) => {
    const workspaceForDiff = currentChatWorkspace || currentWorkspace
    const presentationPath = currentGitPresentationPath || chromeWorkspacePath
    const explicitWorkspacePath =
      typeof workspacePathOverride === 'string' ? workspacePathOverride.trim() : undefined
    if (!explicitWorkspacePath && !workspaceForDiff && !presentationPath) return
    const worktree =
      !explicitWorkspacePath && workspaceForDiff && currentProvider === 'gemini'
        ? resolveGeminiWorktreeConfig(workspaceForDiff)
        : undefined
    if (isGeminiWorktreeDiffUnavailable(worktree)) {
      setDiff(createWorktreeDiffUnavailable())
      setRunDiff(null)
      setDiffView('workspace')
      setDiffRefreshStatus('Diff disabled: worktree path unknown.')
      return
    }

    const diffWorkspacePath =
      explicitWorkspacePath ||
      (currentComposerWorktreeSelection
        ? currentGitPresentationPath
        : presentationPath ||
          (workspaceForDiff ? getDiffWorkspacePath(workspaceForDiff, worktree) : undefined))
    if (!diffWorkspacePath) return
    const diffObj = await window.api.getDiff(diffWorkspacePath)
    setDiff(withWorkspaceDiffPath(diffObj, diffWorkspacePath))
  }

  const openWorkspaceDiffInInspector = async (workspacePath?: string): Promise<void> => {
    const targetPath = workspacePath?.trim() || currentGitPresentationPath
    const requestId = ++workspaceDiffInspectorRequestRef.current
    await openWorkspaceDiffInspector(targetPath, {
      loadDiff: (path) => window.api.getDiff(path),
      isCurrent: () => workspaceDiffInspectorRequestRef.current === requestId,
      onOpen: () => {
        setDiff(null)
        setDiffView('workspace')
        setDiffRefreshStatus('Loading workspace changes…')
        openInspectorTab('diff')
      },
      onLoaded: (diffObj, loadedPath) => {
        setDiff(withWorkspaceDiffPath(diffObj, loadedPath))
        setDiffRefreshStatus('')
      },
      onError: setDiffRefreshStatus
    })
  }

  const openWorkspaceCommitsInInspector = (workspacePath?: string): void => {
    const targetPath = workspacePath?.trim() || currentGitPresentationPath
    if (!targetPath) return
    openInspectorTab('commits', targetPath)
  }

  // ── Host-side fallback compaction (legacy/unmarked Kimi) ──────────────────
  // Pending summarize runs keyed by appRunId, consumed on that run's exit.
  // Ref-only state — a run interrupted by app restart simply never finalizes
  // (no summary stored, no session reset: fail-safe, half-state-free).
  const chatContextTurnsRef = useRef(chatContextTurns)
  chatContextTurnsRef.current = chatContextTurns
  const pendingHostCompactionsRef = useRef(
    new Map<
      string,
      {
        chatId: string
        provider: 'kimi' | 'antigravity' | 'mistral'
        trigger: 'manual' | 'auto'
        preTokens?: number
        startedAtMs: number
        provenance: ContextCompactionProvenance
      }
    >()
  )
  /** Loop breaker for the auto-trigger: one host-compaction attempt per chat
   * per cooldown window, success or failure. */
  const lastHostCompactionAttemptAtByChatIdRef = useRef(new Map<string, number>())
  /** Late-bound handle to compactChatContext (defined much later, next to the
   * context-meter assembly) so the exit-hook trigger below can dispatch it. */
  const compactChatContextRef = useRef<
    ((chatId: string | null, trigger?: 'manual' | 'auto') => Promise<void>) | null
  >(null)
  /**
   * Consume a finished host-compaction summarize run: capture its final
   * assistant message as the stored summary (Kimi keeps its token — its
   * cross-turn context is injection-bounded), and
   * append the compaction card. Failure (non-zero exit / empty summary) cards
   * a failure instead. Idempotent via delete-on-read + deterministic card id.
   */
  const finalizeHostCompactionRun = (completedRunId: string, exitCode: number): void => {
    const pending = pendingHostCompactionsRef.current.get(completedRunId)
    if (!pending) return
    pendingHostCompactionsRef.current.delete(completedRunId)
    const chat = chatByIdRef.current.get(pending.chatId)
    const summaryMessage = chat
      ? [...chat.messages]
          .reverse()
          .find(
            (message) =>
              message.role === 'assistant' &&
              message.runId === completedRunId &&
              Boolean(message.content && message.content.trim())
          )
      : undefined
    const succeeded = exitCode === 0 && Boolean(summaryMessage)
    const telemetry = {
      provider: pending.provider,
      trigger: pending.trigger,
      ...(pending.preTokens !== undefined ? { preTokens: pending.preTokens } : {}),
      durationMs: Date.now() - pending.startedAtMs,
      ...(succeeded
        ? {}
        : {
            error:
              exitCode === 0
                ? 'Summarize turn returned no summary.'
                : `Summarize turn failed (exit ${exitCode}).`
          })
    }
    const signal = { kind: succeeded ? ('completed' as const) : ('failed' as const), telemetry }
    const cardId = contextCompactionMessageId(telemetry, `host-${completedRunId}-${signal.kind}`)
    const summaryText = succeeded
      ? summaryMessage!.content.trim().slice(0, CONTEXT_COMPACTION_SUMMARY_MAX_CHARS)
      : ''
    updateChatById(pending.chatId, (updated) => {
      if (updated.messages.some((message) => message.id === cardId)) return updated
      return {
        ...updated,
        ...(succeeded
          ? {
              contextCompactionSummary: {
                text: summaryText,
                createdAt: new Date().toISOString(),
                provider: pending.provider,
                ...(pending.preTokens !== undefined ? { preTokens: pending.preTokens } : {}),
                provenance: pending.provenance
              }
            }
          : {}),
        messages: [
          ...updated.messages,
          {
            id: cardId,
            role: 'system',
            content: formatContextCompactionSummary(signal, getProviderLabel(pending.provider)),
            timestamp: new Date().toISOString(),
            metadata: {
              kind: CONTEXT_COMPACTION_MESSAGE_KIND,
              contextCompaction: signal,
              provider: pending.provider
            }
          }
        ]
      }
    })
  }
  /**
   * Post-run auto-compaction gate for providers with no native lever. Generic
   * input+output is retained as an advisory UI estimate, but it is not proven
   * session occupancy and therefore cannot authorize a summarize/reset. This
   * hook remains ready for provider-semantic occupancy, classified overflow,
   * or Kimi prompt-projection evidence when those signals are wired.
   */
  const maybeAutoCompactAfterRunExit = (chatId: string | undefined, exitCode: number): void => {
    if (!chatId) return
    // Clean exits only: a cancelled exit is usually a steer about to
    // re-dispatch (racing it with a synthetic run would collide), and a failed
    // exit already surfaces the overflow classifier + manual /compact hint.
    if (exitCode !== 0) return
    if (settings?.hostAutoCompactEnabled === false) return
    const chat = chatByIdRef.current.get(chatId)
    if (!chat || isChatSummaryRecord(chat) || chat.chatKind === 'ensemble') return
    const provider = getChatProvider(chat)
    // Antigravity qualifies on its gemini-api sub-lane only (`api://` synthetic
    // session) — the agy CLI sub-lane owns its own context and must not be
    // host-summarized.
    const antigravityApiLane =
      provider === 'antigravity' && Boolean(chat.linkedProviderSessionId?.startsWith('api://'))
    // Mistral is deliberately ABSENT despite having a manual lever (see
    // compactChatContext). Its only available evidence is generic run usage,
    // which `shouldAutoCompactHostContext` rejects by design — so admitting it
    // here would add a branch that provably never fires, the same dead-code-
    // behind-a-false-gate the seat-session lane was omitted to avoid. It joins
    // when prompt-projection evidence is wired, as Kimi's is specified to be.
    if (provider !== 'kimi' && !antigravityApiLane) return
    // Never chain off an in-flight compaction, and respect the cooldown.
    if ([...pendingHostCompactionsRef.current.values()].some((p) => p.chatId === chatId)) return
    const lastAttempt = lastHostCompactionAttemptAtByChatIdRef.current.get(chatId) || 0
    if (Date.now() - lastAttempt < CONTEXT_AUTO_COMPACT_COOLDOWN_MS) return
    // A queued follow-up is about to pump — don't race it with a synthetic run.
    if (chatHasActiveRunQueueJob(chatId)) {
      return
    }
    const latestRun = [...(chat.runs || [])].reverse().find((run) => run?.stats)
    const usedTokens = currentContextTokens(chat.runs || [], {
      liveOutputTokens: 0,
      isRunning: false
    })
    const windowTokens = resolveContextWindow(
      provider,
      latestRun?.actualModel || latestRun?.requestedModel || '',
      extractUsageLimits(latestRun?.stats).totalTokenLimit
    )
    const advisoryPercent = contextPercent(usedTokens, windowTokens)
    // Antigravity's stateless lane replays the FULL transcript each request,
    // so run input tokens ARE live occupancy — provider-semantic evidence.
    // Kimi's generic run usage stays advisory (a no-op today by design).
    const hostProvider = provider === 'kimi' ? ('kimi' as const) : ('antigravity' as const)
    const evidence =
      hostProvider === 'antigravity'
        ? ({ kind: 'provider_semantic_occupancy', percent: advisoryPercent } as const)
        : ({ kind: 'generic_run_usage', percent: advisoryPercent } as const)
    if (!shouldAutoCompactHostContext(hostProvider, evidence)) {
      return
    }
    void compactChatContextRef.current?.(chatId, 'auto')
  }
  const appEventHandlersRef = useRef({
    appendThreadRawLog,
    clearActiveRunContext,
    getRunFileDiffSummaries,
    refreshDiff,
    refreshUsageSummary,
    resolveActiveRunContext,
    setPendingAgentApprovalByChatId,
    setPendingAgentApprovalForChat,
    setPendingApprovalQueueByChatId,
    enqueueApprovalForChat,
    advanceApprovalQueueForChat,
    showAttachmentPermissionRequest,
    triggerFxBurst,
    finalizeHostCompactionRun,
    maybeAutoCompactAfterRunExit
  })
  appEventHandlersRef.current = {
    appendThreadRawLog,
    clearActiveRunContext,
    getRunFileDiffSummaries,
    refreshDiff,
    refreshUsageSummary,
    resolveActiveRunContext,
    setPendingAgentApprovalByChatId,
    setPendingAgentApprovalForChat,
    setPendingApprovalQueueByChatId,
    enqueueApprovalForChat,
    advanceApprovalQueueForChat,
    showAttachmentPermissionRequest,
    triggerFxBurst,
    finalizeHostCompactionRun,
    maybeAutoCompactAfterRunExit
  }

  // IPC Listeners
  useScopedIpc(() => {
    const handleProviderOutput = (fallbackProvider: ProviderId, payload: unknown) => {
      const handlers = appEventHandlersRef.current
      const provider = getRouteProvider(payload, fallbackProvider)
      const text = extractStreamText(payload, 'data')
      if (!text) return
      const context = handlers.resolveActiveRunContext(
        provider,
        getRouteRunId(payload),
        getRouteChatId(payload)
      )
      if (context) {
        context.adapter.appendChunk(text)
      } else {
        handlers.appendThreadRawLog(getRouteChatId(payload) || currentChatIdRef.current, {
          type: 'stdout',
          content: text
        })
      }
    }

    const handleProviderError = (fallbackProvider: ProviderId, payload: unknown) => {
      const handlers = appEventHandlersRef.current
      const provider = getRouteProvider(payload, fallbackProvider)
      const error = extractStreamText(payload, 'error')
      if (!error) return
      const context = handlers.resolveActiveRunContext(
        provider,
        getRouteRunId(payload),
        getRouteChatId(payload)
      )
      const redacted = redactLog(error)
      const category = classifyError(error)
      const permissionRequest = parseGeminiPermissionRequest(error)
      const errorRunChatId = context?.chatId || getRouteChatId(payload) || currentChatIdRef.current
      const isVisibleErrorRun = !errorRunChatId || currentChatIdRef.current === errorRunChatId
      if (
        provider === 'gemini' &&
        isVisibleErrorRun &&
        permissionRequest &&
        (category === 'permission_or_approval_required' || category === 'untrusted_workspace')
      ) {
        handlers.showAttachmentPermissionRequest({
          ...permissionRequest,
          message: redactLog(permissionRequest.message)
        })
        handlers.triggerFxBurst('warning')
      }

      if (
        provider === 'gemini' &&
        isVisibleErrorRun &&
        category !== 'model_capacity_exhausted' &&
        redacted.toLowerCase().includes('warning')
      ) {
        handlers.triggerFxBurst('warning')
      }

      handlers.appendThreadRawLog(errorRunChatId, {
        type: 'stderr',
        content: redacted,
        timestamp: new Date().toISOString()
      })
    }

    const handleProviderExit = (fallbackProvider: ProviderId, payload: unknown) => {
      const handlers = appEventHandlersRef.current
      const provider = getRouteProvider(payload, fallbackProvider)
      const context = handlers.resolveActiveRunContext(
        provider,
        getRouteRunId(payload),
        getRouteChatId(payload)
      )
      if (!context) {
        // The live run context was lost, so the normal seal below can't run —
        // e.g. a main-process restart mid-run, or a shared codex app-server exit
        // routed to a renderer that no longer holds this run in activeRunsRef
        // (cf. the MCP cross-instance write-leak landmine). Stamp the matching
        // run's terminal state by EXACT id so its footer tally, sidebar
        // "Running" badge, and usage totals don't hang open forever. No-ops when
        // the run is absent or already sealed; exact-id only, so a foreign
        // main-driven run can't be spliced onto the user's in-flight run.
        // Also apply any queued solo provider/model change and prune
        // runningChatIds when no other live activeRunsRef entry remains for
        // this chat — otherwise OOM/orphan exits strand mid-run switches and
        // leave the composer lock sticky even after sealOrphanExitRun.
        const orphanRunId = getRouteRunId(payload)
        const orphanChatId = getRouteChatId(payload)
        if (orphanRunId && orphanChatId) {
          const orphanStats =
            payload && typeof payload === 'object'
              ? (payload as RunRouteEventPayload).stats
              : undefined
          let finalizedOrphanChat: ChatRecord | null = null
          updateChatById(orphanChatId, (source) => {
            const next = finalizeOrphanAgentExitChat(source, orphanRunId, {
              stats: orphanStats,
              exitCode: extractExitCode(payload) ?? 0,
              endedAt: new Date().toISOString()
            })
            // Mirror live exit: when seal and/or pending solo model apply
            // mutate the record, refresh composer selection for the open chat.
            if (next !== source) {
              finalizedOrphanChat = next
            }
            return next
          })
          if (finalizedOrphanChat && currentChatIdRef.current === orphanChatId) {
            applyChatComposerSelection(finalizedOrphanChat, getChatProvider(finalizedOrphanChat))
          }
          if (
            shouldPruneRunningChatIdAfterOrphanExit(
              orphanChatId,
              Array.from(activeRunsRef.current.values(), (run) => run.chatId)
            )
          ) {
            setRunningChatIds((prev) => {
              if (!prev.has(orphanChatId)) return prev
              const next = new Set(prev)
              next.delete(orphanChatId)
              return next
            })
          }
        }
        syncRunningState()
        return
      }

      context.adapter.end()
      const hasToolCalls = context.toolCallsCount > 0
      const exitCode = extractExitCode(payload) ?? 0
      const completedRunId = context.runId
      const wasIntentionalCancel = intentionalCancelRunIdsRef.current.delete(completedRunId)
      const completedRunChatId = context.chatId
      const completedScheduledTaskId = context.scheduledTaskId
      const completedRunDiffUnavailable = context.diffUnavailable
      const isGlobalCompletedRun = !context.baseWorkspacePath
      const suppressSteerSummary = steerSuppressedSummaryRunIdsRef.current.delete(completedRunId)
      const completedWorkspacePath =
        isGlobalCompletedRun || completedRunDiffUnavailable ? null : context.workspacePath
      const completedRunStartedAt = context.startedAt
      const completedRunExitStats =
        payload && typeof payload === 'object' ? (payload as RunRouteEventPayload).stats : undefined
      const isVisibleCompletedRun = () =>
        !completedRunChatId || currentChatIdRef.current === completedRunChatId
      updateRunQueueJobStatus(
        completedRunId,
        exitCode === 0 ? 'completed' : 'failed',
        exitCode === 0 ? 'Provider run completed.' : `Provider run exited with code ${exitCode}.`,
        exitCode === 0 ? undefined : `Run exited with code ${exitCode}`
      )
      if (!suppressSteerSummary) {
        handlers.triggerFxBurst('run-complete')
      }
      if (context.warnings.length > 0 && !suppressSteerSummary) {
        handlers.triggerFxBurst('run-summary')
      }
      if (isVisibleCompletedRun()) {
        setIsThinking(false)
      }

      let finalizedTerminalChat: ChatRecord | null = null
      // Runs that never emit run_finished (cancel, crash, provider exit) still
      // seal here — drop their live stream-metrics entry too.
      runStreamMetricsByRunIdRef.current.delete(completedRunId)
      updateChatById(completedRunChatId, (source) => {
        const updated = { ...source }

        const runs = [...(updated.runs || [])]
        const runIndex = runs.findIndex((run) => run.runId === completedRunId)
        const targetRun = runIndex >= 0 ? runs[runIndex] : undefined
        if (targetRun) {
          // Seal endedAt alongside status: deriveChatRunCompleteNotice treats
          // an un-ended last run as still-active and suppresses the Task
          // Complete card on every later re-derivation (chat switch, refresh,
          // hydrate-after-paint), even though status was stamped here.
          if (!targetRun.endedAt) targetRun.endedAt = new Date().toISOString()
          // Stamp over ANY non-terminal status, not just a missing one. A
          // premature Wire `result` (status 'running' — a turn boundary, not
          // completion) used to seal endedAt + status:'running' here-adjacent
          // in the run_finished handler, and this seal then fell through BOTH
          // branches ('success' upgrade / falsy stamp) and left the ghost
          // status 'running' on a finished run — the close-out read "The run
          // ended with status running" and the Task Complete receipts lost
          // their run-scoped window. Mirrors sealChatRunTerminalFields'
          // isActiveChatRunStatus semantics plus the adapter's 'unknown'
          // fallback; 'sleeping' is deliberately untouched (a parked wakeup
          // run is not an exit).
          if (
            !targetRun.status ||
            targetRun.status === 'unknown' ||
            isActiveChatRunStatus(targetRun.status)
          ) {
            targetRun.status = wasIntentionalCancel
              ? 'cancelled'
              : exitCode === 0
                ? context.warnings.length > 0
                  ? 'success_with_warnings'
                  : 'success'
                : 'failed'
          } else if (targetRun.status === 'success' && context.warnings.length > 0) {
            targetRun.status = 'success_with_warnings'
          }
          if (wasIntentionalCancel) {
            targetRun.cancelled = true
          }
          if (suppressSteerSummary) {
            targetRun.suppressRunSummary = true
          }
          // Normalise a user-cancel to the conventional SIGINT code so the
          // persisted run + re-derived run-complete card read "Stopped" on
          // reload, regardless of the real signal-kill exit the provider sent.
          targetRun.exitCode = wasIntentionalCancel ? 130 : exitCode || undefined
          targetRun.warnings = [...context.warnings]
          if (shouldBackfillRunStats(targetRun.stats, completedRunExitStats)) {
            targetRun.stats = completedRunExitStats
          }
        }
        updated.runs = runs

        const completedAt = new Date().toISOString()
        // Skip the per-participant run-complete notice for ensemble
        // chats — each participant's exit would clobber the card
        // with that participant's metadata. The notice fires once
        // per ROUND via the dedicated `activeRound.status` effect
        // below.
        const isEnsembleChat = updated.chatKind === 'ensemble'
        if (wasIntentionalCancel) {
          // User-intentional stop (steer or Stop): show the muted "Stopped"
          // card (exit 130) and skip the red failure message entirely, even
          // when the provider reported a non-zero/abnormal exit on the kill.
          if (!isEnsembleChat && isVisibleCompletedRun() && !suppressSteerSummary) {
            setRunCompleteNotice({
              timestamp: completedAt,
              exitCode: 130,
              startedAt: targetRun?.startedAt || completedRunStartedAt || undefined
            })
          }
        } else if (exitCode === 0) {
          if (!isEnsembleChat && isVisibleCompletedRun() && !suppressSteerSummary) {
            setRunCompleteNotice({
              timestamp: completedAt,
              exitCode,
              startedAt: targetRun?.startedAt || completedRunStartedAt || undefined
            })
          }
        } else if (exitCode !== 0) {
          // A failed run used to surface only a terse "Check Raw Events"
          // line with the exit code thrown away. Now we (a) raise the
          // run-complete card (same as success) so the outcome is
          // visible without digging into Raw Events, and (b) name the
          // exit code + last error line in the system message. Code 130
          // is the SIGINT a user Cancel produces — report it as a
          // cancellation, not a failure.
          if (!isEnsembleChat && isVisibleCompletedRun() && !suppressSteerSummary) {
            setRunCompleteNotice({
              timestamp: completedAt,
              exitCode,
              startedAt: targetRun?.startedAt || completedRunStartedAt || undefined
            })
          }
          const payloadError =
            payload && typeof payload === 'object'
              ? (payload as RunRouteEventPayload).error
              : undefined
          const stderrLogs = rawLogSnapshotForChat(completedRunChatId, true)
          const roundParticipant = updated.ensemble?.activeRound?.participants?.find(
            (entry) => entry.runId === completedRunId
          )
          const ensembleParticipant =
            updated.chatKind === 'ensemble' && updated.ensemble
              ? roundParticipant
                ? updated.ensemble.participants.find(
                    (participant) => participant.id === roundParticipant.participantId
                  )
                : updated.ensemble.participants.find(
                    (participant) => participant.provider === provider
                  )
              : undefined
          const failureModel =
            targetRun?.actualModel ||
            targetRun?.requestedModel ||
            roundParticipant?.model ||
            ensembleParticipant?.model ||
            ''
          const failureSnippet = buildProviderRunFailureSnippet({
            provider,
            exitCode,
            failureAt: completedAt,
            payloadError,
            warnings: targetRun?.warnings || context.warnings,
            stderrLogs,
            ensembleRole: ensembleParticipant?.role
          })
          const msgs = [
            ...updated.messages,
            {
              id: createMessageId(),
              role: 'error',
              content: failureSnippet.copyText,
              timestamp: completedAt,
              runId: completedRunId,
              metadata: {
                kind: 'providerRunFailure',
                provider,
                exitCode,
                failureAt: completedAt,
                headline: failureSnippet.headline,
                lines: failureSnippet.lines,
                ...(failureModel ? { model: failureModel } : {}),
                ...(failureSnippet.hint ? { hint: failureSnippet.hint } : {}),
                ...(ensembleParticipant
                  ? {
                      ensembleProvider: ensembleParticipant.provider,
                      ensembleRole: ensembleParticipant.role,
                      ensembleParticipantId: ensembleParticipant.id,
                      ...(failureModel ? { ensembleModel: failureModel } : {})
                    }
                  : {})
              }
            }
          ] as ChatMessage[]
          updated.messages = msgs
        }
        // `result` and `agent-exit` are independent IPC deliveries. The result
        // reducer normally owns queued solo-chat changes, but an exit without
        // that line is still a real turn boundary and must not strand them.
        const rosterFinalized = applyPendingEnsembleRosterPresetOnRunTerminal(
          updated,
          completedRunId
        )
        const terminalFinalized =
          rosterFinalized.chatKind === 'ensemble'
            ? rosterFinalized
            : applyPendingProviderChangeOnFinalize(rosterFinalized)
        if (terminalFinalized !== updated) {
          finalizedTerminalChat = terminalFinalized
        }
        return terminalFinalized
      })
      if (finalizedTerminalChat && currentChatIdRef.current === completedRunChatId) {
        applyChatComposerSelection(finalizedTerminalChat, getChatProvider(finalizedTerminalChat))
      }

      // Host-side compaction: consume a finished summarize run (store summary,
      // reset Cursor session, card), THEN — for ordinary exits — check whether
      // this chat just crossed the auto-compact threshold. Order matters: the
      // finalize consumes the pending record so a compaction run can never
      // re-trigger itself, and the trigger's own guards (cooldown, queue,
      // provider, percent) keep it a no-op everywhere else.
      handlers.finalizeHostCompactionRun(completedRunId, exitCode)
      handlers.maybeAutoCompactAfterRunExit(completedRunChatId, exitCode)

      // 1.0.6-TV7 — per-WRITE-workspace run diff summaries. Additive +
      // fully isolated from the primary snapshot diff below: derived
      // from the just-finalised chat's tool-reported changes (no
      // filesystem snapshot, no IPC), so a failure here can never block
      // or corrupt the authoritative primary-path diff. Stored on the
      // run as `runDiffByPath` for Diff Studio's Workspaces selector
      // (TV8); omitted entirely when no WRITE workspace changed.
      try {
        updateChatById(completedRunChatId, (source) => {
          const grants = normalizeExternalPathGrants(
            collectExternalPathGrantsFromMetadata(source.providerMetadata)
          )
          const byPath = buildRunDiffByPath(source.messages, grants, {
            runIds: [completedRunId],
            runs: source.runs
          })
          if (Object.keys(byPath).length === 0) return source
          const runs = [...(source.runs || [])]
          const idx = runs.findIndex((run) => run.runId === completedRunId)
          if (idx < 0) return source
          runs[idx] = { ...runs[idx], runDiffByPath: byPath }
          return { ...source, runs }
        })
      } catch {
        /* per-workspace diff is best-effort; never blocks the primary path */
      }

      if (completedRunDiffUnavailable) {
        if (isVisibleCompletedRun()) {
          setRunDiff(null)
          setDiffView('workspace')
          setDiff(createWorktreeDiffUnavailable())
          setDiffRefreshStatus('Diff disabled: worktree path unknown.')
        }
      } else if (
        !isGlobalCompletedRun &&
        completedWorkspacePath &&
        completedRunId &&
        context.preSnapshot
      ) {
        const completedPreSnapshot = context.preSnapshot
        window.api
          .captureSnapshot(completedWorkspacePath)
          .then((postSnapshot) => {
            window.api
              .computeRunDiff(completedRunId, completedPreSnapshot, postSnapshot, {
                chatId: completedRunChatId,
                workspaceId:
                  context.workspaceId || chatByIdRef.current.get(completedRunChatId)?.workspaceId,
                workspacePath: context.baseWorkspacePath!,
                effectiveWorkspacePath: completedWorkspacePath,
                provider,
                ...(context.worktree
                  ? {
                      worktree: {
                        enabled: Boolean(context.worktree.enabled),
                        name: context.worktree.name,
                        baseWorkspacePath: context.baseWorkspacePath!,
                        effectivePath: context.worktree.effectivePath || completedWorkspacePath
                      }
                    }
                  : {}),
                ...(provider === 'gemini'
                  ? {
                      checkpoint: {
                        enabled: Boolean(context.checkpointingEnabled),
                        provider: 'gemini' as const
                      }
                    }
                  : {}),
                metadata: {
                  scheduledTaskId: completedScheduledTaskId || undefined
                }
              })
              .then(async (rawRunDiffResult) => {
                // Non-git workspaces: snapshot diffs can't line-count
                // modified/deleted files — backfill from this run's
                // successful write-tool evidence so the File-changes card
                // and composer diff row show −M, not just created +N.
                const runDiffResult = backfillRunDiffCounts(
                  rawRunDiffResult,
                  toolEvidenceFromActivities(
                    (chatByIdRef.current.get(completedRunChatId)?.messages ?? [])
                      .filter((message) => message.runId === completedRunId)
                      .flatMap((message) => message.toolActivities ?? [])
                  )
                )
                updateChatById(completedRunChatId, (source) => {
                  const runs = [...(source.runs || [])]
                  const targetIndex = runs.findIndex((run) => run.runId === completedRunId)
                  if (targetIndex >= 0) {
                    runs[targetIndex].preSnapshot = completedPreSnapshot
                    runs[targetIndex].postSnapshot = postSnapshot
                    runs[targetIndex].runDiff = runDiffResult
                    runs[targetIndex].workspaceChangeSetId = runDiffResult.changeSetId
                  }
                  return { ...source, runs }
                })
                const allRunChanges = [
                  ...runDiffResult.createdFiles,
                  ...runDiffResult.modifiedFiles,
                  ...runDiffResult.deletedFiles
                ]
                if (isVisibleCompletedRun()) {
                  liveRunDiffStore.clear(completedRunChatId)
                  setRunDiff(handlers.getRunFileDiffSummaries(allRunChanges))
                  setDiffView('this_run')
                }
              })
              .catch(() => {
                if (isVisibleCompletedRun()) setDiffView('workspace')
              })
          })
          .catch(() => {
            if (isVisibleCompletedRun()) setDiffView('workspace')
          })
      } else if (!isGlobalCompletedRun && isVisibleCompletedRun()) {
        setDiffView('this_run')
      }

      if (isVisibleCompletedRun() && !completedRunDiffUnavailable) {
        handlers.refreshDiff().then(() => {
          if (hasToolCalls || exitCode === 0) {
            setDiffRefreshStatus('Diff refreshed after run.')
          }
        })
      }

      // Phase K1: stamp this chat as "recently completed" BEFORE we
      // clear the active-run context so onChatUpdated's stream-safe
      // merge keeps protecting the live tail for ~2s. Stragglers
      // (delegation card writes, debounced save-chat round-trips) can
      // arrive 1+ IPC ticks after exit and would otherwise replace
      // the live transcript with a disk-stale snapshot.
      if (completedRunChatId) {
        recentlyCompletedChatIdsRef.current.set(completedRunChatId, Date.now())
      }
      handlers.clearActiveRunContext(context)

      if (completedScheduledTaskId) {
        void window.api
          .updateScheduledTask(completedScheduledTaskId, {
            status: exitCode === 0 ? 'completed' : 'failed',
            completedAt: new Date().toISOString(),
            lastError: exitCode === 0 ? undefined : `Run exited with code ${exitCode}`
          })
          .then(async () => {
            const workspaceId = currentWorkspaceIdRef.current || undefined
            setScheduledTasks(await window.api.getScheduledTasks(workspaceId))
            setWorkflowDefinitions(await window.api.getWorkflowDefinitions(workspaceId))
          })
      }

      if (currentWorkspaceIdRef.current) {
        void handlers.refreshUsageSummary(currentWorkspaceIdRef.current)
      }
    }

    const ipcUnsubscriptions: Array<() => void> = []
    const approvalRecovery =
      typeof window.api.getPendingAgentApprovals === 'function'
        ? new PendingApprovalRecoveryWindow<AgentApprovalRequest>()
        : null
    const addIpcSubscription = (unsubscribe: (() => void) | null | undefined): void => {
      if (typeof unsubscribe === 'function') ipcUnsubscriptions.push(unsubscribe)
    }
    const resolveApprovalChatId = (request: AgentApprovalRequest): string | null => {
      const handlers = appEventHandlersRef.current
      const context = handlers.resolveActiveRunContext(
        request.provider,
        request.appRunId,
        request.appChatId
      )
      return context?.chatId || request.appChatId || currentChatIdRef.current
    }
    const presentLiveApprovalRequest = (request: AgentApprovalRequest): void => {
      const handlers = appEventHandlersRef.current
      const targetChatId = resolveApprovalChatId(request)
      if (targetChatId) approvalRecovery?.recordLive({ chatId: targetChatId, approval: request })
      // 1.0.4-AK4 — queue when an approval is already pending for
      // this chat. Pre-AK4 the second arrival would overwrite the
      // first (losing the user's chance to act on it). With AK5/AK6
      // parallel fan-out lanes each can produce their own approval gate
      // simultaneously; queueing keeps them all addressable.
      handlers.setPendingAgentApprovalForChat(targetChatId, (previous) => {
        // The recovery snapshot and live IPC can carry the same request in
        // either order. Never queue a duplicate behind itself.
        if (previous?.id === request.id) return previous
        if (previous && targetChatId) {
          handlers.enqueueApprovalForChat(targetChatId, request)
          return previous
        }
        return request
      })
      handlers.appendThreadRawLog(targetChatId, {
        type: 'info',
        content: `${getProviderLabel(request.provider)} approval requested: ${request.title}\n${request.body}`
      })
    }

    addIpcSubscription(
      window.api.onGeminiOutput((payload) => handleProviderOutput('gemini', payload))
    )
    addIpcSubscription(
      window.api.onGeminiError((payload) => handleProviderError('gemini', payload))
    )
    addIpcSubscription(window.api.onGeminiExit((payload) => handleProviderExit('gemini', payload)))

    if (typeof window.api.onAgentOutput === 'function') {
      addIpcSubscription(
        window.api.onAgentOutput((payload) => {
          if (payload?.provider === 'gemini') return
          handleProviderOutput(payload?.provider || 'codex', payload)
        })
      )
    }

    if (typeof window.api.onAgentError === 'function') {
      addIpcSubscription(
        window.api.onAgentError((payload) => {
          if (payload?.provider === 'gemini') return
          handleProviderError(payload?.provider || 'codex', payload)
        })
      )
    }

    if (typeof window.api.onAgentExit === 'function') {
      addIpcSubscription(
        window.api.onAgentExit((payload) => {
          if (payload?.provider === 'gemini') return
          handleProviderExit(payload?.provider || 'codex', payload)
        })
      )
    }

    if (typeof window.api.onAgentApprovalRequest === 'function') {
      addIpcSubscription(
        window.api.onAgentApprovalRequest(presentLiveApprovalRequest)
      )
    }

    if (typeof window.api.onAgentApprovalTimeout === 'function') {
      addIpcSubscription(
        window.api.onAgentApprovalTimeout((timeout) => {
          approvalRecovery?.recordSettled(timeout.approvalId)
          const handlers = appEventHandlersRef.current
          // Find which chat held this approval, clear it, and surface a
          // visible "auto-denied" note. The main process has already
          // dispatched action='decline' through the same processAgentApprovalResponse
          // path the renderer would use — this is just the UI tidy-up.
          // Raw-log uses `stderr` (red-toned in the existing UI) rather
          // than introducing a new `error` kind to the union.
          const matchedChatIds: string[] = []
          handlers.setPendingAgentApprovalByChatId((prev) => {
            const next: Record<string, AgentApprovalRequest | null> = {}
            for (const [chatId, request] of Object.entries(prev)) {
              if (request && request.id === timeout.approvalId) {
                matchedChatIds.push(chatId)
                next[chatId] = null
                handlers.appendThreadRawLog(chatId, {
                  type: 'stderr',
                  content: `Approval ${timeout.approvalId} auto-denied after ${(timeout.appliedMs / 1000).toFixed(0)}s (timeout). Run will need manual intervention if it stalled.`
                })
              } else {
                next[chatId] = request
              }
            }
            // No matching chat — log into the active chat as a fallback
            // so the user at least sees something happened.
            if (matchedChatIds.length === 0) {
              const fallbackChatId = currentChatIdRef.current
              if (fallbackChatId) {
                handlers.appendThreadRawLog(fallbackChatId, {
                  type: 'stderr',
                  content: `Approval ${timeout.approvalId} auto-denied after ${(timeout.appliedMs / 1000).toFixed(0)}s (timeout).`
                })
              }
            }
            return next
          })
          // 1.0.4-AK4 — advance queued approvals for any chat whose
          // head approval just timed out. The setState above runs
          // synchronously enough for our advance to see the cleared
          // head, but advanceApprovalQueueForChat reads from the
          // queue state (not the head), so order doesn't matter
          // here — it just promotes the next queued approval into
          // the head slot for each affected chat.
          for (const chatId of matchedChatIds) {
            handlers.advanceApprovalQueueForChat(chatId)
          }
        })
      )
    }

    if (typeof window.api.onAgentApprovalResolved === 'function') {
      addIpcSubscription(
        window.api.onAgentApprovalResolved((resolved) => {
          approvalRecovery?.recordSettled(resolved.approvalId)
          // Cross-surface acknowledgment: the approval was decided
          // SOMEWHERE — a paired iPhone, another window, or the auto-deny
          // timer — and main's ApprovalService has already executed the
          // decision. Tidy any modal still showing it here. Local clicks
          // and timeouts clear the head before this event lands, so those
          // paths fall through as no-ops.
          const handlers = appEventHandlersRef.current
          const matchedChatIds: string[] = []
          handlers.setPendingAgentApprovalByChatId((prev) => {
            const next: Record<string, AgentApprovalRequest | null> = {}
            for (const [chatId, request] of Object.entries(prev)) {
              if (request && request.id === resolved.approvalId) {
                matchedChatIds.push(chatId)
                next[chatId] = null
                handlers.appendThreadRawLog(chatId, {
                  type: 'info',
                  content: `Approval ${resolved.action || 'resolved'} from ${
                    resolved.decisionSource === 'system'
                      ? 'the auto-deny timer'
                      : 'a paired device or another window'
                  } — clearing this prompt.`
                })
              } else {
                next[chatId] = request
              }
            }
            return next
          })
          // Purge it from every queue tail too: an approval resolved
          // elsewhere while queued must never be promoted back into the
          // head as a zombie prompt.
          handlers.setPendingApprovalQueueByChatId((prev) => {
            let changed = false
            const next: Record<string, AgentApprovalRequest[]> = {}
            for (const [chatId, queue] of Object.entries(prev)) {
              const filtered = queue.filter((request) => request.id !== resolved.approvalId)
              if (filtered.length !== queue.length) changed = true
              next[chatId] = filtered
            }
            return changed ? next : prev
          })
          for (const chatId of matchedChatIds) {
            handlers.advanceApprovalQueueForChat(chatId)
          }
        })
      )
    }

    if (typeof window.api.getPendingAgentApprovals === 'function') {
      void window.api
        .getPendingAgentApprovals()
        .then((requests) => {
          if (!Array.isArray(requests)) return
          const recovered = requests
            .filter((request): request is AgentApprovalRequest => Boolean(request?.id))
            .map((request) => ({ chatId: resolveApprovalChatId(request), approval: request }))
            .filter(
              (entry): entry is { chatId: string; approval: AgentApprovalRequest } =>
                Boolean(entry.chatId)
            )
          const merged = approvalRecovery?.reconcile(recovered)
          if (!merged) return
          const handlers = appEventHandlersRef.current
          handlers.setPendingAgentApprovalByChatId(merged.approvalHeadByChatId)
          handlers.setPendingApprovalQueueByChatId(merged.approvalQueueByChatId)
        })
        .catch((error) => {
          console.warn('[approval-recovery] pending approval hydration failed', error)
        })
        .finally(() => {
          approvalRecovery?.finish()
        })
    }

    if (!isChatPopoutWindow && typeof window.api.onScheduledTasksChanged === 'function') {
      addIpcSubscription(
        window.api.onScheduledTasksChanged((tasks) => {
          setScheduledTasks(tasks)
        })
      )
    }

    if (!isChatPopoutWindow && typeof window.api.onWorkflowDefinitionsChanged === 'function') {
      addIpcSubscription(
        window.api.onWorkflowDefinitionsChanged((workflows) => {
          const workspaceId = currentWorkspaceIdRef.current || currentWorkspace?.id
          setWorkflowDefinitions(
            workspaceId
              ? workflows.filter((workflow) => workflow.workspaceId === workspaceId)
              : workflows
          )
        })
      )
    }

    if (
      !isChatPopoutWindow &&
      workspaceBoardApiReady &&
      typeof window.api.onWorkspaceBoardsChanged === 'function'
    ) {
      addIpcSubscription(
        window.api.onWorkspaceBoardsChanged((payload) => {
          setWorkspaceBoards(payload.boards)
          setWorkspaceBoardCards(payload.cards)
          setActiveWorkspaceBoardId((activeId) =>
            activeId && payload.boards.some((board) => board.id === activeId && !board.archived)
              ? activeId
              : null
          )
        })
      )
    }

    if (
      !isChatPopoutWindow &&
      evidencePackApiReady &&
      typeof window.api.onEvidencePacksChanged === 'function'
    ) {
      addIpcSubscription(
        window.api.onEvidencePacksChanged((payload) => {
          const workspaceId = currentWorkspaceIdRef.current || currentWorkspace?.id
          if (!workspaceId || payload.ledger.workspaceId === workspaceId) {
            setCapabilityLedgerSnapshot(payload.ledger)
          } else {
            void window.api
              .getCapabilityLedgerSnapshot(workspaceId)
              .then(setCapabilityLedgerSnapshot)
          }
        })
      )
    }

    if (typeof window.api.onUsageChanged === 'function') {
      // Live-refresh the usage meters the moment a run records usage, rather
      // than waiting for the 90s poll.
      addIpcSubscription(
        window.api.onUsageChanged(() => {
          if (!usageRefreshInFlightRef.current) {
            usageRefreshInFlightRef.current = true
            usageRefreshLastFiredAtRef.current = Date.now()
            // forceUsageRecords (NOT force): the just-recorded run must show
            // up now — bypass the 30s records cache and seed it fresh for
            // the other consumers reacting to this same broadcast — but do
            // not force the provider quota meters (their TTLs guard against
            // per-run endpoint hammering).
            void refreshUsageSummaryRef
              .current?.(currentWorkspaceIdRef.current || undefined, undefined, undefined, {
                forceUsageRecords: true
              })
              .catch(() => {})
              .finally(completeUsageRefresh)
          } else {
            usageRecordsRefreshPendingRef.current = true
          }
          // Nudge the sidebar API-spend view to re-query the priced records.
          setUsageRefreshTick((tick) => tick + 1)
        })
      )
    }

    if (typeof window.api.onExternalUsageUpdated === 'function') {
      // Main's external-activity cache upgraded (cold 14-day partial → full
      // 90-day window, or Cursor chunks merged). Drop the renderer's 30-min
      // external cache so the next pull re-fetches, then bump the welcome
      // heatmap refresh key to trigger that pull. Cheap: the main-side cache
      // is warm, so the re-pull is an in-memory IPC round trip.
      addIpcSubscription(
        window.api.onExternalUsageUpdated(() => {
          invalidateRendererUsageRecords('external')
          setExternalUsageVersion((version) => version + 1)
        })
      )
    }

    if (typeof window.api.onChatUpdated === 'function') {
      // Phase F2: when the main process updates a chat (sub-thread
      // result back-propagation in particular), splice the fresh
      // record into our local state so the user sees the synthetic
      // "↩ Result from X" message without a manual reload.
      //
      // Phase J2: previously this handler returned `prev` unchanged
      // when the broadcast chat wasn't already in state — meaning a
      // brand-new sub-thread chat (broadcast right after the
      // delegation approval) was silently dropped, and the sidebar
      // only caught up on the next full `getChats()` poll. INSERT
      // when not found so newly-spawned sub-threads appear in the
      // sidebar within a single render frame. The companion sidebar
      // auto-expand for the parent workspace lives inside Sidebar.tsx
      // (it diffs `chats` against a ref of previously-seen
      // appChatIds), so when a sub-thread is added here the workspace
      // group containing its parent auto-expands too.
      addIpcSubscription(
        window.api.onChatUpdated((delivery) => {
          const diagnosticCounters = rendererChatUpdateCountersRef.current
          diagnosticCounters.received += 1
          if (delivery.kind === 'snapshot') diagnosticCounters.snapshots += 1
          else diagnosticCounters.patches += 1
          const baselines = chatUpdateBaselineByIdRef.current
          const acknowledge = (wasApplied: boolean, appliedBaseline?: ChatUpdateBaseline): void => {
            if (!wasApplied) baselines.delete(delivery.chatId)
            if (!wasApplied) diagnosticCounters.applyFailures += 1
            // ACK means the revision was validated and accepted into renderer
            // state. Waiting for requestAnimationFrame made progress depend on
            // paint: under GC/render pressure (or a throttled hidden window),
            // the frame never arrived, main retained one in-flight delivery,
            // and every later transcript/tool patch was intentionally withheld.
            // Main still caps accepted traffic at 10 Hz and keeps only latest.
            // T6c: successful ACKs carry revision + recordHash so main can keep
            // a compact hash+generation baseline without a third full ChatRecord.
            if (typeof window.api.ackChatUpdated === 'function') {
              window.api.ackChatUpdated(
                buildChatUpdateAck({
                  delivery,
                  applied: wasApplied,
                  phase: 'accepted',
                  rendererEpoch: RENDERER_CHAT_UPDATE_EPOCH,
                  appliedChat: appliedBaseline?.chat,
                  appliedRecordHash: appliedBaseline?.recordHash,
                  appliedTranscriptHash: appliedBaseline?.transcriptHash
                })
              )
              diagnosticCounters.acksSent += 1
            }
          }
          const previousBaseline = baselines.get(delivery.chatId)
          const applied = applyChatUpdateDelivery(delivery, previousBaseline)
          if (!applied.ok) {
            acknowledge(false)
            return
          }
          const chat = applied.baseline.chat
          // Delete + set makes insertion order an LRU. Bounding this map avoids
          // retaining full transcripts for every chat visited during a long app
          // session while preserving exact bases for currently active updates.
          baselines.delete(chat.appChatId)
          baselines.set(chat.appChatId, applied.baseline)
          while (baselines.size > 32) {
            const oldestChatId = baselines.keys().next().value
            if (typeof oldestChatId !== 'string') break
            chatHydrationRuntime.retention.dropTransportBaseline(oldestChatId)
          }
          if (
            clearedChatIdsRef.current.has(chat.appChatId) &&
            !chatByIdRef.current.has(chat.appChatId)
          ) {
            pendingMainChatUpdatesRef.current.delete(chat.appChatId)
            pendingChatFlushRef.current.delete(chat.appChatId)
            acknowledge(true, applied.baseline)
            // The chat was explicitly cleared, so no React row will commit.
            // Close the observational receipt immediately rather than leaving
            // diagnostics to report a permanently pending invisible render.
            if (typeof window.api.ackChatUpdated === 'function') {
              window.api.ackChatUpdated(
                buildChatUpdateRenderedAck(
                  createChatUpdateRenderReceipt(
                    delivery,
                    applied.baseline,
                    RENDERER_CHAT_UPDATE_EPOCH
                  )
                )
              )
            }
            return
          }
          const hasActiveRun = (() => {
            for (const ctx of activeRunsRef.current.values()) {
              if (ctx.chatId === chat.appChatId) return true
            }
            return false
          })()
          let hadRecentRun = false
          const completedAt = recentlyCompletedChatIdsRef.current.get(chat.appChatId)
          if (completedAt !== undefined) {
            if (Date.now() - completedAt < RECENTLY_COMPLETED_WINDOW_MS) {
              hadRecentRun = true
            } else {
              recentlyCompletedChatIdsRef.current.delete(chat.appChatId)
            }
          }
          // Keep this callback bounded: applying the transport patch and
          // queueing the exact accepted snapshot is enough for ACK. The live
          // transcript merge and React state writes run in the existing rAF
          // coalescer, so prompt input is not serialized behind them.
          const pendingRender = pendingMainChatUpdatesRef.current.get(chat.appChatId)
          pendingMainChatUpdatesRef.current.set(
            chat.appChatId,
            coalescePendingChatUpdateRender(pendingRender, {
              chat,
              messagesChanged: previousBaseline?.chat.messages !== chat.messages,
              hasActiveRun,
              hadRecentRun,
              renderReceipt: createChatUpdateRenderReceipt(
                delivery,
                applied.baseline,
                RENDERER_CHAT_UPDATE_EPOCH
              )
            })
          )
          scheduleCoalescedChatFlush(chat.appChatId)
          if (
            currentChatIdRef.current === chat.appChatId &&
            chat.chatKind === 'ensemble' &&
            isEnsembleActiveRoundDispatchLive(chat.ensemble?.activeRound)
          ) {
            setIsThinking(true)
          }
          acknowledge(true, applied.baseline)
          // ACK first so main can release its in-flight delivery, then make a
          // terminal round visible synchronously. The completion notice and
          // closeout effects must not depend on a future paint.
          if (shouldFlushChatUpdateImmediately(chat)) flushCoalescedChatsNow()
          return
        })
      )
    }

    // P2b auto-draft: a collaborator action request under autoDraft rules
    // pre-fills the composer draft with the wrapped, provenance-carrying text.
    // Display-only — nothing is sent or queued; the host reviews and sends.
    // NEVER clobbers a draft the host is already typing (functional update
    // keeps any non-empty draft; the request stays reviewable on its
    // transcript row via "Insert as draft").
    if (typeof window.api.onHumanCollaborationActionRequest === 'function') {
      addIpcSubscription(
        window.api.onHumanCollaborationActionRequest((payload) => {
          if (!payload?.chatId || typeof payload.draft !== 'string') return
          setComposerDraftForChat(payload.chatId, (previous) =>
            previous && previous.trim() ? previous : payload.draft
          )
        })
      )
    }

    // Trusted tool-result image and audio/video refs for a foreground solo run.
    // Main constructs these refs and pushes them on this dedicated main-only
    // channel, so unlike the forgeable provider `assistant_media_refs` lane we
    // attach them RAW: the sanitizer would cap temporal image batches and
    // hard-drop audio/video, and a provider's stdout cannot forge this IPC.
    // Keyed by appChatId (streamed assistant messages carry no runId); the
    // shared helper's append-new-assistant fallback covers the no-trailing-
    // assistant case, and mergeTranscriptMediaRefs dedupes redundant deliveries.
    if (typeof window.api.onRunTrustedMediaRefs === 'function') {
      addIpcSubscription(
        window.api.onRunTrustedMediaRefs((payload) => {
          if (
            !payload?.appChatId ||
            !Array.isArray(payload.mediaRefs) ||
            payload.mediaRefs.length === 0
          )
            return
          applyAssistantMediaRefsToChat(
            payload.appChatId,
            payload.mediaRefs as TranscriptMediaRef[]
          )
        })
      )
    }

    if (typeof window.api.onRunQueueChanged === 'function') {
      addIpcSubscription(
        window.api.onRunQueueChanged((jobs) => {
          setRunQueueJobs(jobs)
          const terminalRunIds = new Set(
            jobs
              .filter((job) => isTerminalRunQueueStatus(job.status))
              .map((job) => job.runId || job.id)
          )
          if (terminalRunIds.size > 0) {
            setQueuedRuns((previous) =>
              previous.filter(
                (request) => !request.appRunId || !terminalRunIds.has(request.appRunId)
              )
            )
            setFailedQueuedSteerRunIds((previous) => {
              if (![...terminalRunIds].some((runId) => previous.has(runId))) return previous
              const next = new Set(previous)
              for (const runId of terminalRunIds) next.delete(runId)
              return next
            })
          }
        })
      )
    }

    if (typeof window.api.onContextCompactionProgress === 'function') {
      addIpcSubscription(
        window.api.onContextCompactionProgress((event) => {
          if (!event?.chatId) return
          const key = contextCompactionProgressKey(event)
          const existingTimer = contextCompactionProgressTimersRef.current.get(key)
          if (existingTimer !== undefined) {
            window.clearTimeout(existingTimer)
            contextCompactionProgressTimersRef.current.delete(key)
          }
          if (event.status !== 'started') {
            setContextCompactionProgressByKey((prev) => {
              if (!prev[key]) return prev
              const { [key]: _drop, ...rest } = prev
              return rest
            })
            return
          }
          setContextCompactionProgressByKey((prev) => ({
            ...prev,
            [key]: { ...event, key, updatedAt: Date.now() }
          }))
          const timer = window.setTimeout(() => {
            contextCompactionProgressTimersRef.current.delete(key)
            setContextCompactionProgressByKey((prev) => {
              if (!prev[key]) return prev
              const { [key]: _drop, ...rest } = prev
              return rest
            })
          }, CONTEXT_COMPACTION_PROGRESS_STALE_MS)
          contextCompactionProgressTimersRef.current.set(key, timer)
        })
      )
    }

    // Legacy global auto-approval indicator. Main refuses new enable requests,
    // but we still read the current value in case multiple windows are attached
    // to a process with an older/global bypass already active.
    if (!isChatPopoutWindow && typeof window.api.agenticYoloGet === 'function') {
      window.api
        .agenticYoloGet()
        .then((state) => setSessionYoloModeState(state))
        .catch(() => {})
    }
    if (!isChatPopoutWindow && typeof window.api.onAgenticYoloState === 'function') {
      addIpcSubscription(window.api.onAgenticYoloState((state) => setSessionYoloModeState(state)))
    }

    // QMOD (1.0.3) — listen for `ask_user_question` MCP-driven question
    // requests from main. When an agent calls the tool, main fires this
    // event with the question payload; we materialise a synthetic
    // system message in the chat (so the question appears in-line with
    // the conversation) and stash the metadata in per-chat state so the
    // transcript renderer can show the modal card next to it.
    if (typeof window.api.onAgentQuestionRequested === 'function') {
      addIpcSubscription(
        window.api.onAgentQuestionRequested((request) => {
          const messageId = `agent-question-${request.questionId}`
          // Insert a synthetic system message into the chat's transcript
          // marking the question. Persisted in `chat.messages` so the
          // question + answer trail survives chat reloads. The transcript
          // renderer keys off `metadata.kind === 'agentQuestion'` to
          // render the modal card next to this message.
          updateChatById(request.appChatId, (prev) => {
            // Avoid duplicating the marker on re-fires (e.g. main retries
            // an event after a renderer reload). We key on questionId.
            if (prev.messages?.some((msg) => msg.id === messageId)) return prev
            const askedAt = new Date().toISOString()
            const provider = (request.provider as ProviderId | undefined) ?? null
            const headerProvider = provider ? getProviderLabel(provider) : 'Agent'
            const headerLine = request.options?.length
              ? `${headerProvider} asked you to pick an option:`
              : `${headerProvider} asked you a question:`
            // Stamp the ACTIVE ensemble round id so the marker groups with the
            // live round (groupEnsembleMessagesByRound keys on ensembleRoundId)
            // instead of rendering as a detached, adjacency-breaking "System"
            // block separated from the current participant's turn.
            const activeRoundId = prev.ensemble?.activeRound?.roundId
            const next: ChatMessage = {
              id: messageId,
              role: 'system',
              content: headerLine,
              timestamp: askedAt,
              ...(request.appRunId ? { runId: request.appRunId } : {}),
              metadata: {
                kind: 'agentQuestion',
                questionId: request.questionId,
                ensembleProvider: provider || undefined,
                agentQuestion: request.question,
                agentQuestionOptions: request.options,
                agentQuestionContext: request.context,
                ...(activeRoundId ? { ensembleRoundId: activeRoundId } : {})
              }
            }
            return { ...prev, messages: [...(prev.messages || []), next] }
          })
          setPendingAgentQuestionsForChat(request.appChatId, (prev) =>
            enqueueAgentQuestion(prev, {
              questionId: request.questionId,
              appRunId: request.appRunId,
              messageId,
              provider: (request.provider as ProviderId | undefined) ?? null,
              question: request.question,
              options: request.options,
              context: request.context,
              askedAt: Date.now()
            })
          )
          // In-app attention when the user is not already looking at this
          // thread. The in-transcript card still mounts when they open it;
          // the banner is the place-marker + deep-link for elsewhere.
          const viewingChatId = currentChatIdRef.current
          if (request.appChatId && request.appChatId !== viewingChatId) {
            const chatTitle = chatByIdRef.current.get(request.appChatId)?.title
            needsInputBannerRef.current.push({
              questionId: request.questionId,
              appChatId: request.appChatId,
              chatTitle,
              provider: (request.provider as ProviderId | undefined) ?? null,
              question: request.question,
              options: request.options,
              context: request.context,
              askedAt: Date.now()
            })
          }
        })
      )
    }
    if (typeof window.api.onAgentQuestionCancelled === 'function') {
      addIpcSubscription(
        window.api.onAgentQuestionCancelled((info) => {
          // Clear the pending-question slot for the chat that owned the
          // question. appChatId comes back on the cancellation payload so
          // we don't have to maintain our own questionId → chatId map.
          needsInputBannerRef.current.dismiss(info.questionId)
          if (info.appChatId) {
            setPendingAgentQuestionsForChat(info.appChatId, (prev) =>
              removeAgentQuestionFromQueue(prev, info.questionId)
            )
          }
        })
      )
    }

    ipcUnsubscriptions.unshift(() => {
      approvalRecovery?.cancel()
      for (const timer of contextCompactionProgressTimersRef.current.values()) {
        window.clearTimeout(timer)
      }
      contextCompactionProgressTimersRef.current.clear()
    })
    return ipcUnsubscriptions
  })

  const currentGeminiWorktree =
    currentProvider === 'gemini' ? resolveGeminiWorktreeConfig(currentWorkspace) : undefined
  const activeDiff = isGeminiWorktreeDiffUnavailable(currentGeminiWorktree)
    ? createWorktreeDiffUnavailable()
    : diffView === 'this_run' && runDiff
      ? { type: 'changes', summaries: runDiff }
      : diff

  const getRunQueueSource = (request: QueuedRunRequest): RunQueueJobSource => {
    if (request.scheduledRunAt) return 'scheduled'
    if (request.scheduledTaskId) return 'scheduled'
    if (request.codexNativeReview) return 'review'
    if (request.existingPrompt) return 'retry'
    return 'manual'
  }

  const normalizeScheduledQueueRunAt = (value: string): string | null => {
    if (!value) return null
    const runAtMs = new Date(value).getTime()
    if (!Number.isFinite(runAtMs) || runAtMs <= Date.now()) return null
    return new Date(runAtMs).toISOString()
  }

  const getScheduledQueueRunAtMs = (
    request: Pick<QueuedRunRequest, 'scheduledRunAt'>
  ): number | null => {
    if (!request.scheduledRunAt) return null
    const runAtMs = new Date(request.scheduledRunAt).getTime()
    return Number.isFinite(runAtMs) ? runAtMs : null
  }

  const isQueuedRunReadyToDispatch = (request: QueuedRunRequest, nowMs = Date.now()): boolean => {
    const runAtMs = getScheduledQueueRunAtMs(request)
    return runAtMs === null || runAtMs <= nowMs
  }

  /**
   * Expected renderer -> preload API contract for solo queued-row steer
   * promotion.
   *
   * Upstream names this as `promoteQueuedRunForSteer`. In this fork, the
   * legacy API name `promoteQueuedJobForSteer` may still be present.
   *
   * Input:
   *   - runId: The queue row to promote.
   *   - provider?: Chat provider for coordinator bookkeeping.
   *   - chatId?: Target chat for the row (telemetry + anti-mismatch guard).
   *   - statusReason?: Human-readable reason for the transition.
   *   - queueMessageId?: Optional queue-entry id for diagnostics.
   *   - transitionVersion?: Optional queue-coordinator transition token.
   *   - ownerToken?: Optional caller-owned key for coordinator pairing.
   *   - cancelRunId/cancelProvider?: Optional active run that main should
   *     intentionally cancel only after reserving the queued row.
   *
   * Output:
   *   - ok === true/kind === 'dispatch-permission': includes a runnable
   *     request snapshot and optional promotionToken/ownerToken.
   *   - ok === false/kind === 'fallback': includes reason and may still
   *     include request to keep user-visible row for retry.
   */
  type PromoteQueuedRunForSteerInput = {
    runId: string
    prepareJob?: Partial<RunQueueJob> & Pick<RunQueueJob, 'runId' | 'provider' | 'source'>
    provider?: ProviderId
    chatId?: string
    statusReason?: string
    queueMessageId?: string
    transitionVersion?: number
    ownerToken?: string
    cancelRunId?: string
    cancelProvider?: ProviderId
  }
  type PromoteQueuedRunForSteerResponse = {
    ok?: boolean
    kind?: string
    request?: RunQueueRequestSnapshot
    promotionToken?: string
    ownerToken?: string
    reason?: string
    runId?: string
    jobStatus?: RunQueueJobStatus
    cancelRequested?: boolean
    requeuedTo?: 'queued'
    status?: RunQueueJobStatus
  }

  const invokePromoteQueuedRunForSteer = async (
    input: PromoteQueuedRunForSteerInput
  ): Promise<PromoteQueuedRunForSteerResponse | null> => {
    const modernApi = (
      window.api as {
        promoteQueuedRunForSteer?: (
          request: PromoteQueuedRunForSteerInput
        ) => Promise<PromoteQueuedRunForSteerResponse> | PromoteQueuedRunForSteerResponse
      }
    ).promoteQueuedRunForSteer
    const legacyApi = (
      window.api as {
        promoteQueuedJobForSteer?: (
          request: PromoteQueuedRunForSteerInput
        ) => Promise<PromoteQueuedRunForSteerResponse> | PromoteQueuedRunForSteerResponse
      }
    ).promoteQueuedJobForSteer
    const promotionApi = typeof modernApi === 'function' ? modernApi : legacyApi
    if (typeof promotionApi !== 'function') return null

    try {
      const result = await promotionApi(input)
      if (!result || typeof result !== 'object') return null
      const response = result as Record<string, unknown>
      const rawRequest = response.request
      const request =
        rawRequest && typeof rawRequest === 'object' && !Array.isArray(rawRequest)
          ? (rawRequest as RunQueueRequestSnapshot)
          : undefined
      return {
        ok: typeof response.ok === 'boolean' ? response.ok : undefined,
        kind: typeof response.kind === 'string' ? response.kind : undefined,
        request,
        promotionToken:
          typeof response.promotionToken === 'string' ? response.promotionToken : undefined,
        ownerToken: typeof response.ownerToken === 'string' ? response.ownerToken : undefined,
        reason: typeof response.reason === 'string' ? response.reason : undefined,
        runId: typeof response.runId === 'string' ? response.runId : undefined,
        jobStatus:
          typeof response.jobStatus === 'string'
            ? (response.jobStatus as RunQueueJobStatus)
            : undefined,
        cancelRequested:
          typeof response.cancelRequested === 'boolean' ? response.cancelRequested : undefined,
        requeuedTo: response.requeuedTo === 'queued' ? 'queued' : undefined,
        status:
          typeof response.status === 'string' ? (response.status as RunQueueJobStatus) : undefined
      }
    } catch (error) {
      console.warn('[queued-steer] promoteQueuedRunForSteer failed', error)
      return null
    }
  }

  const invokeLeasePromotedSteerJob = async (input: {
    runId: string
    ownerToken: string
    statusReason?: string
  }): Promise<{
    ok?: boolean
    kind?: string
    request?: RunQueueRequestSnapshot
    ownerToken?: string
    status?: RunQueueJobStatus
  } | null> => {
    const maybeApi = window.api as {
      leasePromotedSteerJob?: (input: {
        runId: string
        ownerToken: string
        statusReason?: string
      }) => Promise<{
        ok?: boolean
        kind?: string
        request?: RunQueueRequestSnapshot
        ownerToken?: string
        status?: RunQueueJobStatus
      }>
    }
    if (typeof maybeApi.leasePromotedSteerJob !== 'function') return null
    try {
      return await maybeApi.leasePromotedSteerJob(input)
    } catch (error) {
      console.warn('[queued-steer] leasePromotedSteerJob failed', error)
      return null
    }
  }

  const invokeFallbackPromotedSteerJob = async (input: {
    runId: string
    ownerToken: string
    reason: string
    fallbackStatus?: 'queued' | 'cancelled' | 'failed'
  }): Promise<{ ok?: boolean; jobStatus?: RunQueueJobStatus; reason?: string } | null> => {
    const maybeApi = window.api as {
      fallbackPromotedSteerJob?: (input: {
        runId: string
        ownerToken: string
        reason: string
        fallbackStatus?: 'queued' | 'cancelled' | 'failed'
      }) => Promise<{ ok?: boolean; jobStatus?: RunQueueJobStatus; reason?: string }>
    }
    if (typeof maybeApi.fallbackPromotedSteerJob !== 'function') return null
    try {
      return await maybeApi.fallbackPromotedSteerJob(input)
    } catch (error) {
      console.warn('[queued-steer] fallbackPromotedSteerJob failed', error)
      return null
    }
  }

  const buildSteerQueuedRunRequest = (
    snapshot: RunQueueRequestSnapshot | undefined,
    fallbackRequest: QueuedRunRequest
  ): QueuedRunRequest => {
    if (!snapshot) return fallbackRequest
    return {
      ...fallbackRequest,
      prompt: snapshot.prompt,
      ...(snapshot.displayPrompt ? { displayPrompt: snapshot.displayPrompt } : {}),
      dmTargetParticipantId: snapshot.dmTargetParticipantId,
      exactPickerParticipantId: snapshot.exactPickerParticipantId,
      selectedModelType: snapshot.selectedModelType || fallbackRequest.selectedModelType,
      customModel: snapshot.customModel || fallbackRequest.customModel,
      approvalMode: snapshot.approvalMode || fallbackRequest.approvalMode,
      workflowMode: snapshot.workflowMode || fallbackRequest.workflowMode,
      sessionTrust:
        typeof snapshot.sessionTrust === 'boolean'
          ? snapshot.sessionTrust
          : fallbackRequest.sessionTrust,
      effectiveWorkspacePath: restoreQueuedRunWorktreeTarget(snapshot),
      imageAttachments: snapshot.imageAttachments.length
        ? snapshot.imageAttachments.map((attachment, index) => ({
            id:
              attachment.id || `${fallbackRequest.appRunId || 'queued-steer'}-attachment-${index}`,
            path: attachment.path,
            name: attachment.name || getImageName(attachment.path),
            ...attachmentKindMetadata(attachment),
            ...persistedAttachmentMetadata(attachment)
          }))
        : fallbackRequest.imageAttachments,
      ...(snapshot.discordContextSelection
        ? { discordContextSelection: snapshot.discordContextSelection }
        : {}),
      ...(snapshot.projectReferenceContextSelection
        ? { projectReferenceContextSelection: snapshot.projectReferenceContextSelection }
        : {}),
      ...(snapshot.externalPathGrants ? { externalPathGrants: snapshot.externalPathGrants } : {}),
      ...(snapshot.geminiWorktree ? { geminiWorktree: snapshot.geminiWorktree } : {}),
      ...(snapshot.codexNativeReview ? { codexNativeReview: true } : {}),
      ...(snapshot.codexReasoningEffort !== undefined
        ? { codexReasoningEffort: snapshot.codexReasoningEffort }
        : {}),
      ...(snapshot.codexServiceTier !== undefined
        ? { codexServiceTier: snapshot.codexServiceTier }
        : {}),
      ...(snapshot.claudeReasoningEffort !== undefined
        ? { claudeReasoningEffort: snapshot.claudeReasoningEffort }
        : {}),
      ...(snapshot.claudeFastMode !== undefined ? { claudeFastMode: snapshot.claudeFastMode } : {}),
      ...(snapshot.kimiFastMode !== undefined ? { kimiFastMode: snapshot.kimiFastMode } : {}),
      ...(snapshot.kimiReasoningEffort !== undefined
        ? { kimiReasoningEffort: snapshot.kimiReasoningEffort }
        : {}),
      ...(snapshot.kimiThinkingEnabled !== undefined
        ? { kimiThinkingEnabled: snapshot.kimiThinkingEnabled }
        : {}),
      ...(snapshot.grokReasoningEffort !== undefined
        ? { grokReasoningEffort: snapshot.grokReasoningEffort }
        : {}),
      ...(snapshot.museReasoningEffort !== undefined
        ? { museReasoningEffort: snapshot.museReasoningEffort }
        : {}),
      ...(snapshot.mistralReasoningEffort !== undefined
        ? { mistralReasoningEffort: snapshot.mistralReasoningEffort }
        : {}),
      ...(snapshot.piReasoningEffort !== undefined
        ? { piReasoningEffort: snapshot.piReasoningEffort }
        : {}),
      ...(snapshot.antigravityReasoningEffort !== undefined
        ? { antigravityReasoningEffort: snapshot.antigravityReasoningEffort }
        : {}),
      ...(snapshot.cursorReasoningEffort !== undefined
        ? { cursorReasoningEffort: snapshot.cursorReasoningEffort }
        : {}),
      ...(snapshot.cursorFastMode !== undefined ? { cursorFastMode: snapshot.cursorFastMode } : {}),
      ...(snapshot.scheduledTaskId ? { scheduledTaskId: snapshot.scheduledTaskId } : {}),
      ...(snapshot.scheduledRunAt ? { scheduledRunAt: snapshot.scheduledRunAt } : {}),
      ...(snapshot.runtimeProfileId ? { runtimeProfileId: snapshot.runtimeProfileId } : {}),
      ...(snapshot.geminiAuthProfileId
        ? { geminiAuthProfileId: snapshot.geminiAuthProfileId }
        : {}),
      ...(snapshot.handoffSourceRunId ? { handoffSourceRunId: snapshot.handoffSourceRunId } : {})
    }
  }

  const attachSteerMetadataToRequest = (
    request: QueuedRunRequest,
    promotionToken?: string,
    ownerToken?: string
  ): QueuedRunRequest => {
    if (!promotionToken && !ownerToken) return request
    return {
      ...request,
      ...(promotionToken
        ? ({ steerPromotionToken: promotionToken } as Record<string, string>)
        : {}),
      ...(ownerToken ? ({ steerOwnerToken: ownerToken } as Record<string, string>) : {})
    } as QueuedRunRequest
  }

  const restoreQueuedRunForSteer = (request: QueuedRunRequest): void => {
    setQueuedRuns((prev) => {
      const requestKey = request.appRunId
      const exists = prev.some((existing) => {
        if (requestKey) {
          return existing.appRunId === requestKey
        }
        return (
          existing.prompt === request.prompt &&
          queuedRunFallbackId(existing) === queuedRunFallbackId(request)
        )
      })
      if (exists) return prev
      return [...prev, request]
    })
  }

  const createRunQueueRequestSnapshot = (request: QueuedRunRequest): RunQueueRequestSnapshot => ({
    scope: request.scope || getChatScope(request.chatRecord || currentChat),
    prompt: request.prompt,
    ...(request.displayPrompt ? { displayPrompt: request.displayPrompt } : {}),
    ...(request.dmTargetParticipantId
      ? { dmTargetParticipantId: request.dmTargetParticipantId }
      : {}),
    ...(request.exactPickerParticipantId
      ? { exactPickerParticipantId: request.exactPickerParticipantId }
      : {}),
    selectedModelType: request.selectedModelType,
    customModel: request.customModel,
    approvalMode: request.approvalMode,
    ...(request.permissionPresetId ? { permissionPresetId: request.permissionPresetId } : {}),
    ...(request.workflowMode ? { workflowMode: request.workflowMode } : {}),
    sessionTrust: request.sessionTrust,
    imageAttachments: request.imageAttachments.map((attachment) => ({
      id: attachment.id,
      path: attachment.path,
      name: attachment.name,
      ...attachmentKindMetadata(attachment),
      ...persistedAttachmentMetadata(attachment)
    })),
    ...(request.discordContextSelection
      ? { discordContextSelection: request.discordContextSelection }
      : {}),
    ...(request.projectReferenceContextSelection
      ? { projectReferenceContextSelection: request.projectReferenceContextSelection }
      : {}),
    ...(request.externalPathGrants?.length
      ? { externalPathGrants: request.externalPathGrants }
      : {}),
    ...(request.geminiWorktree ? { geminiWorktree: request.geminiWorktree } : {}),
    ...(request.codexNativeReview ? { codexNativeReview: true } : {}),
    ...(request.codexReasoningEffort !== undefined
      ? { codexReasoningEffort: request.codexReasoningEffort }
      : {}),
    ...(request.codexServiceTier !== undefined
      ? { codexServiceTier: request.codexServiceTier }
      : {}),
    ...(request.claudeReasoningEffort !== undefined
      ? { claudeReasoningEffort: request.claudeReasoningEffort }
      : {}),
    ...(request.claudeFastMode !== undefined ? { claudeFastMode: request.claudeFastMode } : {}),
    ...(request.kimiFastMode !== undefined ? { kimiFastMode: request.kimiFastMode } : {}),
    ...(request.kimiReasoningEffort !== undefined
      ? { kimiReasoningEffort: request.kimiReasoningEffort }
      : {}),
    ...(request.kimiThinkingEnabled !== undefined
      ? { kimiThinkingEnabled: request.kimiThinkingEnabled }
      : {}),
    ...(request.grokReasoningEffort !== undefined
      ? { grokReasoningEffort: request.grokReasoningEffort }
      : {}),
    ...(request.museReasoningEffort !== undefined
      ? { museReasoningEffort: request.museReasoningEffort }
      : {}),
    ...(request.mistralReasoningEffort !== undefined
      ? { mistralReasoningEffort: request.mistralReasoningEffort }
      : {}),
    ...(request.piReasoningEffort !== undefined
      ? { piReasoningEffort: request.piReasoningEffort }
      : {}),
    ...(request.antigravityReasoningEffort !== undefined
      ? { antigravityReasoningEffort: request.antigravityReasoningEffort }
      : {}),
    ...(request.ollamaReasoningEffort !== undefined
      ? { ollamaReasoningEffort: request.ollamaReasoningEffort }
      : {}),
    ...(request.cursorReasoningEffort !== undefined
      ? { cursorReasoningEffort: request.cursorReasoningEffort }
      : {}),
    ...(request.cursorFastMode !== undefined ? { cursorFastMode: request.cursorFastMode } : {}),
    ...(request.scheduledTaskId ? { scheduledTaskId: request.scheduledTaskId } : {}),
    ...(request.scheduledRunAt ? { scheduledRunAt: request.scheduledRunAt } : {}),
    ...snapshotQueuedRunWorktreeTarget(request.effectiveWorkspacePath),
    ...(request.runtimeProfileId ? { runtimeProfileId: request.runtimeProfileId } : {}),
    ...(request.geminiAuthProfileId ? { geminiAuthProfileId: request.geminiAuthProfileId } : {}),
    ...(request.handoffSourceRunId ? { handoffSourceRunId: request.handoffSourceRunId } : {}),
    ...(request.preserveComposer ? { preserveComposer: true } : {})
  })

  const buildRunQueueJobInputForRequest = (
    request: QueuedRunRequest,
    status: RunQueueJobStatus,
    statusReason?: string
  ): (Partial<RunQueueJob> & Pick<RunQueueJob, 'runId' | 'provider' | 'source'>) | null => {
    const workspace =
      request.workspaceRecord || getWorkspaceForChat(request.chatRecord) || currentWorkspace
    const chat = request.chatRecord || currentChat
    const scope = request.scope || getChatScope(chat)
    const runId = request.appRunId
    if (!runId || !chat) return null
    if (scope !== 'global' && !workspace) return null
    return {
      id: runId,
      runId,
      provider: request.provider,
      scope,
      ...(scope === 'global' ? {} : { workspaceId: workspace!.id, workspacePath: workspace!.path }),
      chatId: chat.appChatId,
      source: getRunQueueSource(request),
      status,
      promptPreview: runRequestPromptPreview(request),
      runtimeProfileId: request.runtimeProfileId,
      handoffSourceRunId: request.handoffSourceRunId,
      request: createRunQueueRequestSnapshot(request),
      ...(statusReason ? { statusReason } : {})
    }
  }

  const persistRunQueueJobForRequest = (
    request: QueuedRunRequest,
    status: RunQueueJobStatus,
    statusReason?: string
  ): Promise<RunQueueJob | null> => {
    const input = buildRunQueueJobInputForRequest(request, status, statusReason)
    return input ? window.api.requestRunQueueJob(input) : Promise.resolve(null)
  }

  const updateRunQueueJobStatus = (
    runId: string | undefined,
    status: RunQueueJobStatus,
    statusReason?: string,
    lastError?: string
  ) => {
    if (!runId) return
    const existing = runQueueJobsRef.current.find((job) => job.runId === runId || job.id === runId)
    if (existing && isTerminalRunQueueStatus(existing.status) && isTerminalRunQueueStatus(status)) {
      return
    }
    window.api
      .transitionRunQueueJob(runId, status, {
        ...(statusReason ? { statusReason } : {}),
        ...(lastError ? { lastError } : {})
      })
      .catch(() => {})
  }

  const queuedRunRequestFromJob = (
    job: RunQueueJob,
    workspaceList: WorkspaceRecord[],
    chatList: ChatRecord[],
    options: { allowPreparedSoloSteer?: boolean } = {}
  ): QueuedRunRequest | null => {
    const runnable =
      job.status === 'queued' ||
      Boolean(options.allowPreparedSoloSteer && isPreparedSoloSteerQueueJob(job))
    if (!runnable || !job.request) return null
    const workspaceRecord = workspaceList.find(
      (workspace) => workspace.id === job.workspaceId || workspace.path === job.workspacePath
    )
    const chatRecord = chatList.find((chat) => chat.appChatId === job.chatId)
    if (!chatRecord) return null
    const isExecutionGraphJob = Boolean(job.executionGraph)
    const hasQueuedProviderChange = Boolean(
      !isExecutionGraphJob && chatRecord && hasPendingProviderChange(chatRecord)
    )
    const queuedProviderBaseChat = hasQueuedProviderChange
      ? applyPendingProviderChangeOnFinalize(chatRecord)
      : chatRecord
    const queuedProviderSelection = hasQueuedProviderChange
      ? getChatComposerSelection(queuedProviderBaseChat)
      : null
    const effectiveProvider = queuedProviderSelection?.provider || job.provider
    const scope =
      job.scope === 'global' || job.request.scope === 'global' || isGlobalChat(chatRecord)
        ? 'global'
        : 'workspace'
    if (scope !== 'global' && !workspaceRecord) return null
    const request = job.request
    const selectedModel = isExecutionGraphJob
      ? request.selectedModelType
      : queuedProviderSelection
        ? queuedProviderSelection.selectedModelType
        : isValidModelForProvider(job.provider, request.selectedModelType)
          ? request.selectedModelType
          : getDefaultModelForProvider(job.provider)
    return {
      appRunId: job.runId,
      scope,
      provider: effectiveProvider,
      prompt: request.prompt,
      displayPrompt: request.displayPrompt,
      selectedModelType: selectedModel,
      customModel: queuedProviderSelection?.customModel ?? request.customModel,
      approvalMode: queuedProviderSelection?.approvalMode ?? request.approvalMode,
      permissionPresetId: queuedProviderSelection?.permissionPresetId ?? request.permissionPresetId,
      workflowMode: queuedProviderSelection?.workflowMode ?? request.workflowMode,
      sessionTrust: request.sessionTrust,
      imageAttachments: request.imageAttachments.map((attachment, index) => ({
        id: attachment.id || `${job.runId}-attachment-${index}`,
        path: attachment.path,
        name: attachment.name || getImageName(attachment.path),
        ...attachmentKindMetadata(attachment),
        ...persistedAttachmentMetadata(attachment)
      })),
      discordContextSelection: request.discordContextSelection,
      projectReferenceContextSelection: request.projectReferenceContextSelection,
      externalPathGrants: request.externalPathGrants,
      geminiWorktree: request.geminiWorktree,
      codexNativeReview: request.codexNativeReview,
      codexReasoningEffort:
        queuedProviderSelection?.codexReasoningEffort ?? request.codexReasoningEffort,
      codexServiceTier: queuedProviderSelection?.codexServiceTier ?? request.codexServiceTier,
      claudeReasoningEffort:
        queuedProviderSelection?.claudeReasoningEffort ?? request.claudeReasoningEffort,
      claudeFastMode: queuedProviderSelection?.claudeFastMode ?? request.claudeFastMode,
      kimiFastMode: queuedProviderSelection?.kimiFastMode ?? request.kimiFastMode,
      kimiReasoningEffort:
        queuedProviderSelection?.kimiReasoningEffort ?? request.kimiReasoningEffort,
      kimiThinkingEnabled:
        queuedProviderSelection?.kimiThinkingEnabled ?? request.kimiThinkingEnabled,
      grokReasoningEffort:
        queuedProviderSelection?.grokReasoningEffort ?? request.grokReasoningEffort,
      museReasoningEffort:
        queuedProviderSelection?.museReasoningEffort ?? request.museReasoningEffort,
      mistralReasoningEffort:
        queuedProviderSelection?.mistralReasoningEffort ?? request.mistralReasoningEffort,
      piReasoningEffort: queuedProviderSelection?.piReasoningEffort ?? request.piReasoningEffort,
      antigravityReasoningEffort:
        queuedProviderSelection?.antigravityReasoningEffort ?? request.antigravityReasoningEffort,
      ollamaReasoningEffort:
        queuedProviderSelection?.ollamaReasoningEffort ?? request.ollamaReasoningEffort,
      cursorReasoningEffort:
        queuedProviderSelection?.cursorReasoningEffort ?? request.cursorReasoningEffort,
      cursorFastMode: queuedProviderSelection?.cursorFastMode ?? request.cursorFastMode,
      scheduledTaskId: request.scheduledTaskId,
      scheduledRunAt: request.scheduledRunAt,
      effectiveWorkspacePath: restoreQueuedRunWorktreeTarget(request),
      dmTargetParticipantId: request.dmTargetParticipantId,
      exactPickerParticipantId: request.exactPickerParticipantId,
      runtimeProfileId: queuedProviderSelection
        ? getRuntimeProfileIdForChat(queuedProviderBaseChat, effectiveProvider)
        : job.runtimeProfileId || request.runtimeProfileId,
      geminiAuthProfileId: queuedProviderSelection
        ? effectiveProvider === 'gemini'
          ? typeof queuedProviderBaseChat.providerMetadata?.geminiAuthProfileId === 'string'
            ? queuedProviderBaseChat.providerMetadata.geminiAuthProfileId
            : geminiAuthStatus?.activeProfileId || null
          : null
        : request.geminiAuthProfileId,
      handoffSourceRunId: job.handoffSourceRunId || request.handoffSourceRunId,
      workspaceRecord: scope === 'global' ? undefined : workspaceRecord,
      chatRecord,
      preserveComposer: request.preserveComposer
    }
  }

  const discordContextSelectionQueueKey = (
    selection: DiscordContextSelection | null | undefined
  ): string =>
    selection
      ? [
          selection.guildId || '',
          selection.channelId,
          selection.limit,
          selection.channelName || '',
          selection.guildName || ''
        ].join(':')
      : ''

  const projectReferenceContextSelectionQueueKey = (
    selection: ProjectReferenceContextSelection | null | undefined
  ): string => (selection ? `${selection.projectId}:${selection.referenceIds.join(',')}` : '')

  const getQueuedDesktopRunJobs = (sourceJobs: RunQueueJob[] = runQueueJobsRef.current) => {
    const cachedOrder = new Map<string, number>()
    queuedRunsRef.current.forEach((request, index) => {
      if (request.appRunId) cachedOrder.set(request.appRunId, index)
    })
    return (
      sourceJobs
        .filter(isQueuedDesktopRunQueueJob)
        // Execution-graph rows are observed here for Stack/Map projection only.
        // Their lease, composition, and provider launch are owned by main.
        .filter((job) => !job.executionGraph)
        .slice()
        .sort((a, b) => {
          const aOrder = cachedOrder.get(a.runId)
          const bOrder = cachedOrder.get(b.runId)
          if (aOrder !== undefined || bOrder !== undefined) {
            return (aOrder ?? Number.MAX_SAFE_INTEGER) - (bOrder ?? Number.MAX_SAFE_INTEGER)
          }
          return queuedRunJobSortTime(a) - queuedRunJobSortTime(b)
        })
    )
  }

  const resolveQueuedDesktopRunRequest = (job: RunQueueJob): QueuedRunRequest | null => {
    if (!isQueuedDesktopRunQueueJob(job)) return null
    if (job.executionGraph) {
      return queuedRunRequestFromJob(job, workspaces, Array.from(chatByIdRef.current.values()))
    }
    const cached = queuedRunsRef.current.find((request) => request.appRunId === job.runId)
    if (cached) {
      const cachedChatId = cached.chatRecord?.appChatId || job.chatId
      const chatRecord = cachedChatId ? chatByIdRef.current.get(cachedChatId) : cached.chatRecord
      const workspaceRecord =
        job.scope === 'global'
          ? undefined
          : workspaces.find(
              (workspace) =>
                workspace.id === job.workspaceId || workspace.path === job.workspacePath
            ) || cached.workspaceRecord
      return {
        ...cached,
        ...(chatRecord ? { chatRecord } : {}),
        ...(workspaceRecord ? { workspaceRecord } : {})
      }
    }
    return queuedRunRequestFromJob(job, workspaces, Array.from(chatByIdRef.current.values()))
  }

  const applyRecoveryRecordsToChats = async (
    records: RunRecoveryRecord[],
    chatList: ChatRecord[]
  ): Promise<ChatRecord[]> => {
    if (records.length === 0 || chatList.length === 0) return chatList
    const recordsByChatId = new Map<string, RunRecoveryRecord[]>()
    for (const record of records) {
      if (!record.chatId) continue
      const existing = recordsByChatId.get(record.chatId) || []
      existing.push(record)
      recordsByChatId.set(record.chatId, existing)
    }

    if (recordsByChatId.size === 0) return chatList

    // Startup recovery reconciles two persisted views: generic `runs[]`
    // for badges and Ensemble `activeRound` for queue/steer decisions.
    // Without the activeRound pass, a force-quit round can retain a
    // live-looking participant + queuedPrompt even after the run queue
    // marked the underlying provider job failed.
    const runsReconciledChats = applyRecoveryRecordsToChatRuns(records, chatList)
    const lifecycleReconciledChats = applyRecoveryRecordsToEnsembleRounds(
      records,
      runsReconciledChats
    )

    // Run/round lifecycle reconciliation only — we no longer append a
    // "Recovered interrupted <Provider> run…" system message per record.
    // Those notices batch-spammed the transcript on every crash recovery, and
    // the reconciled run/round status already tells the user whether anything
    // was interrupted and whether it is safe to continue.
    const updatedChats = lifecycleReconciledChats

    const changedChats = updatedChats.filter((chat, index) => chat !== chatList[index])
    if (changedChats.length === 0) return chatList

    for (const chat of changedChats) {
      chatByIdRef.current.set(chat.appChatId, chat)
    }
    await Promise.all(changedChats.map((chat) => window.api.saveChat(chat).catch(() => {})))
    setChats((prev) => {
      if (prev.length === 0) return updatedChats
      const updatedById = new Map(updatedChats.map((chat) => [chat.appChatId, chat]))
      return prev.map((chat) => updatedById.get(chat.appChatId) || chat)
    })
    setCurrentChat((prev) =>
      prev ? updatedChats.find((chat) => chat.appChatId === prev.appChatId) || prev : prev
    )
    return updatedChats
  }

  const rehydrateQueuedRuns = async (workspaceList: WorkspaceRecord[]) => {
    if (rehydratedRunQueueRef.current || typeof window.api.getRunQueueJobs !== 'function') return
    rehydratedRunQueueRef.current = true
    let retryNeeded = false
    const scheduleRetry = (): void => {
      if (runQueueRehydrateRetryCountRef.current >= 3) return
      runQueueRehydrateRetryCountRef.current += 1
      rehydratedRunQueueRef.current = false
      const delayMs = runQueueRehydrateRetryCountRef.current * 500
      window.setTimeout(() => void rehydrateQueuedRuns(workspaceList), delayMs)
    }
    let fetchedJobs: RunQueueJob[]
    let recoveryRecords: RunRecoveryRecord[]
    try {
      ;[fetchedJobs, recoveryRecords] = await Promise.all([
        window.api.getRunQueueJobs({ statuses: ['queued', 'steer_promoting'] }),
        typeof window.api.getRunRecoveryRecords === 'function'
          ? window.api.getRunRecoveryRecords({ limit: 100 })
          : Promise.resolve([])
      ])
    } catch {
      scheduleRetry()
      return
    }
    const jobs = fetchedJobs.filter(
      (job) => job.status === 'queued' || isPreparedSoloSteerQueueJob(job)
    )
    // Only chats referenced by a queued job or a recovery record need their
    // full records here — this used to call getChats() and pull EVERY chat
    // transcript (tens of MB) across IPC during startup for a lookup that
    // typically touches zero or a handful of chats.
    const neededChatIds = new Set<string>()
    for (const job of jobs) {
      if ((job.status === 'queued' || isPreparedSoloSteerQueueJob(job)) && job.chatId) {
        neededChatIds.add(job.chatId)
      }
    }
    for (const record of recoveryRecords) {
      if (record.chatId) neededChatIds.add(record.chatId)
    }
    const chatList = (
      await Promise.all(
        Array.from(neededChatIds).map((chatId) => window.api.getChat(chatId).catch(() => null))
      )
    ).filter((chat): chat is ChatRecord => Boolean(chat))
    const recoveredChatList = await applyRecoveryRecordsToChats(recoveryRecords, chatList)
    for (const chat of recoveredChatList) {
      chatByIdRef.current.set(chat.appChatId, chat)
    }
    const effectiveJobs = [...jobs]
    for (const [index, job] of effectiveJobs.entries()) {
      if (!isPreparedSoloSteerQueueJob(job)) continue
      const request = queuedRunRequestFromJob(job, workspaceList, recoveredChatList, {
        allowPreparedSoloSteer: true
      })
      if (!request) {
        let chatLookupFailed = false
        const durableChat = job.chatId
          ? await window.api.getChat(job.chatId).catch(() => {
              chatLookupFailed = true
              return null
            })
          : null
        if (!chatLookupFailed && !durableChat) {
          const reason =
            'Prepared steering could not be recovered because its privacy-scoped chat transcript is unavailable after restart.'
          const failed = await window.api
            .transitionRunQueueJob(job.runId, 'failed', {
              statusReason: reason,
              lastError: reason
            })
            .catch(() => null)
          if (failed) effectiveJobs[index] = failed
        } else {
          retryNeeded = true
        }
        continue
      }
      const message = await appendMidRunQueuedRequestToTranscript(
        request,
        'soloSteer',
        job.createdAt,
        { persistImmediately: true }
      )
      if (!message) {
        retryNeeded = true
        continue
      }
      if (job.steerDeliveryPhase !== undefined && job.steerDeliveryPhase !== 'prepared') {
        const statusReason =
          'Live steering admission was interrupted while its provider outcome was unknown.'
        const lastError =
          'TaskWraith did not replay this steering message because the provider may already have accepted it.'
        const failed = await window.api
          .transitionRunQueueJob(job.runId, 'failed', { statusReason, lastError })
          .catch(() => null)
        // A null result can mean MAIN still owns a live admission in this same
        // process. Preserve that projection rather than fabricating a local
        // failure or deleting its transcript row. On blocked startup there is
        // no coordinator owner, so the terminal transition above commits.
        if (failed) {
          effectiveJobs[index] = failed
          appendThreadRawLog(job.chatId, {
            type: 'stderr',
            content: `${statusReason} ${lastError}`
          })
        }
        continue
      }
      const ownerToken = job.promotionOwnerToken
      if (!ownerToken) continue
      const released = await invokeFallbackPromotedSteerJob({
        runId: job.runId,
        ownerToken,
        reason: 'Recovered a solo steer after its durable transcript barrier.',
        fallbackStatus: 'queued'
      }).catch(() => null)
      if (released?.ok === true && released.jobStatus === 'queued') {
        effectiveJobs[index] = {
          ...job,
          status: 'queued',
          statusReason: 'Recovered a solo steer after its durable transcript barrier.',
          promotionOwnerToken: undefined,
          promotionToken: undefined,
          steerPreparationKind: undefined
        }
      } else {
        retryNeeded = true
      }
    }
    const durableChatList = recoveredChatList.map(
      (chat) => chatByIdRef.current.get(chat.appChatId) || chat
    )
    setRunQueueJobs(effectiveJobs)
    const restoredRuns = effectiveJobs
      .map((job) => queuedRunRequestFromJob(job, workspaceList, durableChatList))
      .filter((request): request is QueuedRunRequest => Boolean(request))
    if (restoredRuns.length > 0) {
      setQueuedRuns((current) => {
        const knownRunIds = new Set(current.map((request) => request.appRunId))
        return [...current, ...restoredRuns.filter((request) => !knownRunIds.has(request.appRunId))]
      })
    }
    if (retryNeeded) scheduleRetry()
    else runQueueRehydrateRetryCountRef.current = 0
  }

  const buildRunRequest = (
    overrideModel?: string,
    existingPrompt?: string,
    target?: {
      chat?: ChatRecord | null
      prompt?: string
      displayPrompt?: string
      approvalMode?: string
      workflowMode?: ChatWorkflowMode
      sessionTrust?: boolean
      imageAttachments?: ImageAttachment[]
      discordContextSelection?: DiscordContextSelection | null
      projectReferenceContextSelection?: ProjectReferenceContextSelection | null
      claimProjectReferenceContext?: boolean
    }
  ): QueuedRunRequest => {
    const selectedChat =
      target?.chat ||
      (currentChatIdRef.current ? chatByIdRef.current.get(currentChatIdRef.current) : null) ||
      currentChat
    const scope = getChatScope(selectedChat)
    const selectedWorkspace =
      scope === 'global' ? null : getWorkspaceForChat(selectedChat) || currentWorkspace
    const selectedComposerWorktree = composerWorktreeSelectionForChat(
      composerWorktreeByChatId,
      selectedChat?.appChatId,
      selectedWorkspace?.path
    )
    const provider = selectedChat ? getChatProvider(selectedChat) : currentProvider
    const composerSelection = selectedChat ? getChatComposerSelection(selectedChat, provider) : null
    // AntiGravity's presentation marker belongs only to an AntiGravity run.
    // Older chats can retain it after a provider switch because provider
    // metadata is merged for history. Strip that stale signal from the run
    // snapshot so another provider cannot inherit invisible UltraTask intent.
    const requestChatRecord =
      selectedChat &&
      provider !== 'antigravity' &&
      (selectedChat.providerMetadata?.antigravityUltraTaskSelected === true ||
        typeof selectedChat.providerMetadata?.antigravityReasoningEffort === 'string')
        ? {
            ...selectedChat,
            providerMetadata: {
              ...(selectedChat.providerMetadata || {}),
              antigravityReasoningEffort: null,
              antigravityUltraTaskSelected: false
            }
          }
        : selectedChat
    const rawRequestModel = overrideModel
      ? selectedModelType
      : composerSelection?.selectedModelType || selectedModelType
    const requestModel = isValidModelForProvider(provider, rawRequestModel)
      ? rawRequestModel
      : getDefaultModelForProvider(provider)
    const requestCustomModel = composerSelection?.customModel ?? customModel
    const requestApprovalMode =
      target?.approvalMode || composerSelection?.approvalMode || approvalMode
    const requestWorkflowMode =
      target?.workflowMode ??
      composerSelection?.workflowMode ??
      selectedChat?.workflowMode ??
      'normal'
    const basePermissionPresetId =
      composerSelection?.permissionPresetId ||
      approvalModeToPermissionPreset(requestApprovalMode, requestWorkflowMode)
    const requestPermissionPresetId: PermissionPresetId = basePermissionPresetId
    const requestReasoningEffort =
      provider === 'codex'
        ? composerSelection?.codexReasoningEffort || codexReasoningEffort
        : codexReasoningEffort
    const requestServiceTier =
      provider === 'codex'
        ? composerSelection?.codexServiceTier || codexServiceTier
        : codexServiceTier
    const requestKimiThinkingEnabled = provider === 'kimi' ? true : kimiThinkingEnabled
    const requestKimiReasoningEffort =
      provider === 'kimi'
        ? composerSelection?.kimiReasoningEffort || kimiReasoningEffort
        : kimiReasoningEffort
    const requestKimiFastMode =
      provider === 'kimi'
        ? Boolean(
            (composerSelection?.kimiFastMode ?? kimiFastMode) &&
            getProviderModelOptions('kimi')
              .find((model) => model.id === requestModel)
              ?.additionalSpeedTiers?.includes('fast')
          )
        : kimiFastMode
    const requestClaudeReasoningEffort =
      provider === 'claude'
        ? composerSelection?.claudeReasoningEffort || claudeReasoningEffort
        : claudeReasoningEffort
    const requestClaudeFastMode =
      provider === 'claude' ? (composerSelection?.claudeFastMode ?? claudeFastMode) : claudeFastMode
    const requestGrokReasoningEffort =
      provider === 'grok'
        ? composerSelection?.grokReasoningEffort || grokReasoningEffort
        : grokReasoningEffort
    const requestMuseReasoningEffort =
      provider === 'muse'
        ? composerSelection?.museReasoningEffort ||
          museReasoningEffort ||
          MUSE_DEFAULT_REASONING_EFFORT
        : museReasoningEffort
    const requestMistralReasoningEffort =
      provider === 'mistral'
        ? composerSelection?.mistralReasoningEffort || mistralReasoningEffort
        : mistralReasoningEffort
    const requestPiReasoningEffort =
      provider === 'pi'
        ? composerSelection?.piReasoningEffort || piReasoningEffort
        : piReasoningEffort
    const requestOllamaReasoningEffort =
      provider === 'ollama'
        ? composerSelection?.ollamaReasoningEffort || ollamaReasoningEffort
        : ollamaReasoningEffort
    const requestCursorReasoningEffort =
      provider === 'cursor'
        ? composerSelection?.cursorReasoningEffort || cursorReasoningEffort
        : cursorReasoningEffort
    const requestCursorFastMode =
      provider === 'cursor' ? (composerSelection?.cursorFastMode ?? cursorFastMode) : cursorFastMode
    const requestAntigravityReasoningEffort =
      provider === 'antigravity'
        ? composerSelection?.antigravityReasoningEffort ||
          antigravityEffortForModelId(requestModel) ||
          null
        : null
    const normalizedExternalPathGrants =
      scope !== 'global'
        ? normalizeExternalPathGrants(
            collectExternalPathGrantsFromMetadata(selectedChat?.providerMetadata)
          )
        : []
    const externalPathGrants =
      scope === 'global'
        ? []
        : selectedChat?.chatKind === 'ensemble'
          ? filterDispatchExternalPathGrants(normalizedExternalPathGrants)
          : normalizedExternalPathGrants.filter((grant) => grant.provider === provider)
    const targetDiscordContextSelection =
      target && Object.prototype.hasOwnProperty.call(target, 'discordContextSelection')
        ? { value: target.discordContextSelection }
        : undefined
    const requestDiscordContextSelection = resolveRunDiscordContextSelection({
      existingPrompt,
      selectedChatId: selectedChat?.appChatId,
      currentComposerChatId,
      currentSelection: currentDiscordContextSelection,
      targetSelection: targetDiscordContextSelection
    })
    const targetProjectReferenceContextSelection =
      target && Object.prototype.hasOwnProperty.call(target, 'projectReferenceContextSelection')
        ? target.projectReferenceContextSelection
        : undefined
    const projectReferenceContextClaim =
      !existingPrompt &&
      selectedChat?.chatKind !== 'ensemble' &&
      targetProjectReferenceContextSelection === undefined &&
      (!target || target.claimProjectReferenceContext === true)
        ? claimProjectReferenceContextSelection(selectedChat?.appChatId)
        : null
    const requestProjectReferenceContextSelection =
      !existingPrompt && selectedChat?.chatKind !== 'ensemble'
        ? targetProjectReferenceContextSelection !== undefined
          ? targetProjectReferenceContextSelection
          : (projectReferenceContextClaim?.selection ?? null)
        : null

    return {
      appRunId: createAppRunId(),
      scope,
      provider,
      prompt: target?.prompt !== undefined ? target.prompt : existingPrompt || prompt,
      ...(target?.displayPrompt !== undefined ? { displayPrompt: target.displayPrompt } : {}),
      overrideModel,
      existingPrompt,
      selectedModelType: requestModel,
      customModel: requestCustomModel,
      approvalMode: requestApprovalMode,
      permissionPresetId: requestPermissionPresetId,
      workflowMode: requestWorkflowMode,
      sessionTrust: target?.sessionTrust ?? sessionTrust,
      imageAttachments: target?.imageAttachments ?? imageAttachments,
      ...(selectedComposerWorktree?.effectiveWorkspacePath
        ? { effectiveWorkspacePath: selectedComposerWorktree.effectiveWorkspacePath }
        : {}),
      ...(requestDiscordContextSelection
        ? { discordContextSelection: requestDiscordContextSelection }
        : {}),
      ...(requestProjectReferenceContextSelection
        ? { projectReferenceContextSelection: requestProjectReferenceContextSelection }
        : {}),
      ...(projectReferenceContextClaim ? { projectReferenceContextClaim } : {}),
      externalPathGrants,
      geminiWorktree:
        scope === 'global' ? undefined : resolveGeminiWorktreeConfig(selectedWorkspace),
      codexReasoningEffort: requestReasoningEffort,
      codexServiceTier: requestServiceTier,
      claudeReasoningEffort: requestClaudeReasoningEffort,
      claudeFastMode: requestClaudeFastMode,
      kimiFastMode: requestKimiFastMode,
      kimiReasoningEffort: requestKimiReasoningEffort,
      kimiThinkingEnabled: requestKimiThinkingEnabled,
      grokReasoningEffort: requestGrokReasoningEffort,
      museReasoningEffort: requestMuseReasoningEffort,
      mistralReasoningEffort: requestMistralReasoningEffort,
      piReasoningEffort: requestPiReasoningEffort,
      ollamaReasoningEffort: requestOllamaReasoningEffort,
      cursorReasoningEffort: requestCursorReasoningEffort,
      cursorFastMode: requestCursorFastMode,
      antigravityReasoningEffort: requestAntigravityReasoningEffort,
      runtimeProfileId: getRuntimeProfileIdForChat(selectedChat, provider),
      geminiAuthProfileId:
        provider === 'gemini'
          ? typeof selectedChat?.providerMetadata?.geminiAuthProfileId === 'string'
            ? selectedChat.providerMetadata.geminiAuthProfileId
            : geminiAuthStatus?.activeProfileId || null
          : null,
      workspaceRecord: selectedWorkspace || undefined,
      chatRecord: requestChatRecord || undefined
    }
  }
  const buildRunRequestRef = useRef(buildRunRequest)
  buildRunRequestRef.current = buildRunRequest

  const queueRunRequest = (
    request: QueuedRunRequest,
    reason = 'Another task is currently active.'
  ): Promise<boolean> => {
    const queuedRequest = request.appRunId ? request : { ...request, appRunId: createAppRunId() }
    const targetChatId = queuedRequest.chatRecord?.appChatId
    const targetProvider = queuedRequest.provider
    const duplicateQueuedRun = getQueuedDesktopRunJobs().some(
      (job) =>
        job.provider === targetProvider &&
        job.chatId === targetChatId &&
        (job.request?.prompt || job.promptPreview || '') === queuedRequest.prompt &&
        job.request?.selectedModelType === queuedRequest.selectedModelType &&
        job.request?.scheduledRunAt === queuedRequest.scheduledRunAt &&
        job.request?.effectiveWorkspacePath === queuedRequest.effectiveWorkspacePath &&
        job.request?.dmTargetParticipantId === queuedRequest.dmTargetParticipantId &&
        job.request?.exactPickerParticipantId === queuedRequest.exactPickerParticipantId &&
        attachmentQueueKey(job.request?.imageAttachments || []) ===
          attachmentQueueKey(queuedRequest.imageAttachments) &&
        discordContextSelectionQueueKey(job.request?.discordContextSelection) ===
          discordContextSelectionQueueKey(queuedRequest.discordContextSelection) &&
        projectReferenceContextSelectionQueueKey(job.request?.projectReferenceContextSelection) ===
          projectReferenceContextSelectionQueueKey(queuedRequest.projectReferenceContextSelection)
    )
    const duplicateLocalQueuedRun = queuedRunsRef.current.some(
      (request) =>
        request.appRunId !== queuedRequest.appRunId &&
        request.provider === targetProvider &&
        queuedRunRequestChatId(request) === targetChatId &&
        request.prompt === queuedRequest.prompt &&
        request.selectedModelType === queuedRequest.selectedModelType &&
        request.scheduledRunAt === queuedRequest.scheduledRunAt &&
        request.effectiveWorkspacePath === queuedRequest.effectiveWorkspacePath &&
        request.dmTargetParticipantId === queuedRequest.dmTargetParticipantId &&
        request.exactPickerParticipantId === queuedRequest.exactPickerParticipantId &&
        attachmentQueueKey(request.imageAttachments) ===
          attachmentQueueKey(queuedRequest.imageAttachments) &&
        discordContextSelectionQueueKey(request.discordContextSelection) ===
          discordContextSelectionQueueKey(queuedRequest.discordContextSelection) &&
        projectReferenceContextSelectionQueueKey(request.projectReferenceContextSelection) ===
          projectReferenceContextSelectionQueueKey(queuedRequest.projectReferenceContextSelection)
    )
    if (duplicateQueuedRun || duplicateLocalQueuedRun) {
      settleProjectReferenceContextForRequest(queuedRequest, 'rejected')
      updateRunQueueJobStatus(queuedRequest.appRunId, 'cancelled', 'Duplicate queued run ignored.')
      appendThreadRawLog(targetChatId, {
        type: 'info',
        content: `${getProviderLabel(targetProvider)} run was already queued for this request.`
      })
      return Promise.resolve(false)
    }
    const knownRunQueueJobIds = collectRunQueueJobIds(runQueueJobsRef.current)
    const localQueuedRunsForChat = queuedRunsRef.current.filter(
      (request) =>
        queuedRunRequestChatId(request) === targetChatId &&
        !(request.appRunId && knownRunQueueJobIds.has(request.appRunId))
    )
    const queuePosition =
      getQueuedDesktopRunJobs().filter((job) => job.chatId === targetChatId).length +
      localQueuedRunsForChat.length +
      1
    const persistence = persistRunQueueJobForRequest(queuedRequest, 'queued', reason)
      .then((job) => {
        if (!job) {
          throw new Error('The queued run could not be persisted.')
        }
        settleProjectReferenceContextForRequest(queuedRequest, 'accepted')
        return true
      })
      .catch((error) => {
        settleProjectReferenceContextForRequest(queuedRequest, 'rejected')
        setQueuedRuns((prev) =>
          prev.filter((candidate) => candidate.appRunId !== queuedRequest.appRunId)
        )
        appendThreadRawLog(targetChatId, {
          type: 'stderr',
          content: `Failed to queue ${getProviderLabel(targetProvider)} run: ${redactLog(String(error))}`
        })
        return false
      })
    setQueuedRuns((prev) => [...prev, queuedRequest])
    appendThreadRawLog(targetChatId, {
      type: 'info',
      content: `${getProviderLabel(targetProvider)} run queued (${queuePosition} waiting). ${reason}`
    })
    return persistence
  }
  const queueRunRequestRef = useRef(queueRunRequest)
  queueRunRequestRef.current = queueRunRequest

  const appendMidRunQueuedRequestToTranscript = async (
    request: QueuedRunRequest,
    source: 'scheduledRun' | 'soloSteer',
    timestampIso: string,
    options: { persistImmediately?: boolean } = {}
  ): Promise<ChatMessage | null> => {
    const runId = request.appRunId
    const chatId = request.chatRecord?.appChatId
    if (!runId || !chatId) return null
    const liveChat = chatByIdRef.current.get(chatId) || request.chatRecord
    if (!liveChat) return null
    const existing = findMidRunQueuedMessage(liveChat.messages || [], runId)
    if (existing) {
      if (options.persistImmediately) {
        try {
          await window.api.saveChat(liveChat)
        } catch {
          return null
        }
      }
      return existing
    }
    if (midRunTranscriptAppendInFlightRef.current.has(runId)) return null
    midRunTranscriptAppendInFlightRef.current.add(runId)
    try {
      const imageAttachmentMetadata = request.imageAttachments
        .map((attachment) => ({
          id: attachment.id,
          path: attachment.path,
          name: attachment.name || getImageName(attachment.path),
          ...attachmentKindMetadata(attachment)
        }))
        .filter((attachment) => Boolean(attachment.path))
      const metadata: ChatMessage['metadata'] = {}
      if (imageAttachmentMetadata.length > 0) {
        metadata.imageAttachments = imageAttachmentMetadata
      }
      const content = runRequestPromptPreview(request)
      const linkPreviews = extractHttpUrls(content, 8)
      if (linkPreviews.length > 0) metadata.linkPreviews = linkPreviews

      let appendedMessage: ChatMessage | null = null
      const updatedChat = updateChatById(chatId, (chat) => {
        const result = appendMidRunQueuedMessage(chat.messages || [], {
          runId,
          content,
          timestampIso,
          source,
          metadata
        })
        appendedMessage = result.message
        if (!result.appended) return chat
        return {
          ...chat,
          title:
            chat.messages.length === 0 ? normalizeThreadTitle(content, 'New Chat') : chat.title,
          messages: result.messages,
          updatedAt: Date.now()
        }
      })
      if (options.persistImmediately) {
        if (!appendedMessage || !updatedChat) return null
        try {
          await window.api.saveChat(updatedChat)
        } catch {
          return null
        }
      }
      if (appendedMessage && request.imageAttachments.length > 0) {
        void buildSubmittedImageThumbnailMetadata(request.imageAttachments)
          .then((imageThumbnailMetadata) => {
            if (imageThumbnailMetadata.imagePaths.length === 0) return
            updateChatById(chatId, (chat) => ({
              ...chat,
              messages: chat.messages.map((message) =>
                message.id === appendedMessage?.id
                  ? {
                      ...message,
                      metadata: {
                        ...(message.metadata || {}),
                        imagePaths: imageThumbnailMetadata.imagePaths,
                        imageThumbnails: imageThumbnailMetadata.imageThumbnails
                      }
                    }
                  : message
              ),
              updatedAt: Date.now()
            }))
          })
          .catch(() => {})
      }
      return appendedMessage
    } finally {
      midRunTranscriptAppendInFlightRef.current.delete(runId)
    }
  }

  const handlePermissionRetry = async () => {
    if (permissionRequestPaths.length === 0 || !currentWorkspace || !currentChat) {
      clearImagePermissions()
      return
    }

    const permissionAttachments = permissionRequestPaths.map((path, index) => ({
      id: `perm-${Date.now()}-${index}`,
      path,
      name: getImageName(path)
    }))
    const lastRequest = latestRunRequestRef.current
    const request = lastRequest
      ? {
          ...lastRequest,
          imageAttachments: mergeImageAttachments(
            lastRequest.imageAttachments,
            permissionAttachments
          )
        }
      : buildRunRequest()

    clearImagePermissions()

    const permissionTargetChat = request.chatRecord || currentChat
    if (
      shouldQueueRunBeforeDispatch({
        chatKind: permissionTargetChat?.chatKind,
        busy: isChatBusy(permissionTargetChat?.appChatId || currentChat?.appChatId)
      })
    ) {
      queueRunRequest(
        request,
        `Permission retry is waiting for this chat's active ${getProviderLabel(request.provider)} task to exit.`
      )
      return
    }

    void executeRun(request)
  }

  const discordContextToolSummary = (metadata: DiscordContextReadMetadata): string =>
    `Read Discord #${metadata.channelName} · ${metadata.messageCount} messages`

  const discordContextToolResult = (metadata: DiscordContextReadMetadata): string => {
    const lines = [
      metadata.guildName ? `Server: ${metadata.guildName}` : '',
      `Channel: #${metadata.channelName}`,
      `Fetched at: ${metadata.fetchedAt}`,
      `Messages: ${metadata.messageCount}`,
      metadata.firstTimestamp && metadata.lastTimestamp
        ? `Range: ${metadata.firstTimestamp} to ${metadata.lastTimestamp}`
        : '',
      '',
      'Preview omitted: Discord message text is run-only and is not persisted in chat history.',
      metadata.truncated
        ? 'Full Discord context was capped before being supplied to the model.'
        : 'Full content was supplied to the model as external untrusted context.'
    ]
    return lines.filter((line, index) => line || lines[index - 1]).join('\n')
  }

  const redactDiscordContextReadMetadataForHistory = (
    metadata: DiscordContextReadMetadata
  ): DiscordContextReadMetadata => ({
    ...metadata,
    previewMessages: []
  })

  const redactDiscordContextReadsForHistory = (
    reads: DiscordContextReadMetadata[]
  ): DiscordContextReadMetadata[] => reads.map(redactDiscordContextReadMetadataForHistory)

  const createDiscordContextToolMessage = (
    reads: DiscordContextReadMetadata[],
    timestamp: string,
    provider: ProviderId
  ): ChatMessage => ({
    id: createMessageId(),
    role: 'tool',
    content: '',
    timestamp,
    toolActivities: reads.map((metadata, index) => ({
      id: `discord-context-${metadata.channelId}-${metadata.fetchedAt}-${index}`,
      toolName: discordContextToolSummary(metadata),
      displayName: discordContextToolSummary(metadata),
      category: 'read',
      status: 'success',
      startedAt: metadata.fetchedAt,
      endedAt: metadata.fetchedAt,
      durationMs: 0,
      parameters: {
        channelId: metadata.channelId,
        channelName: metadata.channelName,
        guildId: metadata.guildId,
        guildName: metadata.guildName,
        limit: metadata.limit,
        retention: metadata.retention
      },
      resultSummary: discordContextToolResult(metadata),
      metadata: {
        provider
      }
    }))
  })

  const executeRun = async (runRequest?: QueuedRunRequest) => {
    // Diagnostic fix (send-message regression investigation, 2026-05-16):
    // Every call site invokes this via `void executeRun(...)` which
    // discards the returned promise. Without a function-level try/catch
    // any uncaught exception silently rejects — producing the reported
    // "clicking Send does nothing" symptom. Wrap the entire body so the
    // user always sees an error if something escapes the inner catches.
    let currentRunIdForCleanup = runRequest?.appRunId
    let dispatchAccepted = false
    let requestForClaimCleanup = runRequest
    try {
      const baseRequest = runRequest ?? buildRunRequest()
      let request = baseRequest.appRunId
        ? baseRequest
        : { ...baseRequest, appRunId: createAppRunId() }
      requestForClaimCleanup = request
      let runChat = request.chatRecord || currentChat
      if (runChat && isChatSummaryRecord(runChat)) {
        const hydrated = await refreshSingleChat(runChat.appChatId)
        if (hydrated) {
          runChat = hydrated
          request = { ...request, chatRecord: hydrated, scope: getChatScope(hydrated) }
        }
      }
      let preAppendedPromptMessage: ChatMessage | null = null
      if (runChat && request.appRunId) {
        const liveRunChat = chatByIdRef.current.get(runChat.appChatId) || runChat
        preAppendedPromptMessage = findMidRunQueuedMessage(
          liveRunChat.messages || [],
          request.appRunId
        )
        if (preAppendedPromptMessage) {
          runChat = liveRunChat
          request = { ...request, chatRecord: liveRunChat, scope: getChatScope(liveRunChat) }
        }
      }
      const isGlobalRun = request.scope === 'global' || isGlobalChat(runChat)
      const runWorkspace = isGlobalRun
        ? null
        : request.workspaceRecord || getWorkspaceForChat(runChat) || currentWorkspace
      const currentRunId = request.appRunId || Date.now().toString()
      currentRunIdForCleanup = currentRunId
      if (!runChat || (!isGlobalRun && !runWorkspace) || !runRequestHasContent(request)) {
        settleProjectReferenceContextForRequest(request, 'rejected')
        updateRunQueueJobStatus(
          currentRunId,
          'failed',
          'Queued run could not be dispatched because its chat, workspace, or prompt was unavailable.'
        )
        return
      }
      const runProvider = request.provider || currentProvider
      if (!isGlobalRun) {
        let grantPreflight = findExternalPathGrantGaps({
          chat: runChat,
          grants: normalizeExternalPathGrants(
            collectExternalPathGrantsFromMetadata(runChat.providerMetadata)
          ),
          primaryWorkspacePath: runWorkspace?.path
        })
        // Mate case: primary workspace removed/re-added leaves secondary grants
        // signed but bound to the old workspace id. Remint from prior consent
        // for every active provider (one consent → whole roster) before any
        // seat can be skipped. Remaining gaps still open the grant prompt —
        // never fail-closed into a dispatch skip.
        if (grantPreflight.gaps.length > 0) {
          try {
            const repair = await window.api.repairStaleExternalPathGrants({
              chatId: runChat.appChatId
            })
            if (repair.ok) {
              const liveChat = chatByIdRef.current.get(runChat.appChatId) || runChat
              runChat = liveChat
              request = {
                ...request,
                chatRecord: liveChat,
                scope: getChatScope(liveChat),
                externalPathGrants: normalizeExternalPathGrants(
                  collectExternalPathGrantsFromMetadata(liveChat.providerMetadata)
                )
              }
              grantPreflight =
                repair.remainingGaps.length > 0
                  ? {
                      ...grantPreflight,
                      gaps: repair.remainingGaps
                    }
                  : findExternalPathGrantGaps({
                      chat: liveChat,
                      grants: normalizeExternalPathGrants(
                        collectExternalPathGrantsFromMetadata(liveChat.providerMetadata)
                      ),
                      primaryWorkspacePath: runWorkspace?.path
                    })
            }
          } catch (err) {
            console.warn('[external-path:repair-stale] preflight repair failed', err)
          }
        }
        if (grantPreflight.gaps.length > 0) {
          updateRunQueueJobStatus(
            currentRunId,
            'paused',
            'Waiting for external path grants before dispatch.'
          )
          openExternalPathGrantPrompt({
            chatId: runChat.appChatId,
            gaps: grantPreflight.gaps,
            pendingRun: request,
            trigger: 'preflight'
          })
          return
        }
      }
      if (request.discordContextSelection && !request.discordContextSnapshots?.length) {
        try {
          const snapshot = await window.api.readDiscordContext(request.discordContextSelection)
          request = {
            ...request,
            discordContextSnapshots: [snapshot]
          }
          appendThreadRawLog(runChat.appChatId, {
            type: 'tool',
            content: discordContextToolResult(snapshot.metadata)
          })
        } catch (error) {
          settleProjectReferenceContextForRequest(request, 'rejected')
          const message = `Failed to read Discord context: ${redactLog(String(error))}`
          updateRunQueueJobStatus(currentRunId, 'failed', 'Discord context read failed.', message)
          appendThreadRawLog(runChat.appChatId, { type: 'stderr', content: message })
          updateChatById(runChat.appChatId, (source) => ({
            ...source,
            messages: [
              ...source.messages,
              {
                id: createMessageId(),
                role: 'error',
                content: message,
                timestamp: new Date().toISOString()
              }
            ]
          }))
          return
        }
      }
      if (runChat.chatKind === 'ensemble') {
        const workflowModeForRound = request.workflowMode || 'normal'
        if (runChat.workflowMode !== workflowModeForRound) {
          const updatedRunChat: ChatRecord = {
            ...runChat,
            workflowMode: workflowModeForRound,
            updatedAt: Date.now()
          }
          runChat = updatedRunChat
          chatByIdRef.current.set(updatedRunChat.appChatId, updatedRunChat)
          setChats((prev) =>
            prev.map((chat) =>
              chat.appChatId === updatedRunChat.appChatId ? updatedRunChat : chat
            )
          )
          if (currentChatIdRef.current === updatedRunChat.appChatId) {
            setCurrentChat(updatedRunChat)
          }
          window.api.saveChat(updatedRunChat)
        }
        const mode = isEnsembleActiveRoundDispatchLive(runChat.ensemble?.activeRound)
          ? ('queue' as const)
          : ('normal' as const)
        // Keep the configured policy on the wire until MAIN resolves the
        // prompt against its authoritative roster. Renderer ids are only
        // hints and may coexist with a multi-participant routing request.
        const fanoutPolicy: EnsembleFanoutPolicy = normalizeEnsembleFanoutPolicy(
          runChat.ensemble?.fanoutPolicy,
          runChat.ensemble?.concurrentModeEnabled
        )
        const concurrentMode = ensembleFanoutPolicyEnabled(fanoutPolicy)
        const optimisticQueuedPrompt = runRequestPromptPreview(request)
        const didOptimisticallyQueue =
          mode === 'queue'
            ? appendOptimisticEnsembleQueuedPrompt(runChat.appChatId, optimisticQueuedPrompt)
            : false
        try {
          await window.api.runEnsembleRound({
            chatId: runChat.appChatId,
            prompt: request.prompt,
            ...(request.scheduledTaskId ? { scheduledTaskId: request.scheduledTaskId } : {}),
            mode,
            concurrentMode,
            fanoutPolicy,
            imageAttachments: request.imageAttachments.map((attachment) => ({
              id: attachment.id,
              path: attachment.path,
              name: attachment.name,
              ...attachmentKindMetadata(attachment),
              ...persistedAttachmentMetadata(attachment)
            })),
            ...(request.discordContextSnapshots?.length
              ? { discordContextSnapshots: request.discordContextSnapshots }
              : {}),
            // A2 (1.0.3) — DM the selected chip only when the user
            // sent with Cmd/Ctrl held. The orchestrator filters
            // participants to just this one for the round.
            ...(request.dmTargetParticipantId
              ? { dmTargetParticipantId: request.dmTargetParticipantId }
              : {}),
            ...(request.exactPickerParticipantId
              ? { exactPickerParticipantId: request.exactPickerParticipantId }
              : {}),
            // 1.0.4-AT4 — composer-level external path grants. Pre-AT4
            // these were dropped at the IPC boundary, so file-mention
            // grants the user added in the composer never reached
            // ensemble participants. The orchestrator runs them
            // through `resolveEffectiveRunPermissions`'s
            // `explicitExternalPathGrants` input which provider-
            // filters per participant.
            ...(request.externalPathGrants && request.externalPathGrants.length > 0
              ? { externalPathGrants: request.externalPathGrants }
              : {}),
            // P1 F6 — Use-next selection for ensemble rounds. MAIN re-resolves
            // against the Project registry; the orchestrator appendix helper
            // formats per-seat disclosure (BG stays catalogue-only).
            ...(request.projectReferenceContextSelection
              ? {
                  projectReferenceContextSelection: request.projectReferenceContextSelection
                }
              : {})
          })
          const acceptedQueueWrapperReason = acceptedEnsembleRunQueueWrapperReason({
            mode,
            scheduledTaskId: request.scheduledTaskId,
            scheduledRunAt: request.scheduledRunAt
          })
          if (acceptedQueueWrapperReason) {
            updateRunQueueJobStatus(currentRunId, 'completed', acceptedQueueWrapperReason)
          }
          settleProjectReferenceContextForRequest(request, 'accepted')
        } catch (error) {
          if (didOptimisticallyQueue) {
            removeOptimisticEnsembleQueuedPrompt(runChat.appChatId, optimisticQueuedPrompt)
          }
          updateRunQueueJobStatus(
            currentRunId,
            'failed',
            'Ensemble dispatch handoff failed.',
            redactLog(String(error))
          )
          settleProjectReferenceContextForRequest(request, 'rejected')
          throw error
        }
        dispatchAccepted = true
        if (!request.existingPrompt && !request.preserveComposer) {
          setChatPromptDraft(runChat.appChatId, '')
          clearComposerAttachmentsForSubmittedRequest(request)
        }
        setIsThinking(true)
        if (mode !== 'queue') {
          void refreshSingleChat(runChat.appChatId)
        }
        return
      }
      // Per-chat busy check: only queue when THIS chat has an active
      // run. Multiple chats can dispatch in parallel to the same
      // provider — the underlying runner (Codex app-server thread,
      // fresh CLI process for Gemini/Kimi, independent SDK call for
      // Claude) handles concurrency per-chat.
      if (isChatBusy(runChat.appChatId, { ignoreQueueRunId: currentRunId })) {
        queueRunRequest(
          request,
          `This ${getProviderLabel(runProvider)} chat already has an in-flight run; TaskWraith will dispatch this turn when the chat's previous turn finishes.`
        )
        if (!request.existingPrompt && !request.preserveComposer) {
          setChatPromptDraft(runChat.appChatId, '')
          clearComposerAttachmentsForSubmittedRequest(request)
        }
        return
      }

      void persistRunQueueJobForRequest(
        request,
        'starting',
        'Provider runner is preparing this task.'
      ).catch(() => {})
      runSchedulerBusyRef.current = true

      errorCountRef.current = 0
      toolCallsCountRef.current = 0
      activeRunUsageResetHintsRef.current = new Map()
      currentRunWarningsRef.current = []
      clearImagePermissions()
      latestRunRequestRef.current = request

      const requestedRunWorktree =
        !isGlobalRun && runProvider === 'gemini' ? request.geminiWorktree : undefined
      const pendingMidRunMessageIds = pendingMidRunQueuedMessageIds([
        ...(preAppendedPromptMessage ? [currentRunId] : []),
        ...getQueuedDesktopRunJobs()
          .filter((job) => job.chatId === runChat.appChatId)
          .map((job) => job.runId)
      ])
      let composedPayload: Awaited<ReturnType<typeof window.api.composeRun>>
      try {
        composedPayload = await window.api.composeRun({
          chatId: runChat.appChatId,
          appRunId: currentRunId,
          // Unattended marker: presence forces a safe posture in ComposerService
          // (a scheduled occurrence must not silently inherit the chat's elevated
          // approvalMode). Mirrors the ensemble dispatch path.
          ...(request.scheduledTaskId ? { scheduledTaskId: request.scheduledTaskId } : {}),
          provider: runProvider,
          scope: isGlobalRun ? 'global' : 'workspace',
          ...(isGlobalRun ? {} : { workspace: runWorkspace!.path }),
          userInput: request.prompt,
          selectedModelType: request.selectedModelType,
          customModel: request.customModel,
          overrideModel: request.overrideModel,
          approvalMode: request.approvalMode,
          permissionPresetId: request.permissionPresetId,
          workflowMode: request.workflowMode,
          sessionTrust: request.sessionTrust,
          imageAttachments: request.imageAttachments,
          externalPathGrants: request.externalPathGrants,
          projectReferenceContextSelection: request.projectReferenceContextSelection,
          geminiWorktree: requestedRunWorktree,
          codexReasoningEffort: request.codexReasoningEffort,
          codexServiceTier: request.codexServiceTier,
          claudeReasoningEffort: request.claudeReasoningEffort,
          claudeFastMode: request.claudeFastMode,
          kimiFastMode: request.kimiFastMode,
          kimiReasoningEffort: request.kimiReasoningEffort,
          kimiThinkingEnabled: request.kimiThinkingEnabled,
          grokReasoningEffort: request.grokReasoningEffort,
          museReasoningEffort: request.museReasoningEffort,
          mistralReasoningEffort: request.mistralReasoningEffort,
          piReasoningEffort: request.piReasoningEffort,
          antigravityReasoningEffort: request.antigravityReasoningEffort,
          ollamaReasoningEffort: request.ollamaReasoningEffort,
          cursorReasoningEffort: request.cursorReasoningEffort,
          cursorFastMode: request.cursorFastMode,
          runtimeProfileId: request.runtimeProfileId,
          geminiAuthProfileId: request.geminiAuthProfileId,
          handoffSourceRunId: request.handoffSourceRunId,
          discordContextSnapshots: request.discordContextSnapshots,
          ...(request.verbatimPrompt ? { verbatimPrompt: true } : {}),
          ...(pendingMidRunMessageIds.length > 0
            ? ({ excludeMessageIds: pendingMidRunMessageIds } as Record<string, string[]>)
            : {}),
          chatSnapshot: runChat
        })
      } catch (error) {
        settleProjectReferenceContextForRequest(request, 'rejected')
        // Diagnostic fix (send-message regression investigation, 2026-05-16):
        // Previously this catch wrote only to the Inspector raw log, which a
        // user without the Inspector tab open never sees — producing the
        // exact "clicking Send does nothing" symptom that was reported.
        // Surface the failure as an error-role chat message + a queue-job
        // failure, mirroring the runAgent catch at lines 6513-6523. This
        // does not fix any underlying composeRun bug — it makes one visible.
        const message = `Failed to compose ${getProviderLabel(runProvider)} run: ${redactLog(String(error))}`
        updateRunQueueJobStatus(currentRunId, 'failed', 'Run payload composition failed.', message)
        appendThreadRawLog(runChat.appChatId, { type: 'stderr', content: message })
        updateChatById(runChat.appChatId, (source) => ({
          ...source,
          messages: [
            ...source.messages,
            {
              id: createMessageId(),
              role: 'error',
              content: message,
              timestamp: new Date().toISOString()
            }
          ]
        }))
        return
      }
      const composerMetadata = composedPayload.composer
      const effectiveRunProvider = composedPayload.provider || runProvider
      const runWorktree =
        !isGlobalRun && effectiveRunProvider === 'gemini'
          ? normalizeGeminiWorktreeLaunchOption(
              composedPayload.geminiWorktree ||
                (runProvider === 'gemini' ? request.geminiWorktree : undefined)
            )
          : undefined
      const runDiffUnavailable = !isGlobalRun && isGeminiWorktreeDiffUnavailable(runWorktree)
      let runDiffWorkspacePath =
        !isGlobalRun && runWorkspace && !runDiffUnavailable
          ? getDiffWorkspacePath(runWorkspace, runWorktree)
          : undefined
      const composerWorktreeSelection =
        !isGlobalRun && runWorkspace
          ? composerWorktreeSelectionFromEffectivePath(
              runWorkspace.path,
              request.effectiveWorkspacePath
            )
          : null
      const runRuntimeProfile = request.runtimeProfileId
        ? runtimeProfiles.find((profile) => profile.id === request.runtimeProfileId) || null
        : null
      const runtimeWorktreeIntent =
        !isGlobalRun && runWorkspace
          ? buildComposerRuntimeWorktreeIntent({
              baseWorkspacePath: runWorkspace.path,
              selection: composerWorktreeSelection,
              runtimeProfile: runRuntimeProfile
            })
          : undefined
      // A runtime profile can require an isolated worktree with no composer
      // selection: main preflight now allocates and persists one
      // asynchronously (ThreadWorktreeAllocator). Keep the run pending with a
      // visible preparing state; allocation failures surface through the
      // existing preflight error path with the allocator's recovery guidance.
      if (runtimeWorktreeIntent?.status === 'selection-required') {
        updateRunQueueJobStatus(currentRunId, 'starting', 'Preparing an isolated worktree…')
      }
      const composerEffectiveWorkspacePath =
        runtimeWorktreeIntent?.status === 'selected'
          ? runtimeWorktreeIntent.effectiveWorkspacePath
          : undefined
      if (composerEffectiveWorkspacePath) {
        runDiffWorkspacePath = composerEffectiveWorkspacePath
      }
      const finalPrompt = composerMetadata.finalPrompt
      const discordContextReads = composerMetadata.discordContextReads?.length
        ? redactDiscordContextReadsForHistory(composerMetadata.discordContextReads)
        : request.discordContextSnapshots?.length
          ? redactDiscordContextReadsForHistory(
              request.discordContextSnapshots.map((snapshot) => snapshot.metadata)
            )
          : []
      const projectReferenceContextMetadata = composerMetadata.projectReferenceContext
        ? projectReferenceContextDisclosure(composerMetadata.projectReferenceContext)
        : null
      const displayFinalPrompt = runRequestDisplayPrompt(request, finalPrompt)
      const modelToPass =
        composedPayload.model ||
        request.overrideModel ||
        (request.selectedModelType === 'custom'
          ? request.customModel.trim()
          : request.selectedModelType)
      const modeToPass = composerMetadata.approvalMode
      const workflowModeToPass =
        composerMetadata.workflowMode || composedPayload.workflowMode || request.workflowMode
      const resumeSessionId = composedPayload.providerSessionId || undefined
      const geminiResumeSkippedReason = composerMetadata.geminiResumeSkippedReason
      const contextualPrompt = composedPayload.prompt
      const usagePromptText = discordContextReads.length > 0 ? displayFinalPrompt : contextualPrompt
      const contextApplicationLog = composerMetadata.applicationLog

      activeScheduledTaskIdRef.current = request.scheduledTaskId || null
      const dispatchChatBase = preAppendedPromptMessage
        ? chatByIdRef.current.get(runChat.appChatId) || runChat
        : runChat
      const chatToUpdate = { ...dispatchChatBase, provider: effectiveRunProvider }
      if (composerMetadata.clearLinkedGeminiSession) {
        chatToUpdate.linkedGeminiSessionId = undefined
      }
      const selectedChatIdAtRunStart = currentChatIdRef.current || currentChat?.appChatId || null
      const isRunVisibleAtStart = selectedChatIdAtRunStart === chatToUpdate.appChatId
      liveRunDiffStore.clear(chatToUpdate.appChatId)
      if (isRunVisibleAtStart) {
        setRunCompleteNotice(null)
        setRunDiff(null)
        setPendingPlanChoice(null)
        setPendingProposedPlan(null)
        setPendingPlanImport(null)
        setIsThinking(true)
      }

      if (chatToUpdate.messages.length === 0) {
        chatToUpdate.title = normalizeThreadTitle(displayFinalPrompt, 'New Chat')
      }

      let runStartedAt = new Date().toISOString()
      let promptMessageId: string | undefined
      if (!request.existingPrompt && !preAppendedPromptMessage) {
        const imageAttachmentMetadata = request.imageAttachments
          .map((attachment) => ({
            id: attachment.id,
            path: attachment.path,
            name: attachment.name || getImageName(attachment.path),
            ...attachmentKindMetadata(attachment)
          }))
          .filter((attachment) => Boolean(attachment.path))
        const linkPreviewMetadata = extractHttpUrls(displayFinalPrompt, 8)
        const messageMetadata: ChatMessage['metadata'] = {}
        if (imageAttachmentMetadata.length > 0) {
          messageMetadata.imageAttachments = imageAttachmentMetadata
        }
        const imageThumbnailMetadata = await buildSubmittedImageThumbnailMetadata(
          request.imageAttachments
        )
        if (imageThumbnailMetadata.imagePaths.length > 0) {
          messageMetadata.imagePaths = imageThumbnailMetadata.imagePaths
          messageMetadata.imageThumbnails = imageThumbnailMetadata.imageThumbnails
        }
        if (linkPreviewMetadata.length > 0) {
          messageMetadata.linkPreviews = linkPreviewMetadata
        }
        if (discordContextReads.length > 0) {
          messageMetadata.discordContextReads = discordContextReads
        }
        if (projectReferenceContextMetadata) {
          messageMetadata.projectReferenceContext = projectReferenceContextMetadata
        }
        const userMessage: ChatMessage = {
          id: createMessageId(),
          role: 'user',
          content: displayFinalPrompt,
          timestamp: runStartedAt,
          ...(Object.keys(messageMetadata).length > 0 ? { metadata: messageMetadata } : {})
        }
        promptMessageId = userMessage.id
        chatToUpdate.messages = [...chatToUpdate.messages, userMessage]
        if (discordContextReads.length > 0) {
          chatToUpdate.messages = [
            ...chatToUpdate.messages,
            createDiscordContextToolMessage(discordContextReads, runStartedAt, effectiveRunProvider)
          ]
        }
      } else if (preAppendedPromptMessage) {
        promptMessageId = preAppendedPromptMessage.id
        if (projectReferenceContextMetadata) {
          chatToUpdate.messages = chatToUpdate.messages.map((message) =>
            message.id === preAppendedPromptMessage?.id
              ? {
                  ...message,
                  metadata: {
                    ...(message.metadata || {}),
                    projectReferenceContext: projectReferenceContextMetadata
                  }
                }
              : message
          )
        }
        if (discordContextReads.length > 0) {
          chatToUpdate.messages = [
            ...chatToUpdate.messages,
            createDiscordContextToolMessage(discordContextReads, runStartedAt, effectiveRunProvider)
          ]
        }
      } else {
        const lastUserMessage = [...chatToUpdate.messages]
          .reverse()
          .find((message) => message.role === 'user' && message.metadata?.kind !== 'channelInbound')
        runStartedAt = lastUserMessage?.timestamp || runStartedAt
        promptMessageId = lastUserMessage?.id
      }
      activeRunChatIdRef.current = chatToUpdate.appChatId
      activeRunIdRef.current = currentRunId
      activeRunWorkspacePathRef.current = runDiffWorkspacePath || null
      activeRunStartedAtRef.current = runStartedAt
      activeRunDiffUnavailableRef.current = runDiffUnavailable
      const newRun: ChatRun = {
        runId: currentRunId,
        provider: effectiveRunProvider,
        startedAt: runStartedAt,
        status: 'starting',
        promptMessageId,
        rawEventsFile: `run-events/${currentRunId}.jsonl`,
        requestedModel: modelToPass,
        approvalMode: modeToPass,
        ...(workflowModeToPass ? { workflowMode: workflowModeToPass } : {}),
        runtimeProfileId: request.runtimeProfileId,
        handoffSourceRunId: request.handoffSourceRunId,
        ...(effectiveRunProvider !== 'gemini' && resumeSessionId
          ? { providerThreadId: resumeSessionId }
          : {}),
        ...(composedPayload.providerReroute
          ? { providerReroute: composedPayload.providerReroute }
          : {}),
        ...(runWorktree ? { geminiWorktree: runWorktree } : {}),
        ...(runDiffWorkspacePath ? { effectiveWorkspacePath: runDiffWorkspacePath } : {}),
        ...(runDiffUnavailable ? { diffUnavailableReason: WORKTREE_DIFF_UNAVAILABLE_TEXT } : {}),
        ...(composedPayload.geminiAuthProfileId
          ? { geminiAuthProfileId: composedPayload.geminiAuthProfileId }
          : {}),
        ...(composerMetadata.promptEnvelope
          ? { promptEnvelope: composerMetadata.promptEnvelope }
          : {}),
        ...(chatToUpdate.activeGoal && chatToUpdate.activeGoal.status !== 'completed'
          ? {
              activeGoalId: chatToUpdate.activeGoal.id,
              activeGoalStatusAtStart: chatToUpdate.activeGoal.status
            }
          : {})
      }
      chatToUpdate.runs = [...(chatToUpdate.runs || []), newRun]
      if (composerMetadata.providerMetadataPatch) {
        chatToUpdate.providerMetadata = {
          ...(chatToUpdate.providerMetadata || {}),
          ...composerMetadata.providerMetadataPatch
        }
      }
      if (composerMetadata.uiNoticeMessage) {
        setChatContextNotice({
          id: `${Date.now()}-${composerMetadata.codexHandoffApplied?.handoffKey || 'context'}`,
          message: composerMetadata.uiNoticeMessage
        })
      }

      const runChatId = chatToUpdate.appChatId
      activeRunChatSnapshotRef.current = chatToUpdate
      chatByIdRef.current.set(runChatId, chatToUpdate)
      setRunningChatIds((prev) => {
        const next = new Set(prev)
        next.add(runChatId)
        return next
      })
      if (isRunVisibleAtStart) {
        setCurrentChat(chatToUpdate)
      }
      setChats((prev) => {
        const index = prev.findIndex((chat) => chat.appChatId === runChatId)
        if (index < 0) return [chatToUpdate, ...prev]
        return prev.map((chat) => (chat.appChatId === runChatId ? chatToUpdate : chat))
      })
      window.api.saveChat(chatToUpdate)
      const promptLogContent =
        discordContextReads.length > 0
          ? `User prompt (pre-composition): ${displayFinalPrompt}\n\n[${discordContextReads.length} Discord context snapshot(s) supplied to provider; run-only Discord message content omitted from Inspector log.]`
          : `TaskWraith-composed prompt (before provider adapter): ${contextualPrompt}`
      const initialRawLogs: RawLogEntry[] = [
        { type: 'info', content: contextApplicationLog },
        { type: 'info', content: promptLogContent },
        { type: 'info', content: `Requested model: ${modelToPass}` },
        { type: 'info', content: `Approval Mode: ${modeToPass}` },
        ...(geminiResumeSkippedReason
          ? [{ type: 'info' as const, content: geminiResumeSkippedReason }]
          : []),
        ...(resumeSessionId
          ? [
              {
                type: 'info' as const,
                content: `Resuming ${getProviderLabel(effectiveRunProvider)} session: ${resumeSessionId}`
              }
            ]
          : []),
        ...(runWorktree?.enabled
          ? [
              {
                type: 'info' as const,
                content: `Gemini worktree: ${runWorktree.name || 'enabled'}${runDiffWorkspacePath ? ` (diff path: ${runDiffWorkspacePath})` : ' (effective path unknown; Diff Studio disabled)'}`
              }
            ]
          : []),
        ...(runtimeWorktreeIntent?.status === 'selected'
          ? [
              {
                type: 'info' as const,
                content: `Composer worktree: ${runtimeWorktreeIntent.effectiveWorkspacePath || 'selected'}`
              }
            ]
          : [])
      ]
      setThreadRawLogs(runChatId, initialRawLogs)
      triggerFxBurst('run-start')
      setIsRunning(true)
      setDiffRefreshStatus('')

      let preSnapshot: any = null
      try {
        if (runDiffUnavailable) {
          setDiff(createWorktreeDiffUnavailable())
          setDiffView('workspace')
          setDiffRefreshStatus('Diff disabled: worktree path unknown.')
        } else if (runDiffWorkspacePath) {
          preSnapshot = await window.api.captureSnapshot(runDiffWorkspacePath)
        }
      } catch {
        preSnapshot = null
      }
      preSnapshotRef.current = preSnapshot

      const isVisibleRunChat = () => currentChatIdRef.current === runChatId
      const runContext = {} as ActiveRunContext
      const providerModelMetadataForAssistantDelta = (
        updated: ChatRecord,
        model?: string,
        modelLabel?: string
      ) => {
        const currentRun =
          updated.runs?.find((run) => run.runId === currentRunId) ||
          updated.runs?.[updated.runs.length - 1]
        const resolvedModel = model || currentRun?.actualModel || currentRun?.requestedModel || ''
        const resolvedLabel = modelLabel || humaniseModelId(effectiveRunProvider, resolvedModel)
        const reasoningEffort =
          effectiveRunProvider === 'codex'
            ? request.codexReasoningEffort
            : effectiveRunProvider === 'claude'
              ? request.claudeReasoningEffort
              : effectiveRunProvider === 'kimi'
                ? request.kimiReasoningEffort
                : effectiveRunProvider === 'grok'
                  ? request.grokReasoningEffort
                  : effectiveRunProvider === 'cursor'
                    ? request.cursorReasoningEffort
                    : effectiveRunProvider === 'ollama'
                      ? request.ollamaReasoningEffort
                      : effectiveRunProvider === 'pi'
                        ? request.piReasoningEffort
                        : effectiveRunProvider === 'mistral'
                          ? request.mistralReasoningEffort
                          : effectiveRunProvider === 'muse'
                            ? request.museReasoningEffort
                            : effectiveRunProvider === 'antigravity'
                              ? request.antigravityReasoningEffort
                              : undefined
        return {
          assistantProvider: effectiveRunProvider,
          ...(resolvedModel ? { providerModel: resolvedModel } : {}),
          ...(resolvedLabel ? { providerModelLabel: resolvedLabel } : {}),
          ...(reasoningEffort ? { assistantReasoningEffort: reasoningEffort } : {}),
          ...(effectiveRunProvider === 'kimi' && typeof request.kimiThinkingEnabled === 'boolean'
            ? { assistantThinkingEnabled: request.kimiThinkingEnabled }
            : {})
        }
      }
      const adapter = new GeminiStreamAdapter((event: NormalizedEvent) => {
        if (event.type === 'run_item_event') {
          const itemEvent = event.event
          runStreamMetricsByRunIdRef.current.set(
            itemEvent.runId,
            recordRunItemMetric(
              runStreamMetricsByRunIdRef.current.get(itemEvent.runId),
              itemEvent,
              Date.now()
            )
          )
          const sidecarProjection = projectRunItemAssistantDelta(itemEvent)
          if (sidecarProjection && sidecarProjection.chatId === runChatId) {
            updateChatById(
              runChatId,
              (source) => {
                // Same-reference returns are the no-op signal: no flush, no
                // saveChat re-arm. Never spread before these guards.
                if (source.chatKind === 'ensemble') return source
                if (steerSuppressionChatIdsRef.current.has(runChatId)) return source
                const updated = { ...source }
                if (isVisibleRunChat()) setIsThinking(false)
                const providerModelMetadata = providerModelMetadataForAssistantDelta(
                  updated,
                  itemEvent.kind === 'item/delta' ? itemEvent.model : undefined,
                  itemEvent.kind === 'item/delta' ? itemEvent.modelLabel : undefined
                )
                const projection = projectRunItemAssistantDelta(itemEvent, providerModelMetadata)
                if (!projection) return source
                updated.messages = applyAssistantDelta(updated.messages, projection.input, {
                  createMessageId,
                  now: () => new Date().toISOString()
                })
                recordPendingStreamFlush(
                  projection.runId,
                  projection.itemId,
                  projection.input.incoming.length
                )
                return updated
              },
              { coalesce: true, persistence: 'transcript-tail' }
            )
          }
          const toolProjections = projectRunItemToolEvents(itemEvent, effectiveRunProvider).filter(
            (projection) => projection.chatId === runChatId
          )
          if (toolProjections.length > 0) {
            toolProjections.forEach((projection) => {
              if (projection.event.isUse && isProviderExecutionToolEvent(projection.event)) {
                runContext.toolCallsCount += 1
              }
            })
            updateChatById(
              runChatId,
              (source) => {
                // Same-reference return = no-op (no flush, no saveChat re-arm);
                // ensemble transcripts are orchestrator-canonical.
                if (source.chatKind === 'ensemble') return source
                const updated = { ...source }
                // The assistant-delta handler hides the Working indicator while
                // the bubble streams; tool traffic after the bubble seals means
                // the run is still live, so re-arm it or the transcript shows
                // no indicator at all for the rest of the tool phase.
                if (isVisibleRunChat() && !steerSuppressionChatIdsRef.current.has(runChatId)) {
                  setIsThinking(true)
                }
                let nextMessages = updated.messages
                for (const projection of toolProjections) {
                  const reduction = reduceSoloToolEventMessages(nextMessages, projection.event, {
                    createMessageId,
                    provider: effectiveRunProvider,
                    runId: currentRunId
                  })
                  nextMessages = reduction.messages
                  if (
                    isVisibleRunChat() &&
                    !runContext.diffUnavailable &&
                    reduction.latestToolActivity &&
                    reduction.isResult
                  ) {
                    upsertRunDiffFromTool(
                      runChatId,
                      reduction.latestToolActivity,
                      runContext.workspacePath
                    )
                  }
                }
                updated.messages = nextMessages
                return updated
              },
              { coalesce: true }
            )
          }
          return
        }

        if (event.type === 'raw_event') {
          // TaskWraith's own provider notices (Kimi runtime admission, the
          // Kimi/Pi compatibility filter) no longer get a transcript card, and
          // the deferred entry below is an unreadable JSON dump until something
          // materializes it. Emit an eager, prefixed line so the Inspector has
          // one shape to find — byte-identical to the run-event summary main
          // persists for the same payload, so a rehydrated ring reads the same.
          const diagnosticNotice = readProviderDiagnosticNotice(event.data)
          if (diagnosticNotice) {
            appendThreadRawLog(runChatId, {
              type: 'info',
              content: formatProviderDiagnosticNotice(diagnosticNotice)
            })
          }
          // Keep the parsed payload unformatted in the bounded ring. Recursive
          // truncation, pretty-printing and redaction happen only when a
          // visible Raw Events/terminal consumer asks for this entry.
          const deferredLog = deferredRawLogEntry('stdout', event.data)
          // This lane is heuristic text sniffing over EVERY raw event: any
          // tool output that merely contained "access denied" / "needs
          // access to" popped the attachment modal — Full Access runs
          // saw it constantly. The modal's contract: only a READ-ONLY
          // posture blocked from an attachment OUTSIDE the workspace needs
          // the prompt; write postures already hold the access, and real
          // provider refusals surface through the classified error lane.
          const permissionRequest =
            modeToPass === 'plan' ? parseGeminiPermissionRequest(event.data) : null
          if (permissionRequest && isVisibleRunChat()) {
            const outsidePaths = attachmentPathsOutsideWorkspace(
              permissionRequest.paths,
              runContext.workspacePath
            )
            if (outsidePaths.length > 0) {
              showAttachmentPermissionRequest({
                ...permissionRequest,
                paths: outsidePaths,
                message: redactLog(permissionRequest.message)
              })
            }
          }
          const rawEventRecord =
            event.data && typeof event.data === 'object' && !Array.isArray(event.data)
              ? (event.data as Record<string, unknown>)
              : null
          const rawEventType =
            typeof rawEventRecord?.type === 'string' ? rawEventRecord.type.toLowerCase() : ''
          const isExitRawEvent =
            rawEventType === 'process_exit' ||
            rawEventType === 'provider_exit' ||
            rawEventType === 'exit'
          const rawExitCode =
            typeof rawEventRecord?.exitCode === 'number'
              ? rawEventRecord.exitCode
              : typeof rawEventRecord?.code === 'number'
                ? rawEventRecord.code
                : undefined
          const exitMatch =
            isExitRawEvent && rawExitCode === undefined
              ? rawLogEntryContent(deferredLog).match(/Process exited with code\s+(\d+)/i)
              : null
          const exitCode = rawExitCode ?? (exitMatch ? Number(exitMatch[1]) : undefined)
          if (isExitRawEvent && Number.isFinite(exitCode)) {
            const suppressRawCompletionNotice =
              steerSuppressedSummaryRunIdsRef.current.has(currentRunId) ||
              intentionalCancelRunIdsRef.current.has(currentRunId)
            if (exitCode === 0 && isVisibleRunChat() && !suppressRawCompletionNotice) {
              // Skip per-participant notice for ensemble (round-level
              // effect handles it). Same reasoning as the main exit
              // handler above.
              const runChat = chatByIdRef.current.get(runChatId)
              if (runChat?.chatKind !== 'ensemble') {
                setRunCompleteNotice({
                  timestamp: new Date().toISOString(),
                  exitCode,
                  startedAt: runContext.startedAt || undefined
                })
              }
              return
            }
          }
          const isTool =
            event.data.type === 'tool_use' ||
            event.data.type === 'tool_result' ||
            [
              'update_topic',
              'invoke_agent',
              'summary',
              'intent',
              'progress',
              'tool_progress'
            ].includes(String(event.data.type || ''))
          deferredLog.type = isTool ? 'tool' : 'stdout'
          appendThreadRawLog(runChatId, deferredLog)
          return
        }
        if (event.type === 'malformed_json') {
          appendThreadRawLog(runChatId, {
            type: 'stdout',
            content: redactLog(event.text)
          })
          return
        }
        if (event.type === 'assistant_media_refs') {
          // RAW provider lane (GeminiAdapter → here): the provider controls
          // every field of these refs, so SANITIZE before merging onto the
          // transcript — drop hostile `path`s (the desktop "Open file" overlay
          // calls api.openExternalOrPath on them), oversize/non-raster
          // thumbnails, svg/unknown mimes, and fake sources. Shared with the
          // main-side ensemble + bridge ingestion points so the policy can't
          // drift (src/shared/transcriptMediaRefSanitize.ts). This is the
          // forgeable lane — it MUST keep sanitizing; only the trusted
          // main-only `run-trusted-media-refs` IPC bypasses the sanitizer.
          applyAssistantMediaRefsToChat(runChatId, sanitizeRawProviderMediaRefs(event.mediaRefs))
          return
        }
        if (event.type === 'assistant_message_delta' && event.projectedFromRunItem === true) {
          // The run-item sidecar on the SAME stdout line already carried this
          // delta (the adapter sets the flag only when a non-empty
          // channel:'assistant' item/delta rode the line), and the
          // run_item_event handler above is the sole applier — its
          // ensemble/steer guards mirror the legacy reducer's, so any state
          // where the sidecar no-ops the legacy would have no-oped too.
          // Skip unconditionally rather than consulting a content-keyed set:
          // the previous keyed lookup embedded the compat mapper's
          // synthesized `<runId>:assistant` itemId on the record side but the
          // legacy event's (absent) itemId on the lookup side, so every
          // provider whose legacy content lines carry no itemId
          // (Claude/Kimi/Grok/Ollama) double-applied each increment. A keyed
          // set is also structurally weaker here: byte-identical repeated
          // deltas collapse to one entry, and the record-side add lives
          // inside a reducer that can defer behind async chat hydration
          // while this check runs synchronously.
          return
        }
        if (event.type === 'tool_event' && event.projectedFromRunItem === true) {
          // The run-item sidecar on the SAME stdout line already carried this
          // tool row (the adapter sets the flag only when a tool/progress or
          // tool/outputDelta rode the line), and the run_item_event handler
          // above is the sole applier — its ensemble/steer guards mirror the
          // legacy reducer's, so any state where the sidecar no-ops the legacy
          // would have no-oped too.
          //
          // Skip unconditionally rather than consulting a content-keyed set.
          // The keyed lookup this replaces had three independent ways to miss,
          // each of which rendered one call as two rows (2026-08-05, reported
          // as "shell commands always appear twice"):
          //   - the two lanes resolved the tool NAME from different fallback
          //     chains, so the name key diverged (now shared — see
          //     src/shared/toolEventNaming.ts) while the id key could never
          //     match a synthesized `<runId>:tool-N` against a legacy line
          //     that carries no id at all;
          //   - a Set collapses two idless calls to the same tool into ONE
          //     name key, and the lookup deletes it, so the second doubled;
          //   - the record-side add lives inside a reducer that defers behind
          //     async chat hydration while this check runs synchronously, so
          //     during that window EVERY row doubled.
          // Mirrors the assistant-delta lane above; keep the two symmetric.
          return
        }

        let finalizedProviderChangeChat: ChatRecord | null = null
        let finalizedProviderChangeChatId: string | null = null
        updateChatById(
          runChatId,
          (source) => {
            let updated = { ...source }

            // Steer suppression: while the user has clicked Steer and the
            // cancel is in flight, drop in-flight assistant content so the
            // provider's farewell wrap-up doesn't pollute the transcript
            // with a mid-flow "final summary." See `handleSteer`.
            const isSteerSuppressed =
              (event.type === 'assistant_message_delta' ||
                event.type === 'assistant_message_complete') &&
              steerSuppressionChatIdsRef.current.has(runChatId)
            if (isSteerSuppressed) {
              // Same-reference return = no-op: no flush, no saveChat re-arm.
              return source
            }

            if (event.type === 'user_message') {
              // Handled manually before run — nothing changes here.
              return source
            } else if (event.type === 'assistant_message_delta') {
              // Ensemble transcripts are materialised by EnsembleOrchestrator
              // (`flushRun` → chat-updated). Provider compat lines still reach
              // the renderer, but merging them here races the orchestrator and
              // can stamp Ollama `providerModel` metadata onto the wrong
              // assistant bubble (backward-scan finds another participant's
              // message). Skip transcript mutation; orchestrator is canonical.
              // Also leave `isThinking` alone — compat deltas are noise for
              // ensemble rounds and were clearing the indicator until the next
              // user turn. Same-reference return = no flush, no saveChat re-arm.
              if (updated.chatKind === 'ensemble') {
                return source
              }
              if (isVisibleRunChat()) setIsThinking(false)
              // Interleaving-preserving routing. A content delta continues
              // the live bubble ONLY while the trailing message is still an
              // assistant; once a tool burst is the trailing message the text
              // segment is sealed and the next delta opens a NEW bubble AFTER
              // the burst. This mirrors the iOS stream (af91f0be — "seal a
              // text segment at every tool boundary") and the main bridge
              // transcript (`appendBridgeRunText`). The previous code scanned
              // backward PAST tool messages and merged every later delta into
              // the first bubble of the turn, which pulled prose up out of its
              // position and left the tail a tool message — so every tool
              // burst coalesced into one ActivityStack rendered above the text.
              const incomingItemId = (event as { itemId?: unknown }).itemId
              const incomingItemIdStr =
                typeof incomingItemId === 'string' && incomingItemId ? incomingItemId : undefined
              // Ollama stamps the streaming bubble with its provider model so the
              // transcript can show which local model produced the text.
              const providerModelMetadata = providerModelMetadataForAssistantDelta(
                updated,
                typeof event.model === 'string' && event.model ? event.model : undefined,
                typeof event.modelLabel === 'string' && event.modelLabel
                  ? event.modelLabel
                  : undefined
              )
              // Interleaving-preserving routing, idempotent increment-vs-
              // restatement merge, and Codex item separators all live in
              // lib/applyAssistantDelta (pure + unit-tested). It returns a new
              // messages array; the ref write-back happens in updateChatById.
              updated.messages = applyAssistantDelta(
                updated.messages,
                {
                  incoming: event.content,
                  runId: currentRunId,
                  cumulative: event.cumulative === true,
                  itemId: incomingItemIdStr,
                  providerModelMetadata
                },
                { createMessageId, now: () => new Date().toISOString() }
              )
              if (currentRunId && event.content) {
                recordPendingStreamFlush(currentRunId, incomingItemIdStr, event.content.length)
              }
            } else if (event.type === 'assistant_message_complete') {
              if (isVisibleRunChat() && updated.chatKind !== 'ensemble') setIsThinking(false)
              const providerModelMetadata = providerModelMetadataForAssistantDelta(updated)
              const lastRun = updated.runs?.[updated.runs.length - 1]
              const lastWorkflowMode = lastRun?.workflowMode || updated.workflowMode
              const isPlanMode = lastRun?.approvalMode === 'plan' && lastWorkflowMode === 'plan'
              const parsedChoice = parsePlanModeChoice(event.content)
              // The complete event carries the FULL turn, so treat it as a
              // cumulative restatement: it may reach back across a trailing
              // tool burst to replace its own bubble in place. Without this an
              // interleaved turn (text → tool burst → complete) would append a
              // duplicate full-turn bubble below the tools.
              const completeTarget = resolveAssistantDeltaTarget(updated.messages, {
                incoming: event.content,
                cumulative: true,
                // A system card (queued-run record, question marker, terminal
                // compaction card) landing after the last delta must not hide
                // the streamed bubbles from the dedupe — without this the full
                // turn re-appends below the card.
                spanTrailingSystemCards: true,
                // A mid-run steering row is a transcript boundary, not a
                // provider-turn boundary. Reconcile the final envelope across
                // it without duplicating pre-interjection prose below it.
                spanMidRunSteeringMessages: true
              })
              // The complete event restates the FULL turn. A `merge`/`replaceText`
              // targets an existing bubble; `skip` means the streamed deltas
              // already rendered it (don't duplicate); `appendText`/`append` open
              // a fresh post-tool bubble with only the tail / the content.
              const completeTargetIdx =
                completeTarget.action === 'merge' || completeTarget.action === 'replaceText'
                  ? completeTarget.index
                  : -1
              const completeTargetMsg =
                completeTargetIdx >= 0 ? updated.messages[completeTargetIdx] : null
              // assistantMessageId anchors the plan-mode choice below — reuse the
              // targeted bubble's id, else the trailing assistant's, else a new id.
              const trailingAssistantForId =
                updated.messages.length > 0 &&
                updated.messages[updated.messages.length - 1].role === 'assistant'
                  ? updated.messages[updated.messages.length - 1]
                  : null
              const newCompleteMessageId = createMessageId()
              const assistantMessageId =
                completeTargetMsg?.id ?? trailingAssistantForId?.id ?? newCompleteMessageId

              if (updated.chatKind !== 'ensemble') {
                if (completeTarget.action === 'skip') {
                  // Already rendered by the streamed deltas — no-op.
                } else if (
                  (completeTarget.action === 'merge' || completeTarget.action === 'replaceText') &&
                  completeTargetMsg
                ) {
                  const nextContent =
                    completeTarget.action === 'replaceText' ? completeTarget.text : event.content
                  updated.messages = [
                    ...updated.messages.slice(0, completeTargetIdx),
                    {
                      ...completeTargetMsg,
                      content: nextContent,
                      runId: completeTargetMsg.runId ?? currentRunId,
                      metadata: {
                        ...(completeTargetMsg.metadata || {}),
                        ...providerModelMetadata
                      }
                    },
                    ...updated.messages.slice(completeTargetIdx + 1)
                  ]
                } else {
                  const content =
                    completeTarget.action === 'appendText' ? completeTarget.text : event.content
                  updated.messages = [
                    ...updated.messages,
                    {
                      id: newCompleteMessageId,
                      role: 'assistant',
                      content,
                      runId: currentRunId,
                      timestamp: new Date().toISOString(),
                      metadata: providerModelMetadata
                    }
                  ]
                }
              }
              const resetHints = extractResetHintsFromText(event.content)
              for (const hint of resetHints) {
                const key = normalizeModelName(hint.model)
                const existing = runContext.usageResetHints.get(key) || {}
                runContext.usageResetHints.set(key, mergeUsageReset(existing, hint))
              }
              if (resetHints.length > 0) {
                Promise.all(
                  resetHints.map((hint) =>
                    window.api.recordUsage({
                      provider: effectiveRunProvider,
                      workspaceId: getUsageWorkspaceIdForChat(updated) || GLOBAL_USAGE_WORKSPACE_ID,
                      chatId: updated.appChatId,
                      runId: currentRunId,
                      usageKind: 'reset_hint',
                      model: hint.model,
                      inputTokens: 0,
                      outputTokens: 0,
                      totalTokens: 0,
                      resetAt: hint.resetAt,
                      resetText: hint.resetText,
                      durationMs: 0
                    })
                  )
                ).then(() => {
                  const usageWorkspaceId = getUsageWorkspaceIdForChat(updated)
                  if (
                    usageWorkspaceId &&
                    (currentWorkspaceIdRef.current === usageWorkspaceId || isGlobalChat(updated))
                  ) {
                    void refreshUsageSummary(usageWorkspaceId)
                  }
                })
              }
              if (isVisibleRunChat()) {
                // Plan mode surfaces ONE card per turn: a choice (question +
                // options) takes precedence; otherwise a proposed plan (an
                // explicit <proposed_plan> block in any mode, or a substantive
                // plan-mode turn) gets the approve/implement card.
                // Solo plan-mode runs still parse <proposed_plan> inline to derive
                // title/body. Ensemble transcripts are authored by the
                // orchestrator, so they hydrate pending modal state from existing
                // metadata instead.
                const parsedPlan =
                  parsedChoice || updated.chatKind === 'ensemble'
                    ? null
                    : parseProposedPlan(event.content, isPlanMode)
                setPendingPlanChoice(
                  isPlanMode && parsedChoice
                    ? {
                        messageId: assistantMessageId,
                        question: parsedChoice.question,
                        options: parsedChoice.options
                      }
                    : null
                )
                if (parsedPlan) {
                  // Persist the plan on its message so the card survives reload +
                  // the decision, and strip the raw <proposed_plan> block so it
                  // doesn't double-render as prose beside the card. Anchor to the
                  // message that actually holds the plan: the resolved id when it
                  // exists, else the last assistant bubble — `assistantMessageId`
                  // can be a phantom id on the skip branch when the turn ends on a
                  // tool burst (the plan streamed into the pre-burst bubble).
                  const planTargetId = updated.messages.some((m) => m.id === assistantMessageId)
                    ? assistantMessageId
                    : [...updated.messages].reverse().find((m) => m.role === 'assistant')?.id
                  updated.messages = updated.messages.map((m) =>
                    m.id === planTargetId
                      ? {
                          ...m,
                          content: stripProposedPlanBlock(m.content),
                          metadata: {
                            ...(m.metadata || {}),
                            proposedPlan: {
                              ...(m.metadata?.proposedPlan || {}),
                              title: parsedPlan.title,
                              body: parsedPlan.body,
                              status: 'pending' as const
                            }
                          }
                        }
                      : m
                  )
                  if (planTargetId) {
                    setPendingProposedPlan({
                      messageId: planTargetId,
                      title: parsedPlan.title,
                      body: parsedPlan.body,
                      artifactPath: updated.messages.find((message) => message.id === planTargetId)
                        ?.metadata?.proposedPlan?.artifactPath
                    })
                  }
                } else if (updated.chatKind === 'ensemble') {
                  const pendingEnsembleProposedPlan = [...updated.messages]
                    .reverse()
                    .find((message) => {
                      const proposedPlan = message.metadata?.proposedPlan
                      if (!proposedPlan || proposedPlan.status !== 'pending') return false

                      const messageParticipantId =
                        typeof message.metadata?.ensembleParticipantId === 'string'
                          ? message.metadata?.ensembleParticipantId
                          : undefined

                      return shouldSurfaceProposedPlanCard({
                        chatKind: 'ensemble',
                        bossmanParticipantId: updated.ensemble?.bossmanParticipantId,
                        fallbackOwnerParticipantId: undefined,
                        messageParticipantId,
                        isPlanMode,
                        hasExplicitProposedPlanBlock: true
                      })
                    })

                  if (pendingEnsembleProposedPlan?.metadata?.proposedPlan) {
                    setPendingProposedPlan({
                      messageId: pendingEnsembleProposedPlan.id,
                      title: pendingEnsembleProposedPlan.metadata.proposedPlan.title,
                      body: pendingEnsembleProposedPlan.metadata.proposedPlan.body,
                      artifactPath: pendingEnsembleProposedPlan.metadata.proposedPlan.artifactPath
                    })
                  }
                }
              }
            } else if (event.type === 'run_started') {
              const promptDeliveryPatch = promptDeliveryReceiptMetadataPatch(
                (composerMetadata as { promptDeliveryReceipts?: PromptDeliveryReceipts })
                  .promptDeliveryReceipts,
                effectiveRunProvider
              )
              if (Object.keys(promptDeliveryPatch).length > 0) {
                updated.providerMetadata = {
                  ...(updated.providerMetadata || {}),
                  ...promptDeliveryPatch
                }
              }
              const sessionId = normalizeGeminiResumeTarget(event.session_id)
              if (sessionId && (effectiveRunProvider !== 'gemini' || !event.fallback)) {
                if (effectiveRunProvider !== 'gemini') {
                  updated.linkedProviderSessionId = sessionId
                  if (effectiveRunProvider === 'kimi' && event.kimiAcpNativeSession) {
                    updated.providerMetadata = {
                      ...(updated.providerMetadata || {}),
                      kimiAcpNativeSession: true,
                      ...(event.kimiAcpPostureVersion
                        ? { kimiAcpPostureVersion: event.kimiAcpPostureVersion }
                        : {})
                    }
                  }
                } else {
                  updated.linkedGeminiSessionId = sessionId
                }
              }
              const runs = [...(updated.runs || [])]
              const runIndex = findChatRunIndex(runs, currentRunId)
              if (runIndex >= 0) {
                const targetRun = runs[runIndex]
                const nextModel = typeof event.model === 'string' ? event.model.trim() : ''
                // Model-less follow-up inits (Muse opaque exec) must not clobber a
                // real requested/actual model with '' or the old 'unknown' sentinel.
                const keepModel =
                  !nextModel || nextModel.toLowerCase() === 'unknown'
                    ? targetRun.actualModel
                    : nextModel
                runs[runIndex] = {
                  ...targetRun,
                  actualModel: keepModel,
                  ...(effectiveRunProvider !== 'gemini'
                    ? { providerThreadId: sessionId || targetRun.providerThreadId }
                    : {})
                }
              }
              updated.runs = runs
            } else if (event.type === 'run_finished') {
              if (isVisibleRunChat()) setIsThinking(false)
              const runs = [...(updated.runs || [])]
              const renderMetrics = drainStreamRenderMetrics(currentRunId)
              const streamMetrics = renderMetrics
                ? mergeRunStreamRenderMetrics(
                    runStreamMetricsByRunIdRef.current.get(currentRunId),
                    currentRunId,
                    renderMetrics,
                    Date.now()
                  )
                : runStreamMetricsByRunIdRef.current.get(currentRunId)
              // Terminal: the merged metrics ride the persisted run stats below;
              // drop the live entry so long sessions don't retain one per run.
              runStreamMetricsByRunIdRef.current.delete(currentRunId)
              const finishedStats = streamMetrics
                ? { ...(event.stats || {}), streamMetrics }
                : event.stats
              const finishedSessionId = normalizeGeminiResumeTarget(event.providerThreadId)
              if (finishedSessionId && effectiveRunProvider !== 'gemini') {
                updated.linkedProviderSessionId = finishedSessionId
              }
              const runIndex = findChatRunIndex(runs, currentRunId)
              const targetRun = runIndex >= 0 ? runs[runIndex] : undefined
              const resolvedRunModel =
                targetRun?.actualModel || targetRun?.requestedModel || 'unknown'
              const runUsageEntries = extractModelUsageEntriesFromStats(
                finishedStats || {},
                resolvedRunModel
              )

              if (runIndex >= 0 && targetRun) {
                runs[runIndex] = {
                  ...targetRun,
                  status: event.status,
                  stats: finishedStats,
                  endedAt: new Date().toISOString(),
                  ...(finishedSessionId && effectiveRunProvider !== 'gemini'
                    ? { providerThreadId: finishedSessionId }
                    : {})
                }
              }
              updated.runs = runs
              if (updated.chatKind !== 'ensemble') {
                const nextChat = applyPendingProviderChangeOnFinalize(
                  applyPendingEnsembleRosterPresetOnRunTerminal(updated, currentRunId)
                )
                if (nextChat !== updated) {
                  updated = nextChat
                  finalizedProviderChangeChat = nextChat
                  finalizedProviderChangeChatId = nextChat.appChatId
                }
              }

              const runDurationMs = Math.max(
                0,
                extractUsageCount(finishedStats, [['duration_ms'], ['durationMs']])
              )

              const usageAlreadyRecorded = Boolean(finishedStats?._taskwraith_usage_recorded)
              const usageRecordPromises = usageAlreadyRecorded
                ? []
                : runUsageEntries.map((usageEntry) => {
                    const {
                      model,
                      costRateModel,
                      inputTokens,
                      outputTokens,
                      totalTokens,
                      cacheReadInputTokens,
                      cacheCreationInputTokens,
                      inputTokenLimit,
                      outputTokenLimit,
                      totalTokenLimit,
                      resetAt,
                      resetText,
                      durationMs: entryDurationMs
                    } = usageEntry
                    const resetHint =
                      runContext.usageResetHints.get(normalizeModelName(model)) || {}
                    const mergedReset = mergeUsageReset({ resetAt, resetText }, resetHint)

                    return window.api.recordUsage({
                      provider: effectiveRunProvider,
                      workspaceId: getUsageWorkspaceIdForChat(updated) || GLOBAL_USAGE_WORKSPACE_ID,
                      chatId: updated.appChatId,
                      runId: currentRunId,
                      usageKind: 'run',
                      model,
                      costRateModel,
                      inputTokens,
                      outputTokens,
                      totalTokens,
                      cacheReadInputTokens,
                      cacheCreationInputTokens,
                      inputTokenLimit,
                      outputTokenLimit,
                      totalTokenLimit,
                      resetAt: mergedReset.resetAt,
                      resetText: mergedReset.resetText,
                      durationMs: entryDurationMs ?? runDurationMs,
                      ...(effectiveRunProvider === 'ollama'
                        ? ollamaMemoryUsageFields(event.stats)
                        : {}),
                      promptText: usagePromptText,
                      responseText:
                        updated.messages[updated.messages.length - 1]?.role === 'assistant'
                          ? updated.messages[updated.messages.length - 1].content
                          : undefined
                    })
                  })

              Promise.all(usageRecordPromises).then(() => {
                const usageWorkspaceId = getUsageWorkspaceIdForChat(updated)
                if (
                  usageWorkspaceId &&
                  (currentWorkspaceIdRef.current === usageWorkspaceId || isGlobalChat(updated))
                ) {
                  void refreshUsageSummary(usageWorkspaceId)
                }
              })
            } else if (event.type === 'tool_event') {
              // Ensemble tool rows are materialised by EnsembleOrchestrator
              // (`flushRun` -> chat-updated). The renderer's solo reducer
              // would append a second local tool message for the same provider
              // compat event, which is especially visible for ensemble_yield
              // because yield activities intentionally stay inline.
              // Same-reference return = no flush, no saveChat re-arm.
              if (updated.chatKind === 'ensemble') {
                return source
              }
              // Mirrors the run-item lane above: text deltas hide the Working
              // indicator, so trailing tool activity must re-arm it.
              if (isVisibleRunChat() && !steerSuppressionChatIdsRef.current.has(runChatId)) {
                setIsThinking(true)
              }
              if (isProviderExecutionToolEvent(event)) {
                runContext.toolCallsCount += 1
              }
              const reduction = reduceSoloToolEventMessages(updated.messages, event, {
                createMessageId,
                provider: effectiveRunProvider,
                runId: currentRunId
              })
              updated.messages = reduction.messages

              if (
                isVisibleRunChat() &&
                !runContext.diffUnavailable &&
                reduction.latestToolActivity &&
                reduction.isResult
              ) {
                upsertRunDiffFromTool(
                  runChatId,
                  reduction.latestToolActivity,
                  runContext.workspacePath
                )
              }
            } else if (event.type === 'workflow_telemetry') {
              // Claude-native Workflow live status. Merge onto the originating
              // `Workflow` tool activity (found by tool_use id anywhere in the
              // transcript) so the workflow card updates in place; no new tool row.
              if (event.toolUseId) {
                updated.messages = mergeWorkflowTelemetryIntoMessages(
                  updated.messages,
                  event.toolUseId,
                  event.telemetry
                )
              }
            } else if (event.type === 'review_telemetry') {
              // Codex native-review live status. Merge onto the synthesized
              // `codex_review` anchor activity so the review card updates in place.
              if (event.toolUseId) {
                updated.messages = mergeReviewTelemetryIntoMessages(
                  updated.messages,
                  event.toolUseId,
                  event.telemetry
                )
              }
            } else if (event.type === 'multi_agent_telemetry') {
              // Codex native Multi-agent live status. Merge onto the synthesized
              // `codex_multi_agent` anchor so the orchestration card updates in
              // place; coordination never becomes a generic tool row.
              if (event.toolUseId) {
                updated.messages = mergeMultiAgentTelemetryIntoMessages(
                  updated.messages,
                  event.toolUseId,
                  event.telemetry
                )
              }
            } else if (event.type === 'compaction_notice') {
              // Provider context compaction. Persist a system card for terminal
              // signals; 'started' stays transient (no row). Ensemble transcripts
              // are orchestrator-canonical — the same compat line reaches the
              // orchestrator, which appends the card main-side, so appending here
              // too would double-card (and be clobbered by its saveChat anyway).
              if (event.kind !== 'started' && updated.chatKind !== 'ensemble') {
                const cardId = contextCompactionMessageId(
                  event.telemetry,
                  `${currentRunId}-${event.kind}`
                )
                if (!updated.messages.some((message) => message.id === cardId)) {
                  updated.messages = [
                    ...updated.messages,
                    {
                      id: cardId,
                      role: 'system',
                      content: formatContextCompactionSummary(
                        { kind: event.kind, telemetry: event.telemetry },
                        getProviderLabel(
                          (event.telemetry.provider as ProviderId) || effectiveRunProvider
                        )
                      ),
                      timestamp: new Date().toISOString(),
                      metadata: {
                        kind: CONTEXT_COMPACTION_MESSAGE_KIND,
                        contextCompaction: { kind: event.kind, telemetry: event.telemetry },
                        provider: event.telemetry.provider || effectiveRunProvider
                      }
                    }
                  ]
                }
              }
            } else if (event.type === 'error') {
              updated.messages = [
                ...updated.messages,
                {
                  id: createMessageId(),
                  role: 'error',
                  content: event.message,
                  timestamp: new Date().toISOString()
                }
              ]
            }

            return updated
          },
          {
            coalesce: event.type === 'assistant_message_delta',
            persistence: event.type === 'assistant_message_delta' ? 'transcript-tail' : undefined
          }
        )
        if (
          finalizedProviderChangeChat &&
          currentChatIdRef.current === finalizedProviderChangeChatId
        ) {
          applyChatComposerSelection(
            finalizedProviderChangeChat,
            getChatProvider(finalizedProviderChangeChat)
          )
        }
      })
      Object.assign(runContext, {
        runId: currentRunId,
        chatId: runChatId,
        provider: effectiveRunProvider,
        adapter,
        warnings: currentRunWarningsRef.current,
        usageResetHints: activeRunUsageResetHintsRef.current,
        errorCount: errorCountRef.current,
        toolCallsCount: toolCallsCountRef.current,
        preSnapshot,
        baseWorkspacePath: isGlobalRun ? null : runWorkspace!.path,
        workspacePath: runDiffWorkspacePath || null,
        workspaceId: isGlobalRun ? undefined : runWorkspace!.id,
        worktree: runWorktree,
        checkpointingEnabled:
          effectiveRunProvider === 'gemini' ? geminiCheckpointingEnabled : false,
        startedAt: runStartedAt,
        diffUnavailable: runDiffUnavailable,
        scheduledTaskId: request.scheduledTaskId || null
      })
      activeRunsRef.current.set(currentRunId, runContext)
      adapterRef.current = adapter
      syncRunningState()

      if (!request.existingPrompt && !request.preserveComposer) {
        setChatPromptDraft(runChatId, '')
        clearComposerAttachmentsForSubmittedRequest(request)
      }
      try {
        if (
          effectiveRunProvider === 'codex' &&
          request.codexNativeReview &&
          resumeSessionId &&
          typeof window.api.startAgentReview === 'function'
        ) {
          if (runtimeWorktreeIntent?.status === 'selection-required') {
            throw new Error(
              "Native review can't allocate an isolated worktree. Select a worktree in the composer, or run a normal turn first."
            )
          }
          await window.api.startAgentReview(
            'codex',
            resumeSessionId,
            buildCodexNativeReviewInvocationParams({
              composedPayload,
              model: modelToPass,
              cwd: runDiffWorkspacePath || runWorkspace!.path,
              usagePromptText
            })
          )
          dispatchAccepted = true
          settleProjectReferenceContextForRequest(request, 'rejected')
        } else {
          // Thread scheduledTaskId onto the DISPATCHED payload for a scheduled
          // run. composeRun consumes it (to force the unattended posture) but does
          // NOT echo it onto the payload, and the ensemble path threads it via
          // runEnsembleRound — but the solo path dropped it here. The main-side
          // dispatch chokepoint keys the per-occurrence budget kill, the
          // failover-completion bridge AND the solo main-side completion mark off
          // routedPayload.scheduledTaskId (read PRE-normalize), so without this
          // all three were inert for solo scheduled runs. scheduledTaskId is not
          // part of the signed posture context, so this cannot affect the clamp.
          const dispatchPayload = {
            ...composedPayload,
            usagePromptText,
            ...(runtimeWorktreeIntent ? { runtimeWorktree: runtimeWorktreeIntent } : {}),
            ...(composerEffectiveWorkspacePath
              ? { effectiveWorkspacePath: composerEffectiveWorkspacePath }
              : {}),
            ...(request.scheduledTaskId ? { scheduledTaskId: request.scheduledTaskId } : {})
          } as typeof composedPayload
          const dispatchResult = await window.api.runAgent(dispatchPayload)
          dispatchAccepted = dispatchResult.dispatched
          settleProjectReferenceContextForRequest(
            request,
            dispatchResult.dispatched ? 'accepted' : 'rejected'
          )
          // Main preflight may allocate or reuse an isolated worktree for a
          // selection-required runtime profile; the dispatch result then
          // carries the effective path. Retarget the per-turn diff spine to
          // the worktree the provider actually edits, and re-capture the
          // pre-run snapshot there — a fresh worktree excludes the base
          // checkout's uncommitted state, so the base snapshot would corrupt
          // the per-turn diff.
          const allocatedWorkspacePath =
            dispatchResult.dispatched &&
            typeof dispatchResult.effectiveWorkspacePath === 'string' &&
            dispatchResult.effectiveWorkspacePath.length > 0 &&
            dispatchResult.effectiveWorkspacePath !== runDiffWorkspacePath
              ? dispatchResult.effectiveWorkspacePath
              : null
          if (allocatedWorkspacePath) {
            runDiffWorkspacePath = allocatedWorkspacePath
            activeRunWorkspacePathRef.current = allocatedWorkspacePath
            let allocatedPreSnapshot: any = null
            try {
              allocatedPreSnapshot = await window.api.captureSnapshot(allocatedWorkspacePath)
            } catch {
              allocatedPreSnapshot = null
            }
            preSnapshot = allocatedPreSnapshot
            preSnapshotRef.current = allocatedPreSnapshot
            runContext.preSnapshot = allocatedPreSnapshot
            runContext.workspacePath = allocatedWorkspacePath
            appendThreadRawLog(runChatId, {
              type: 'info',
              content: `Isolated worktree ready: ${allocatedWorkspacePath}`
            })
          }
        }
      } catch (error) {
        settleProjectReferenceContextForRequest(request, 'rejected')
        clearActiveRunContext(runContext)
        const message = `Failed to start ${getProviderLabel(effectiveRunProvider)}: ${redactLog(String(error))}`
        updateRunQueueJobStatus(
          currentRunId,
          'failed',
          'Provider process failed before startup completed.',
          message
        )
        appendThreadRawLog(runChatId, { type: 'stderr', content: message })
        updateChatById(runChatId, (source) => ({
          ...source,
          messages: [
            ...source.messages,
            {
              id: createMessageId(),
              role: 'error',
              content: message,
              timestamp: new Date().toISOString()
            }
          ],
          runs: source.runs.map((run) =>
            run.runId === currentRunId
              ? { ...run, status: 'failed', endedAt: new Date().toISOString() }
              : run
          )
        }))
      }
      await refreshChatList()
    } catch (error) {
      if (requestForClaimCleanup) {
        settleProjectReferenceContextForRequest(requestForClaimCleanup, 'rejected')
      }
      // Last line of defense — any uncaught exception in the function
      // body (between the inner try/catches that wrap composeRun + the
      // runAgent dispatch) surfaces here. Without this catch the void
      // promise rejection vanishes silently.

      console.warn('[executeRun] uncaught exception:', error)
      const message = `Run execution failed unexpectedly: ${redactLog(String(error))}`
      if (
        currentRunIdForCleanup &&
        !dispatchAccepted &&
        !activeRunsRef.current.has(currentRunIdForCleanup)
      ) {
        updateRunQueueJobStatus(
          currentRunIdForCleanup,
          'failed',
          'Run execution failed before provider dispatch.',
          message
        )
      }
      const chatId = runRequest?.chatRecord?.appChatId || currentChat?.appChatId
      if (chatId) {
        appendThreadRawLog(chatId, { type: 'stderr', content: message })
        updateChatById(chatId, (source) => ({
          ...source,
          messages: [
            ...source.messages,
            {
              id: createMessageId(),
              role: 'error',
              content: message,
              timestamp: new Date().toISOString()
            }
          ]
        }))
      }
    }
  }

  const executeRunRef = useRef(executeRun)
  executeRunRef.current = executeRun
  executeExternalPathGrantRunRef.current = (request) => {
    void executeRunRef.current(request)
  }

  const handleReviewCurrentDiff = async () => {
    if (
      !(currentChatWorkspace || currentWorkspace) ||
      !currentGitPresentationPath ||
      !currentChat ||
      isPreparingDiffReview
    ) {
      return
    }

    setIsPreparingDiffReview(true)

    try {
      const diffObj = await window.api.getDiff(currentGitPresentationPath)
      setDiff(diffObj)
      setDiffView('workspace')
      openInspectorTab('diff')

      // 1.0.4-AT5 — surface a clear distinction between Codex's
      // native `/review` (only fires when the solo path resumes a
      // linked Codex thread via `startAgentReview`) and the
      // ensemble-mode prompt-based review (which runs as a panel
      // discussion of the diff through `runEnsembleRound`, with no
      // native review invocation). Pre-AT5 there was no signal that
      // these two paths produced different behavior — users
      // assumed Ensemble `/review` had the same correctness
      // guarantees as Codex's solo native review and were surprised
      // when the panel's output differed.
      if (isCurrentEnsembleChat) {
        setRawLogs((prev) => [
          ...prev,
          {
            type: 'info',
            content:
              'Ensemble /review: runs as a panel discussion of the diff (prompt-only). ' +
              'Native Codex review only fires in solo Codex chats with a linked thread.'
          }
        ])
      }

      // 1.0.4-AT5 — `codexNativeReview` only fires for solo Codex
      // chats. In Ensemble the dispatch goes through
      // `runEnsembleRound` (see `executeRun`'s chatKind branch),
      // which ignores this flag — every participant gets the same
      // diff as a prompt and reviews it in their role. The flag
      // is kept on the request so the downstream
      // `formatReviewRequestPrompt` / activity-categorization paths
      // can still tag the run as a "review" intent.
      const reviewRequest: QueuedRunRequest = {
        provider: currentProvider,
        prompt: buildReviewCurrentDiffPrompt(diffObj),
        displayPrompt: '/review current diff',
        selectedModelType,
        customModel,
        approvalMode: 'plan',
        workflowMode: 'normal',
        sessionTrust,
        imageAttachments: [],
        effectiveWorkspacePath: currentComposerWorktreeSelection?.effectiveWorkspacePath,
        codexNativeReview:
          currentProvider === 'codex' &&
          !isCurrentEnsembleChat &&
          Boolean(currentChat?.linkedProviderSessionId),
        workspaceRecord: currentChatWorkspace || currentWorkspace || undefined,
        chatRecord: currentChat
      }

      if (
        shouldQueueRunBeforeDispatch({
          chatKind: reviewRequest.chatRecord?.chatKind,
          busy: isChatBusy(reviewRequest.chatRecord?.appChatId)
        })
      ) {
        queueRunRequest(
          reviewRequest,
          `Diff review is waiting for this chat's active ${getProviderLabel(reviewRequest.provider)} task to exit.`
        )
        setDiffRefreshStatus('Diff review queued.')
        return
      }

      void executeRun(reviewRequest)
    } catch (error) {
      setDiffRefreshStatus('Diff review failed to prepare.')
      setRawLogs((prev) => [
        ...prev,
        { type: 'info', content: `Failed to prepare diff review: ${redactLog(String(error))}` }
      ])
    } finally {
      setIsPreparingDiffReview(false)
    }
  }

  const appendBusyRunToExecutionStack = (
    request: QueuedRunRequest,
    specialOverride: boolean
  ): boolean => {
    const targetChat = request.chatRecord || currentChat
    const targetChatId = targetChat?.appChatId
    const targetWorkspace = getWorkspaceForChat(targetChat)
    const busy = isChatBusy(targetChatId)
    if (
      !shouldAppendBusySendToExecutionStack({
        busy,
        hasWorkspace: Boolean(targetWorkspace?.id),
        isTopLevel: Boolean(targetChat && isTopLevelWorkspaceChat(targetChat)),
        isPopout: isChatPopoutWindow,
        isGlobal: Boolean(targetChat && isGlobalChat(targetChat)),
        chatKind: targetChat?.chatKind,
        existingPrompt: Boolean(request.existingPrompt),
        scheduled: Boolean(request.scheduledRunAt || request.scheduledTaskId),
        directedParticipant: Boolean(request.dmTargetParticipantId),
        specialOverride:
          specialOverride ||
          Boolean(
            request.verbatimPrompt ||
            request.codexNativeReview ||
            request.handoffSourceRunId ||
            request.preserveComposer ||
            request.discordContextSelection ||
            request.geminiWorktree?.enabled ||
            request.effectiveWorkspacePath ||
            request.externalPathGrants?.some((grant) => grant.duration === 'thisRun')
          )
      }) ||
      !targetChatId ||
      !targetWorkspace ||
      typeof window.api.appendExecutionStackStep !== 'function'
    ) {
      return false
    }

    const requestSnapshot = createRunQueueRequestSnapshot(request)
    const preferredExecutionId = preferredExecutionByChatIdRef.current[targetChatId]
    const targetExecutionRuns = (executionRunIdsByChatId[targetChatId] || [])
      .map((executionId) => executionRunsById[executionId])
      .filter((run): run is ExecutionRunProjection => Boolean(run))
      .sort((left, right) => executionRunTimestamp(right) - executionRunTimestamp(left))
    const targetExecution =
      targetExecutionRuns.find(
        (run) => run.executionId === preferredExecutionId && !isTerminalExecutionRun(run)
      ) || targetExecutionRuns.find((run) => !isTerminalExecutionRun(run))
    const appendFingerprint = JSON.stringify({
      executionId: targetExecution?.executionId,
      provider: request.provider,
      request: requestSnapshot
    })
    const inFlightFingerprint = executionAppendInFlightRef.current.get(targetChatId)
    if (inFlightFingerprint) {
      if (inFlightFingerprint === appendFingerprint) {
        appendThreadRawLog(targetChatId, {
          type: 'info',
          content: 'This message is already being added to the Stack.'
        })
        return true
      }
      appendThreadRawLog(targetChatId, {
        type: 'info',
        content: 'Another Stack update is still committing; this message was queued safely.'
      })
      return false
    }

    const durableAppendKey = executionAppendSubmissionKey(
      JSON.stringify({
        workspaceId: targetWorkspace.id,
        rootChatId: targetChatId,
        provider: request.provider,
        request: requestSnapshot
      })
    )
    const pendingStorageKey = `taskwraith.execution-stack-pending.v1.${targetChatId}`
    let recoveredClientRequestId: string | undefined
    try {
      const persisted = JSON.parse(window.localStorage.getItem(pendingStorageKey) || 'null') as {
        key?: unknown
        clientRequestId?: unknown
      } | null
      if (
        persisted?.key === durableAppendKey &&
        typeof persisted.clientRequestId === 'string' &&
        /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(persisted.clientRequestId)
      ) {
        recoveredClientRequestId = persisted.clientRequestId
      }
    } catch {
      // A malformed best-effort receipt cannot authorize anything in main.
    }
    const graphRequest = {
      ...request,
      appRunId: recoveredClientRequestId || request.appRunId || createAppRunId()
    }
    try {
      window.localStorage.setItem(
        pendingStorageKey,
        JSON.stringify({ key: durableAppendKey, clientRequestId: graphRequest.appRunId })
      )
    } catch {
      // Main still provides durable idempotency within this live renderer.
    }

    const liveAnchorRunRef =
      resolveActiveRunContextForChat(targetChatId)?.runId ||
      (activeRunChatIdRef.current === targetChatId
        ? activeRunIdRef.current || undefined
        : undefined)
    executionAppendInFlightRef.current.set(targetChatId, appendFingerprint)

    void window.api
      .appendExecutionStackStep({
        clientRequestId: graphRequest.appRunId!,
        ...(targetExecution ? { executionId: targetExecution.executionId } : {}),
        workspaceId: targetWorkspace.id,
        rootChatId: targetChatId,
        ...(!targetExecution && liveAnchorRunRef ? { anchorRunRef: liveAnchorRunRef } : {}),
        // Stack titles share THREAD_TITLE_MAX_CHARS (160). Appending " Stack" to a
        // full-length chat title used to exceed optionalString(…, 160) and fail with
        // "Optional execution value is too long.", blocking busy-queue appends.
        title: normalizeThreadTitle(`${targetChat.title || 'Task'} Stack`, 'Task Stack'),
        stepTitle: executionStackStepTitle(graphRequest.displayPrompt || graphRequest.prompt),
        objective: graphRequest.prompt,
        provider: graphRequest.provider,
        request: requestSnapshot
      })
      .then((run) => {
        try {
          const persisted = JSON.parse(
            window.localStorage.getItem(pendingStorageKey) || 'null'
          ) as {
            key?: unknown
            clientRequestId?: unknown
          } | null
          if (
            persisted?.key === durableAppendKey &&
            persisted.clientRequestId === graphRequest.appRunId
          ) {
            window.localStorage.removeItem(pendingStorageKey)
          }
        } catch {
          // Best-effort cleanup only; a retained receipt remains payload-bound in main.
        }
        preferredExecutionByChatIdRef.current[targetChatId] = run.executionId
        rememberExecutionRun(run)
        settleProjectReferenceContextForRequest(graphRequest, 'accepted')
        clearSubmittedExecutionStackContext(graphRequest, targetChatId)
        const submittedDraft = graphRequest.displayPrompt || graphRequest.prompt
        if (composerDraftsByChatIdRef.current[targetChatId] === submittedDraft) {
          setChatPromptDraft(targetChatId, '')
        }
      })
      .catch((error) => {
        settleProjectReferenceContextForRequest(graphRequest, 'rejected')
        const message = `Could not add this message to the Stack: ${redactLog(
          stripElectronInvokeErrorFraming(error)
        )}`
        appendThreadRawLog(targetChatId, {
          type: 'stderr',
          content: message
        })
        updateChatById(targetChatId, (source) => ({
          ...source,
          messages: [
            ...source.messages,
            {
              id: createMessageId(),
              role: 'error',
              content: message,
              timestamp: new Date().toISOString()
            }
          ]
        }))
      })
      .finally(() => {
        if (executionAppendInFlightRef.current.get(targetChatId) === appendFingerprint) {
          executionAppendInFlightRef.current.delete(targetChatId)
        }
      })
    return true
  }
  const appendBusyRunToExecutionStackRef = useRef(appendBusyRunToExecutionStack)
  appendBusyRunToExecutionStackRef.current = appendBusyRunToExecutionStack

  const welcomeBackgroundSubmitInFlightRef = useRef<Set<string>>(new Set())
  const dispatchWelcomeBackgroundRequest = async (
    request: QueuedRunRequest,
    target: WelcomeBackgroundThreadTarget,
    requestedSchedule: string,
    scheduledRunAt?: string
  ): Promise<void> => {
    const sourceChatId = target.chat.appChatId
    if (welcomeBackgroundSubmitInFlightRef.current.has(sourceChatId)) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      return
    }
    welcomeBackgroundSubmitInFlightRef.current.add(sourceChatId)
    try {
      await launchWelcomeBackgroundThread(
        { target, request, scheduledRunAt },
        {
          createWorkspaceChat: (workspaceId, workspacePath) =>
            window.api.createChat(workspaceId, workspacePath),
          createGlobalChat: () => window.api.createGlobalChat(),
          createEnsembleChat: (args) => window.api.createEnsembleChat(args),
          saveChat: (chat) => window.api.saveChat(chat),
          recordChat: (chat) => {
            chatByIdRef.current.set(chat.appChatId, chat)
            setChats((current) => mergeChatRecord(current, chat))
          },
          projectIdsForChat: (chatId) =>
            listProjects()
              .filter((project) => !project.archived && project.memberChatIds.includes(chatId))
              .map((project) => project.id),
          addChatToProject: (projectId, chatId) => {
            addChatToProject(projectId, chatId)
          },
          createRunId: createAppRunId,
          queueRun: (queued, reason) => {
            void queueRunRequest(queued, reason)
          },
          executeRun: (queued) => {
            void executeRun(queued)
          },
          currentDraft: (chatId) => composerDraftsByChatIdRef.current[chatId] || '',
          clearDraft: (chatId) => setChatPromptDraft(chatId, ''),
          clearSubmittedContext: clearSubmittedExecutionStackContext,
          reapAbandonedChats: reapAbandonedChatsAfterCreate,
          formatScheduledRunTime
        }
      )
      if (
        scheduledRunAt &&
        requestedSchedule &&
        scheduleRunAtByChatId[sourceChatId] === requestedSchedule
      ) {
        setScheduleRunAtForChat(sourceChatId, '')
      }
    } catch (error) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      const message = `Could not start a background thread: ${redactLog(String(error))}`
      appendThreadRawLog(sourceChatId, { type: 'stderr', content: message })
      window.alert(message)
    } finally {
      welcomeBackgroundSubmitInFlightRef.current.delete(sourceChatId)
    }
  }

  const handleRun = (
    overrideModel?: string,
    existingPrompt?: string,
    /**
     * A2 (1.0.3) — DM routing. When set, the resulting dispatch
     * scopes the ensemble round to just this participant via the
     * orchestrator's `dmTargetParticipantId`. Ignored on solo chats.
     * Plumbed onto the request envelope (not chat-level state)
     * because each dispatch is an independent decision.
     */
    dmTargetParticipantId?: string,
    /**
     * Plan-mode approval elevates the run off read-only: Approve re-dispatches
     * with `approvalMode: 'default'` so ComposerService re-derives write
     * permissions (the HMAC posture clamp re-signs). Undefined inherits the
     * chat's composer selection.
     */
    approvalModeOverride?: string,
    workflowModeOverride?: ChatWorkflowMode,
    /**
     * Exact identity selected by the composer @ picker. Unlike the regular
     * explicit id above, this is only allowed to disambiguate one matching
     * plain mention when MAIN resolves the current roster.
     */
    exactPickerParticipantId?: string,
    backgroundTarget?: WelcomeBackgroundThreadTarget
  ) => {
    if (
      backgroundTarget &&
      (!isReusableWelcomeChat(backgroundTarget.chat) ||
        workflowDraft?.chatId === backgroundTarget.chat.appChatId ||
        welcomeBackgroundSubmitInFlightRef.current.has(backgroundTarget.chat.appChatId))
    ) {
      return
    }
    const requestTarget = backgroundTarget
      ? {
          chat: backgroundTarget.chat,
          prompt: backgroundTarget.prompt,
          sessionTrust: backgroundTarget.sessionTrust,
          imageAttachments: backgroundTarget.imageAttachments,
          discordContextSelection: backgroundTarget.discordContextSelection,
          ...(approvalModeOverride ? { approvalMode: approvalModeOverride } : {}),
          ...(workflowModeOverride ? { workflowMode: workflowModeOverride } : {}),
          claimProjectReferenceContext: true
        }
      : approvalModeOverride || workflowModeOverride
        ? {
            ...(approvalModeOverride ? { approvalMode: approvalModeOverride } : {}),
            ...(workflowModeOverride ? { workflowMode: workflowModeOverride } : {}),
            claimProjectReferenceContext: true
          }
        : undefined
    const baseRequest = buildRunRequest(overrideModel, existingPrompt, requestTarget)
    // One consent notice per WORKSPACE (owner directive 2026-08-05): the
    // first prompt sent into a never-consented workspace at an edit-capable
    // mode raises the generic Tier-1 sheet; Continue records the workspace
    // ack (covering every agent/provider/participant, like the 'agents'-wide
    // grants) and resumes this exact send. Read-only sends stay silent and
    // auto_edit keeps its own always-on Tier-2 raise flow.
    if (firstSendConsentGrantedRef.current) {
      firstSendConsentGrantedRef.current = false
    } else if (baseRequest.scope !== 'global') {
      const consentModes =
        baseRequest.chatRecord?.chatKind === 'ensemble'
          ? (baseRequest.chatRecord.ensemble?.participants ?? [])
              .filter((participant) => participant.enabled)
              .map((participant) => permissionPresetToApprovalMode(participant.permissionPresetId))
          : [baseRequest.approvalMode]
      const consentWorkspace = baseRequest.chatRecord
        ? getWorkspaceForChat(baseRequest.chatRecord)
        : currentWorkspace
      const firstSendConsent = decideFirstSendWorkspaceConsent({
        approvalModes: consentModes,
        workspacePath: baseRequest.chatRecord?.workspacePath ?? currentWorkspacePath,
        acknowledgedDefault: acknowledgedElevationDefaults
      })
      if (firstSendConsent) {
        if (backgroundTarget) {
          settleProjectReferenceContextForRequest(baseRequest, 'rejected')
        }
        setPendingElevation({
          tier: firstSendConsent.tier,
          provider: baseRequest.provider,
          workspaceLabel: consentWorkspace?.displayName ?? null,
          ackKey: firstSendConsent.ackKey,
          persistAck: firstSendConsent.persistAckOnConfirm,
          toMode: 'default',
          apply: () => {
            firstSendConsentGrantedRef.current = true
            try {
              handleRun(
                overrideModel,
                existingPrompt,
                dmTargetParticipantId,
                approvalModeOverride,
                workflowModeOverride,
                exactPickerParticipantId,
                backgroundTarget
              )
            } finally {
              firstSendConsentGrantedRef.current = false
            }
          }
        })
        return
      }
    }
    if (
      baseRequest.chatRecord?.chatKind !== 'ensemble' &&
      !isRunnableProvider(baseRequest.provider)
    ) {
      settleProjectReferenceContextForRequest(baseRequest, 'rejected')
      appendThreadRawLog(baseRequest.chatRecord?.appChatId || currentChat?.appChatId, {
        type: 'info',
        content: `${getProviderOfferUnavailableReason(baseRequest.provider)} Choose a currently offered provider to continue.`
      })
      return
    }
    // The textarea Enter + send-button handlers resolve @mentions before
    // calling us, but the global Run Prompt shortcut (Cmd/Ctrl+Enter) calls
    // handleRun directly. Resolve once more at this central seam so a queued
    // shortcut submission preserves its directed participant scope through a
    // later natural drain or Steer action.
    const resolvedDmTargetParticipantId = resolveComposerRunDmTarget({
      explicitParticipantId: dmTargetParticipantId,
      prompt: baseRequest.prompt || '',
      participants: baseRequest.chatRecord?.ensemble?.participants,
      inferFromPrompt: !existingPrompt && baseRequest.chatRecord?.chatKind === 'ensemble'
    })
    const request = {
      ...baseRequest,
      ...(resolvedDmTargetParticipantId
        ? { dmTargetParticipantId: resolvedDmTargetParticipantId }
        : {}),
      ...(exactPickerParticipantId && baseRequest.chatRecord?.chatKind === 'ensemble'
        ? { exactPickerParticipantId }
        : {})
    }
    if (!runRequestHasContent(request)) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      return
    }
    // Workflow compose: the first "send" CREATES the workflow (captures the
    // prompt + run settings into a WorkflowDefinition) instead of dispatching a
    // one-off run. The chat becomes the workflow's thread.
    if (workflowDraft && request.chatRecord?.appChatId === workflowDraft.chatId) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      void createWorkflowFromDraft(request)
      clearComposerAttachmentsForSubmittedRequest(request)
      if (!request.existingPrompt) {
        setChatPromptDraft(
          request.chatRecord?.appChatId || currentChatIdRef.current || currentChat?.appChatId,
          ''
        )
      }
      return
    }
    if (
      !existingPrompt &&
      pendingPlanImport &&
      request.chatRecord?.appChatId === currentComposerChatId
    ) {
      setPendingPlanImport(null)
    }

    if (backgroundTarget) {
      const sourceChatId = backgroundTarget.chat.appChatId
      const requestedSchedule = scheduleRunAtByChatId[sourceChatId] || ''
      const backgroundScheduledRunAt = requestedSchedule
        ? normalizeScheduledQueueRunAt(requestedSchedule) || undefined
        : undefined
      if (requestedSchedule && !backgroundScheduledRunAt) {
        settleProjectReferenceContextForRequest(request, 'rejected')
        appendThreadRawLog(sourceChatId, {
          type: 'info',
          content: 'Choose a future time for scheduled runs.'
        })
        return
      }
      void dispatchWelcomeBackgroundRequest(
        request,
        backgroundTarget,
        requestedSchedule,
        backgroundScheduledRunAt
      )
      return
    }

    if (!existingPrompt && scheduleRunAt) {
      const scheduledRunAt = normalizeScheduledQueueRunAt(scheduleRunAt)
      if (!scheduledRunAt) {
        settleProjectReferenceContextForRequest(request, 'rejected')
        appendThreadRawLog(request.chatRecord?.appChatId || currentChat?.appChatId, {
          type: 'info',
          content: 'Choose a future time for scheduled runs.'
        })
        return
      }
      const scheduledRequest: QueuedRunRequest = {
        ...request,
        scheduledRunAt
      }
      queueRunRequest(scheduledRequest, `Scheduled for ${formatScheduledRunTime(scheduledRunAt)}.`)
      setScheduleRunAt('')
      clearComposerAttachmentsForSubmittedRequest(request)
      setChatPromptDraft(
        request.chatRecord?.appChatId || currentChatIdRef.current || currentChat?.appChatId,
        ''
      )
      return
    }

    // Gesture-time re-lock (Claude/Codex parity): the composer submit is the
    // user's action, so the visible transcript returns to the live edge NOW —
    // for the queued branch too (the send is the gesture; the drain minutes
    // later is not). Scheduled tasks and queue drains re-enter via executeRun
    // directly and must never relock a reading user.
    if (
      !request.existingPrompt &&
      (request.chatRecord?.appChatId || currentChat?.appChatId) ===
        (currentChatIdRef.current || currentChat?.appChatId)
    ) {
      relockMainTranscriptToLatest()
    }
    const targetChat = request.chatRecord || currentChat
    const targetChatId = targetChat?.appChatId || currentChat?.appChatId
    if (
      shouldQueueRunBeforeDispatch({
        chatKind: targetChat?.chatKind,
        busy: isChatBusy(targetChatId)
      })
    ) {
      if (
        appendBusyRunToExecutionStack(
          request,
          Boolean(approvalModeOverride || workflowModeOverride)
        )
      ) {
        return
      }
      queueRunRequest(request)
      clearComposerAttachmentsForSubmittedRequest(request)
      if (!request.existingPrompt) {
        setChatPromptDraft(targetChatId || currentChatIdRef.current || currentChat?.appChatId, '')
      }
      return
    }

    void executeRun(request)
  }
  const handleRunRef = useRef(handleRun)
  handleRunRef.current = handleRun
  const runWelcomeBackgroundTarget = useCallback(
    (
      target: WelcomeBackgroundThreadTarget,
      dmTargetParticipantId?: string,
      exactPickerParticipantId?: string
    ): void => {
      handleRunRef.current(
        undefined,
        undefined,
        dmTargetParticipantId,
        undefined,
        undefined,
        exactPickerParticipantId,
        target
      )
    },
    []
  )
  const handleRunInBackground = useCallback(
    (dmTargetParticipantId?: string, exactPickerParticipantId?: string): void => {
      const sourceChatId = currentChatIdRef.current
      if (!sourceChatId) return
      const sourceChat = chatByIdRef.current.get(sourceChatId)
      if (!sourceChat) return
      runWelcomeBackgroundTarget(
        {
          chat: sourceChat,
          prompt: composerDraftsByChatIdRef.current[sourceChatId] || '',
          sessionTrust,
          imageAttachments:
            imageAttachmentsByChatIdRef.current[sourceChatId] || EMPTY_IMAGE_ATTACHMENTS,
          discordContextSelection: discordContextSelectionByChatIdRef.current[sourceChatId] || null
        },
        dmTargetParticipantId,
        exactPickerParticipantId
      )
    },
    [runWelcomeBackgroundTarget, sessionTrust]
  )

  const createSideChatFromCurrentChat = async (
    seedPrompt = '',
    clearParentDraft = false,
    presentation: SidePanelPresentation = 'split',
    seedContext: SideChatSeedContext = {},
    mode?: SideChatCreateMode,
    presentInline = true,
    participantOverride?: EnsembleParticipant | null
  ): Promise<ChatRecord | null> => {
    const parentChat = currentChat
    if (!parentChat) return null
    try {
      const parentProvider = getChatProvider(parentChat)
      const sideChatMode: SideChatCreateMode =
        mode || (parentChat.chatKind === 'ensemble' ? 'ensembleClone' : 'singleProvider')
      const selectedSideParticipant =
        sideChatMode === 'singleProvider' && parentChat.chatKind === 'ensemble'
          ? participantOverride ||
            selectedParticipant ||
            parentChat.ensemble?.participants.find((participant) => participant.enabled) ||
            parentChat.ensemble?.participants[0] ||
            null
          : null
      const sideProvider = selectedSideParticipant?.provider || parentProvider
      if (!isRunnableProvider(sideProvider)) {
        const message = `${getProviderOfferUnavailableReason(sideProvider)} A new side chat cannot use this provider; choose a currently offered provider first.`
        appendThreadRawLog(parentChat.appChatId, { type: 'info', content: message })
        window.alert(message)
        return null
      }
      const sideParticipantLabel = selectedSideParticipant
        ? selectedSideParticipant.role || getProviderLabel(selectedSideParticipant.provider)
        : getProviderLabel(sideProvider)
      const shouldSeedIsolatedContextSnapshot = shouldSeedIsolatedSideChatContext(
        seedPrompt,
        sideChatMode
      )
      const effectiveSeedPrompt = shouldSeedIsolatedContextSnapshot
        ? buildIsolatedSideChatContextSeed(parentChat, {
            participantLabel: selectedSideParticipant
              ? `${getProviderLabel(selectedSideParticipant.provider)} / ${sideParticipantLabel}`
              : undefined
          })
        : seedPrompt
      const hiddenInitialContextPrompt =
        shouldSeedIsolatedContextSnapshot && effectiveSeedPrompt.trim()
          ? effectiveSeedPrompt.trim()
          : ''
      const persistedSideChatMode =
        sideChatMode === 'guestParticipant' ? 'singleProvider' : sideChatMode
      const createdSideChat = await window.api.createSideChat({
        parentChatId: parentChat.appChatId,
        chatKind:
          sideChatMode === 'singleProvider' || sideChatMode === 'guestParticipant'
            ? 'single'
            : 'ensemble',
        provider: sideProvider,
        sideChatMode: persistedSideChatMode,
        originMessageId: seedContext.originMessageId,
        originRunId: seedContext.originRunId,
        title:
          sideChatMode === 'fanOut'
            ? `Fan-out side chat from ${parentChat.title || 'ensemble chat'}`
            : sideChatMode === 'ensembleClone'
              ? `Side ensemble from ${parentChat.title || 'ensemble chat'}`
              : `Isolated ${sideParticipantLabel} side chat from ${
                  parentChat.title || getProviderLabel(parentProvider)
                }`
      })
      let nextSideChat = createdSideChat
      const seedTranscriptVisibility =
        seedContext.transcriptVisibility ||
        (seedContext.originMessageId
          ? 'selected'
          : seedContext.originRunId
            ? 'snapshot'
            : shouldSeedIsolatedContextSnapshot && effectiveSeedPrompt
              ? 'snapshot'
              : undefined)
      if (selectedSideParticipant) {
        const participantMetadata: Record<string, unknown> = {
          selectedModelType:
            selectedSideParticipant.model ||
            getDefaultModelForProvider(selectedSideParticipant.provider),
          customModel: '',
          approvalMode: permissionPresetToApprovalMode(selectedSideParticipant.permissionPresetId),
          [SIDE_CHAT_SELECTED_PARTICIPANT_ID_METADATA_KEY]: selectedSideParticipant.id,
          [SIDE_CHAT_SELECTED_PARTICIPANT_ROLE_METADATA_KEY]:
            selectedSideParticipant.role || getProviderLabel(selectedSideParticipant.provider)
        }
        if (selectedSideParticipant.pooledAgentId) {
          participantMetadata.pooledAgentId = selectedSideParticipant.pooledAgentId
        }
        if (selectedSideParticipant.pooledAgentIdentity) {
          participantMetadata.pooledAgentIdentity = selectedSideParticipant.pooledAgentIdentity
        }
        if (selectedSideParticipant.runtimeProfileId) {
          participantMetadata.runtimeProfileId = selectedSideParticipant.runtimeProfileId
        }
        if (
          selectedSideParticipant.provider === 'gemini' &&
          selectedSideParticipant.geminiAuthProfileId
        ) {
          participantMetadata.geminiAuthProfileId = selectedSideParticipant.geminiAuthProfileId
        }
        if (selectedSideParticipant.provider === 'codex') {
          participantMetadata.codexReasoningEffort =
            selectedSideParticipant.reasoningEffort || 'medium'
          participantMetadata.codexServiceTier =
            selectedSideParticipant.serviceTier ||
            (selectedSideParticipant.fastModeEnabled ? 'fast' : '')
        }
        if (selectedSideParticipant.provider === 'claude') {
          const selectedClaudeSettings = resolveEnsembleParticipantSettings(selectedSideParticipant)
          const selectedClaudeModel =
            selectedSideParticipant.model ||
            getDefaultModelForProvider(selectedSideParticipant.provider)
          const selectedClaudeModelOption = (
            agentModelsByProvider.claude || CLAUDE_DEFAULT_MODELS
          ).find((model) => model.id === selectedClaudeModel)
          participantMetadata.claudeReasoningEffort =
            selectedClaudeSettings.reasoningEffort ||
            resolveClaudeDefaultReasoningEffort(selectedClaudeModelOption)
          participantMetadata.claudeFastMode = Boolean(selectedSideParticipant.fastModeEnabled)
        }
        if (selectedSideParticipant.provider === 'kimi') {
          const selectedKimiSettings = resolveEnsembleParticipantSettings(selectedSideParticipant)
          participantMetadata.kimiFastMode = selectedKimiSettings.fastModeEnabled
          participantMetadata.kimiReasoningEffort = selectedKimiSettings.reasoningEffort || 'on'
          participantMetadata.kimiThinkingEnabled = true
        }
        nextSideChat = {
          ...createdSideChat,
          provider: selectedSideParticipant.provider,
          providerMetadata: {
            ...(createdSideChat.providerMetadata || {}),
            ...participantMetadata
          },
          updatedAt: Date.now()
        }
        void window.api.saveChat(nextSideChat).catch(() => {})
      }
      if (seedTranscriptVisibility) {
        nextSideChat = {
          ...nextSideChat,
          sideChatContext: {
            createdAt: nextSideChat.sideChatContext?.createdAt || Date.now(),
            ...(nextSideChat.sideChatContext || {}),
            transcriptVisibility: seedTranscriptVisibility
          },
          updatedAt: Date.now()
        }
        void window.api.saveChat(nextSideChat).catch(() => {})
      }
      if (hiddenInitialContextPrompt) {
        nextSideChat = {
          ...nextSideChat,
          providerMetadata: {
            ...(nextSideChat.providerMetadata || {}),
            [SIDE_CHAT_HIDDEN_CONTEXT_PROMPT_METADATA_KEY]: hiddenInitialContextPrompt
          },
          updatedAt: Date.now()
        }
        void window.api.saveChat(nextSideChat).catch(() => {})
      }
      chatByIdRef.current.set(nextSideChat.appChatId, nextSideChat)
      chatMutations.promoteToFront(nextSideChat)
      if (presentInline && sideChat?.appChatId && sideChat.appChatId !== nextSideChat.appChatId) {
        closeSideChatPresentationRecord(sideChat)
      }
      if (presentInline) {
        setSidePanelPresentation(presentation)
        setSideChatId(nextSideChat.appChatId)
        closeOtherRightDockPanels('chat')
        setIsSideChatDockPanelOpen(true)
        setRightDockTab('chat')
      }
      setChatPromptDraft(
        nextSideChat.appChatId,
        hiddenInitialContextPrompt ? '' : effectiveSeedPrompt
      )
      if (clearParentDraft) {
        setChatPromptDraft(parentChat.appChatId, '')
      }
      if (presentInline) {
        requestAnimationFrame(() => {
          sideComposerTextareaRef.current?.focus()
        })
      }
      return nextSideChat
    } catch (error) {
      appendThreadRawLog(parentChat.appChatId, {
        type: 'stderr',
        content: `Failed to create side chat: ${redactLog(String(error))}`
      })
      return null
    }
  }

  const openLinkedChatInSidePanel = (
    chat: ChatRecord,
    presentation: SidePanelPresentation = 'split',
    parentOverride?: ChatRecord | null
  ) => {
    const parentChat = parentOverride || currentChat
    if (!parentChat?.appChatId || chat.parentChatId !== parentChat.appChatId) return
    // A list row is a summary projection. Present it immediately, but let the
    // side-surface residency coordinator hydrate before mutating/persisting its
    // lifecycle; saveChat correctly refuses summary-only records.
    const nextChat =
      chat.parentChatRelation === 'sideChat' && !isChatSummaryRecord(chat)
        ? applySideChatLifecycle(chat, 'active')
        : chat
    chatByIdRef.current.set(nextChat.appChatId, nextChat)
    if (nextChat !== chat) {
      setChats((prev) => {
        const index = prev.findIndex((item) => item.appChatId === nextChat.appChatId)
        if (index < 0) return [nextChat, ...prev]
        return prev.map((item) => (item.appChatId === nextChat.appChatId ? nextChat : item))
      })
      void window.api.saveChat(nextChat).catch(() => {})
    }
    if (sideChat?.appChatId && sideChat.appChatId !== nextChat.appChatId) {
      closeSideChatPresentationRecord(sideChat)
    }
    setSidePanelPresentation(presentation)
    setSideChatId(nextChat.appChatId)
    closeOtherRightDockPanels('chat')
    setIsSideChatDockPanelOpen(true)
    setRightDockTab('chat')
    setSideChatMenuOpen(false)
    requestAnimationFrame(() => {
      sideComposerTextareaRef.current?.focus()
    })
  }

  const openLinkedChatAsMain = async (chat: ChatRecord) => {
    const inlineScrollState =
      sideChatId === chat.appChatId
        ? captureChatScrollState(sideTranscriptScrollRef.current)
        : undefined
    if (sideChatId) {
      if (sideChat?.appChatId && sideChat.appChatId !== chat.appChatId) {
        closeSideChatPresentationRecord(sideChat)
      }
      setSideChatId(null)
      setSideChatMenuOpen(false)
    }
    const cancelInlineRestore = inlineScrollState
      ? restoreMainTranscriptScrollStateWhenReady(inlineScrollState, {
          syncAutoFollow: true,
          targetChatId: chat.appChatId
        })
      : null
    try {
      await handleSelectChat(chat)
    } catch (error) {
      cancelInlineRestore?.()
      throw error
    }
  }
  const openLinkedChatInSidePanelRef = useRef(openLinkedChatInSidePanel)
  useEffect(() => {
    openLinkedChatInSidePanelRef.current = openLinkedChatInSidePanel
  })

  const ensureSideChatForCurrentChat = async (
    seedPrompt = '',
    clearParentDraft = false,
    presentation: SidePanelPresentation = 'split',
    seedContext: SideChatSeedContext = {},
    mode?: SideChatCreateMode,
    presentInline = true,
    participantOverride?: EnsembleParticipant | null
  ): Promise<ChatRecord | null> => {
    const parentChat = currentChat
    if (!parentChat) return null
    const sideChatMode =
      mode || (parentChat.chatKind === 'ensemble' ? 'ensembleClone' : 'singleProvider')
    const selectedSideParticipant =
      sideChatMode === 'singleProvider' && parentChat.chatKind === 'ensemble'
        ? participantOverride ||
          selectedParticipant ||
          parentChat.ensemble?.participants.find((participant) => participant.enabled) ||
          parentChat.ensemble?.participants[0] ||
          null
        : null
    const selectedSideProvider = selectedSideParticipant?.provider
    const selectedSideParticipantId = selectedSideParticipant?.id
    const existing = findReusableSideChat(currentChat.appChatId, chats, {
      mode: sideChatMode,
      provider: selectedSideProvider,
      selectedParticipantId: selectedSideParticipantId
    })
    if (existing) {
      if (presentInline) {
        openLinkedChatInSidePanel(existing, presentation)
      }
      if (
        seedContext.originMessageId ||
        seedContext.originRunId ||
        seedContext.transcriptVisibility
      ) {
        updateChatById(existing.appChatId, (source) => ({
          ...source,
          updatedAt: Date.now(),
          sideChatContext: {
            createdAt: source.sideChatContext?.createdAt || Date.now(),
            ...source.sideChatContext,
            ...(seedContext.originMessageId
              ? { originMessageId: seedContext.originMessageId, originRunId: undefined }
              : {}),
            ...(seedContext.originRunId
              ? { originMessageId: undefined, originRunId: seedContext.originRunId }
              : {}),
            ...(seedContext.transcriptVisibility === 'summary'
              ? { originMessageId: undefined, originRunId: undefined }
              : {}),
            transcriptVisibility: seedContext.originMessageId
              ? 'selected'
              : seedContext.originRunId
                ? 'snapshot'
                : seedContext.transcriptVisibility ||
                  source.sideChatContext?.transcriptVisibility ||
                  'none'
          }
        }))
      }
      if (seedPrompt) {
        setChatPromptDraft(existing.appChatId, seedPrompt)
      }
      if (clearParentDraft) {
        setChatPromptDraft(parentChat.appChatId, '')
      }
      return existing
    }
    return createSideChatFromCurrentChat(
      seedPrompt,
      clearParentDraft,
      presentation,
      seedContext,
      sideChatMode,
      presentInline,
      participantOverride
    )
  }

  const popOutLinkedChat = (
    chat: ChatRecord,
    draftOverride?: string,
    presentation: ChatPopoutPresentation = 'full'
  ) => {
    const targetChat =
      chat.parentChatRelation === 'sideChat' ? applySideChatLifecycle(chat, 'active') : chat
    if (targetChat !== chat) {
      chatByIdRef.current.set(targetChat.appChatId, targetChat)
      setChats((prev) =>
        prev.map((item) => (item.appChatId === targetChat.appChatId ? targetChat : item))
      )
      void window.api.saveChat(targetChat).catch(() => {})
    }
    const wasInlinePresentation =
      sideChatId === targetChat.appChatId || sideChat?.appChatId === targetChat.appChatId
    writeChatPopoutHandoff(targetChat.appChatId, {
      draft:
        typeof draftOverride === 'string'
          ? draftOverride
          : composerDraftsByChatId[targetChat.appChatId] || '',
      scrollState: wasInlinePresentation
        ? captureChatScrollState(sideTranscriptScrollRef.current)
        : currentChat?.appChatId === targetChat.appChatId
          ? captureMainTranscriptScrollState()
          : undefined,
      roundExpansion: captureSessionRoundExpansionForChat(targetChat.appChatId)
    })
    void window.api.openWorkspacePopout({
      kind: 'chat',
      chatId: targetChat.appChatId,
      workspacePath: targetChat.workspacePath,
      presentation
    })
    if (wasInlinePresentation) {
      setSideChatId(null)
      setSideChatMenuOpen(false)
    }
  }

  const resolveCurrentLinkedParentChat = async (): Promise<ChatRecord | null> => {
    if (!currentChatIsLinkedChild || !currentChat?.parentChatId) return null
    const parentChat =
      currentLinkedParentChat || (await window.api.getChat(currentChat.parentChatId)) || null
    if (!parentChat) return null
    chatByIdRef.current.set(parentChat.appChatId, parentChat)
    setChats((prev) => {
      const index = prev.findIndex((chat) => chat.appChatId === parentChat.appChatId)
      if (index < 0) return [parentChat, ...prev]
      return prev.map((chat) => (chat.appChatId === parentChat.appChatId ? parentChat : chat))
    })
    return parentChat
  }

  const openCurrentSideChatPresentation = async (
    presentation: SidePanelPresentation | 'popout' | 'main',
    mode?: SideChatCreateMode,
    participantOverride?: EnsembleParticipant | null,
    draftOverride?: string
  ) => {
    setSideChatMenuOpen(false)
    if (currentChat && currentChatIsLinkedChild) {
      if (typeof draftOverride === 'string') {
        setChatPromptDraft(currentChat.appChatId, draftOverride)
      }
      const linkedMainScrollState =
        presentation === 'split' || presentation === 'drawer'
          ? captureMainTranscriptScrollState()
          : undefined
      const linkedParentChat = await resolveCurrentLinkedParentChat()
      if (!linkedParentChat) return
      if (presentation === 'popout') {
        skipCloseSideChatPresentationIdRef.current = currentChat.appChatId
        popOutLinkedChat(currentChat, draftOverride)
        await handleSelectChat(linkedParentChat)
        return
      }
      if (presentation === 'main') {
        return
      }
      if (currentChatIdRef.current !== linkedParentChat.appChatId) {
        await handleSelectChat(linkedParentChat)
      }
      openLinkedChatInSidePanel(currentChat, presentation, linkedParentChat)
      if (linkedMainScrollState) {
        sideAutoFollowRef.current = linkedMainScrollState.atBottom
        restoreSideTranscriptScrollStateWhenReady(currentChat.appChatId, linkedMainScrollState)
      }
      return
    }
    const activeLinkedChatForParent =
      !mode &&
      currentChat?.appChatId &&
      sideChat?.parentChatId === currentChat.appChatId &&
      (sideChat.parentChatRelation === 'sideChat' || isSubThreadChat(sideChat)) &&
      !sideChat.archived &&
      !isTerminatedSideChat(sideChat)
        ? sideChat
        : null
    if (activeLinkedChatForParent) {
      if (presentation === 'popout') {
        popOutLinkedChat(activeLinkedChatForParent)
        return
      }
      if (presentation === 'main') {
        void openLinkedChatAsMain(activeLinkedChatForParent)
        return
      }
      openLinkedChatInSidePanel(
        activeLinkedChatForParent,
        presentation === 'drawer' ? 'drawer' : 'split'
      )
      return
    }
    const linkedChat = await ensureSideChatForCurrentChat(
      '',
      false,
      presentation === 'drawer' ? 'drawer' : 'split',
      {},
      mode,
      presentation !== 'popout' && presentation !== 'main',
      participantOverride
    )
    if (!linkedChat) return
    if (presentation === 'popout') {
      popOutLinkedChat(linkedChat)
      return
    }
    if (presentation === 'main') {
      void openLinkedChatAsMain(linkedChat)
    }
  }

  const handleOpenLinkedChatInSidePanelById = (
    chatId: string,
    presentation: SidePanelPresentation = 'split'
  ) => {
    const chat = chatByIdRef.current.get(chatId) || chats.find((item) => item.appChatId === chatId)
    if (!chat) return
    openLinkedChatInSidePanel(chat, presentation)
  }

  const handleOpenLinkedChatInSidePanelFromSidebar = async (
    chat: ChatRecord,
    presentation: SidePanelPresentation = 'split'
  ) => {
    const linkedMainScrollState =
      currentChat?.appChatId === chat.appChatId ? captureMainTranscriptScrollState() : undefined
    const parentChat = chat.parentChatId
      ? chatByIdRef.current.get(chat.parentChatId) ||
        chats.find((item) => item.appChatId === chat.parentChatId) ||
        null
      : null
    if (!parentChat) return
    if (currentChat?.appChatId !== parentChat.appChatId) {
      await handleSelectChat(parentChat)
    }
    openLinkedChatInSidePanel(chat, presentation, parentChat)
    if (linkedMainScrollState) {
      sideAutoFollowRef.current = linkedMainScrollState.atBottom
      restoreSideTranscriptScrollStateWhenReady(chat.appChatId, linkedMainScrollState)
    }
  }

  useEffect(() => {
    if (isChatPopoutWindow || typeof window.api.onSideChatDockRequest !== 'function') return
    const unsubscribe = window.api.onSideChatDockRequest((request) => {
      void (async () => {
        const dockScrollState = normalizeChatScrollState(request.scrollState)
        const linkedChat =
          chatByIdRef.current.get(request.chatId) ||
          (await window.api.getChat(request.chatId)) ||
          null
        if (
          !linkedChat ||
          linkedChat.parentChatId !== request.parentChatId ||
          (linkedChat.parentChatRelation !== 'sideChat' &&
            linkedChat.parentChatRelation !== 'subThread')
        ) {
          return
        }
        const parentChat =
          chatByIdRef.current.get(request.parentChatId) ||
          (await window.api.getChat(request.parentChatId)) ||
          null
        if (!parentChat) return

        chatByIdRef.current.set(parentChat.appChatId, parentChat)
        chatByIdRef.current.set(linkedChat.appChatId, linkedChat)
        setChats((prev) => {
          let next = prev
          for (const record of [parentChat, linkedChat]) {
            const idx = next.findIndex((chat) => chat.appChatId === record.appChatId)
            if (idx < 0) {
              next = [record, ...next]
              continue
            }
            if (next === prev) next = prev.slice()
            next[idx] = record
          }
          return next
        })
        if (typeof request.draft === 'string') {
          setChatPromptDraft(linkedChat.appChatId, request.draft)
        }
        if (request.roundExpansion !== undefined) {
          hydrateSessionRoundExpansionForChat(linkedChat.appChatId, request.roundExpansion)
        }
        if (currentChatIdRef.current !== parentChat.appChatId) {
          await handleSelectChatRef.current(parentChat)
        }
        openLinkedChatInSidePanelRef.current(linkedChat, request.presentation, parentChat)
        if (dockScrollState) {
          sideAutoFollowRef.current = dockScrollState.atBottom
          restoreSideTranscriptScrollStateWhenReady(linkedChat.appChatId, dockScrollState)
        }
      })()
    })
    return unsubscribe
  }, [isChatPopoutWindow, setChatPromptDraft])

  const handleSideRun = (
    _overrideModel?: unknown,
    _existingPrompt?: unknown,
    dmTargetParticipantId?: string
  ) => {
    if (!sideChat) return
    if (!isRunnableProvider(sideComposerProvider)) {
      const message = `${getProviderOfferUnavailableReason(sideComposerProvider)} Choose a currently offered provider for this linked chat.`
      appendThreadRawLog(sideChat.appChatId, { type: 'info', content: message })
      window.alert(message)
      return
    }
    const sideRunAttachments =
      imageAttachmentsByChatIdRef.current[sideChat.appChatId] || EMPTY_IMAGE_ATTACHMENTS
    const hiddenContextPrompt = getPendingSideChatHiddenContextPrompt(sideChat)
    const requestPrompt = hiddenContextPrompt
      ? buildHiddenSideChatInitialPrompt(hiddenContextPrompt, sidePrompt)
      : sidePrompt
    const hiddenContextConsumedAt = hiddenContextPrompt ? new Date().toISOString() : ''
    const sideChatForRequest = hiddenContextConsumedAt
      ? {
          ...sideChat,
          providerMetadata: {
            ...(sideChat.providerMetadata || {}),
            [SIDE_CHAT_HIDDEN_CONTEXT_CONSUMED_AT_METADATA_KEY]: hiddenContextConsumedAt
          },
          updatedAt: Date.now()
        }
      : sideChat
    const request = buildRunRequest(undefined, undefined, {
      chat: sideChatForRequest,
      prompt: requestPrompt,
      imageAttachments: sideRunAttachments,
      approvalMode: sideSelectedApprovalMode,
      workflowMode: sideComposerWorkflowMode,
      // Linked-chat trust belongs to the linked composer's explicit permission
      // selection. Never inherit whichever focused main chat happens to have
      // Full Access at dispatch time.
      sessionTrust: sideSelectedPermission === 'full_access',
      claimProjectReferenceContext: true
    })
    if (!runRequestHasContent(request)) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      return
    }
    if (dmTargetParticipantId) request.dmTargetParticipantId = dmTargetParticipantId
    if (hiddenContextPrompt) {
      request.displayPrompt =
        sidePrompt.trim() ||
        attachmentSummary(sideRunAttachments) ||
        (sideRunAttachments.length === 1
          ? 'Attached file'
          : `Attached ${sideRunAttachments.length} files`)
      updateChatById(sideChat.appChatId, (source) => ({
        ...source,
        providerMetadata: {
          ...(source.providerMetadata || {}),
          [SIDE_CHAT_HIDDEN_CONTEXT_CONSUMED_AT_METADATA_KEY]: hiddenContextConsumedAt
        },
        updatedAt: Date.now()
      }))
    }
    if (
      shouldQueueRunBeforeDispatch({
        chatKind: sideChat.chatKind,
        busy: isChatBusy(sideChat.appChatId)
      })
    ) {
      queueRunRequest(request)
      clearComposerAttachmentsForSubmittedRequest(request)
      setChatPromptDraft(sideChat.appChatId, '')
      return
    }
    void executeRun(request)
  }

  const cancelRunningScheduledTaskForChat = async (
    chatId: string,
    reason: string
  ): Promise<boolean> => {
    const task = scheduledTasksRef.current.find(
      (candidate) => candidate.chatId === chatId && candidate.status === 'running'
    )
    if (!task) return false
    const cancelled = await window.api.cancelScheduledTask(task.id, reason)
    return cancelled?.status === 'cancelled'
  }

  const resolveActiveRunContextForChat = (chatId: string): ActiveRunContext | null => {
    for (const ctx of activeRunsRef.current.values()) {
      if (ctx.chatId === chatId) return ctx
    }
    return null
  }

  const finalizeAcceptedRendererRunCancellation = (
    targetChatId: string,
    runId: string,
    activeContext: ActiveRunContext | null
  ): void => {
    const endedAt = new Date().toISOString()
    let cancelledRunStartedAt: string | undefined
    let finalizedChat: ChatRecord | null = null
    updateChatById(targetChatId, (source) => {
      cancelledRunStartedAt = source.runs?.find((run) => run.runId === runId)?.startedAt
      const next = finalizeAcceptedRunCancellationChat(source, runId, endedAt)
      if (next !== source) finalizedChat = next
      return next
    })

    const exactContext = activeContext?.runId === runId ? activeContext : null
    exactContext?.adapter.end()
    if (exactContext) {
      clearActiveRunContext(exactContext)
    } else if (
      !Array.from(activeRunsRef.current.values()).some((run) => run.chatId === targetChatId)
    ) {
      setRunningChatIds((prev) => {
        if (!prev.has(targetChatId)) return prev
        const next = new Set(prev)
        next.delete(targetChatId)
        return next
      })
    }
    if (currentChatIdRef.current === targetChatId) {
      setIsThinking(false)
      setRunCompleteNotice({
        timestamp: endedAt,
        exitCode: 130,
        startedAt: cancelledRunStartedAt
      })
      if (finalizedChat) {
        applyChatComposerSelection(finalizedChat, getChatProvider(finalizedChat))
      }
    }
    syncRunningState()
  }

  const cancelExactSoloChatRun = async (targetChat: ChatRecord): Promise<boolean> => {
    const activeContext = resolveActiveRunContextForChat(targetChat.appChatId)
    const runId = resolveSteerCancelTargetRunId({
      chatId: targetChat.appChatId,
      activeContext,
      activeRunId: activeRunIdRef.current,
      activeRunChatId: activeRunChatIdRef.current,
      runQueueJobs: runQueueJobsRef.current,
      targetChat
    })
    if (!runId) return false

    const queueJob = runQueueJobsRef.current.find((job) => job.runId === runId)
    const persistedRun = targetChat.runs?.find((run) => run.runId === runId)
    const provider =
      activeContext?.provider ||
      queueJob?.provider ||
      persistedRun?.provider ||
      getChatProvider(targetChat)
    intentionalCancelRunIdsRef.current.add(runId)
    try {
      const accepted = await window.api.cancelAgentRun(provider, runId)
      if (!accepted) {
        intentionalCancelRunIdsRef.current.delete(runId)
        syncRunningState()
        return false
      }
      finalizeAcceptedRendererRunCancellation(targetChat.appChatId, runId, activeContext)
      return true
    } catch (error) {
      intentionalCancelRunIdsRef.current.delete(runId)
      throw error
    }
  }

  const cancelLinkedChatRun = async (targetChat: ChatRecord) => {
    if (
      await cancelRunningScheduledTaskForChat(targetChat.appChatId, 'Cancelled from linked chat.')
    ) {
      syncRunningState()
      void refreshSingleChat(targetChat.appChatId)
      return
    }
    if (targetChat.chatKind === 'ensemble') {
      await window.api.cancelEnsembleRound(targetChat.appChatId)
      void refreshSingleChat(targetChat.appChatId)
      return
    }
    await cancelExactSoloChatRun(targetChat)
  }

  const handleSideCancel = async () => {
    if (!sideChat) return
    await cancelLinkedChatRun(sideChat)
  }

  const cancelQueuedSideChatRuns = (chatId: string) => {
    setQueuedRuns((prev) =>
      prev.filter((request) => {
        const requestChatId = request.chatRecord?.appChatId
        if (requestChatId !== chatId) return true
        if (request.appRunId) {
          updateRunQueueJobStatus(
            request.appRunId,
            'cancelled',
            'Linked chat was ended before this queued run started.'
          )
        }
        return false
      })
    )
    for (const job of runQueueJobsRef.current) {
      if (job.chatId !== chatId || isTerminalRunQueueStatus(job.status)) continue
      updateRunQueueJobStatus(
        job.runId || job.id,
        'cancelled',
        'Linked chat was ended before this queued run started.'
      )
    }
  }

  const hideSideChatPane = () => {
    const targetChat = sideChat
    if (targetChat?.parentChatRelation === 'sideChat') {
      updateChatById(targetChat.appChatId, (source) =>
        source.archived || isTerminatedSideChat(source)
          ? source
          : applySideChatLifecycle(source, 'closed')
      )
    }
    setSideChatId(null)
    setIsSideChatDockPanelOpen(false)
    setSideChatMenuOpen(false)
  }

  const handleToggleSideChatAuthorityReturn = async (chatId?: string) => {
    const target = chatId
      ? chatByIdRef.current.get(chatId) || chats.find((chat) => chat.appChatId === chatId)
      : sideChat
    if (!target || target.parentChatRelation !== 'sideChat') return
    const enabled = !sideChatAuthorityReturnEnabled(target)
    const updated = updateChatById(target.appChatId, (source) =>
      setSideChatAuthorityReturn(source, enabled)
    )
    if (!updated) return
    try {
      // Persist immediately so a terminal provider event cannot race the
      // ordinary 200ms renderer save debounce and miss the user's opt-in.
      await window.api.saveChat(updated)
    } catch (error) {
      updateChatById(target.appChatId, (source) =>
        sideChatAuthorityReturnEnabled(source) === enabled
          ? setSideChatAuthorityReturn(source, !enabled)
          : source
      )
      appendThreadRawLog(target.appChatId, {
        type: 'stderr',
        content: `Could not save side-chat return preference: ${redactLog(String(error))}`
      })
    }
  }

  const handleReturnToSideChatParent = () => {
    if (sidePanelParentChat && currentChat?.appChatId !== sidePanelParentChat.appChatId) {
      void handleSelectChat(sidePanelParentChat)
    }
    hideSideChatPane()
  }

  const handleTerminateSideChatRecord = async (targetChat: ChatRecord | null) => {
    if (!targetChat || targetChat.parentChatRelation !== 'sideChat') return
    if (isChatBusy(targetChat.appChatId)) {
      await cancelLinkedChatRun(targetChat)
    }
    cancelQueuedSideChatRuns(targetChat.appChatId)
    updateChatById(targetChat.appChatId, (source) => ({
      ...applySideChatLifecycle(source, 'terminated', 'ended_by_user'),
      archived: true
    }))
    if (sideChatId === targetChat.appChatId) {
      setSideChatId(null)
    }
    setSideChatMenuOpen(false)
    if (currentChat?.appChatId === targetChat.appChatId) {
      const parentChat = targetChat.parentChatId
        ? chatByIdRef.current.get(targetChat.parentChatId) ||
          chats.find((chat) => chat.appChatId === targetChat.parentChatId) ||
          null
        : null
      if (parentChat) {
        await handleSelectChat(parentChat)
      }
    }
  }

  const handleEndSidePanelChat = async () => {
    if (!sideChat) return
    await handleTerminateSideChatRecord(sideChat)
  }

  const handleEndCurrentLinkedMainChat = async () => {
    if (!currentChat || currentChat.parentChatRelation !== 'sideChat') return
    await handleTerminateSideChatRecord(currentChat)
  }

  /**
   * Steer is append-now / deliver-at-boundary. Ensemble text steering is
   * absorbed by main into the live round; solo steering appends the user row
   * immediately and leaves the active provider turn untouched, then the
   * durable queue resumes the same provider session at its natural boundary.
   */
  const handleSteer = async (
    overrideModel?: string,
    existingPrompt?: string,
    // Multiview resting panes steer their OWN chat by passing the pane
    // chat/draft/attachments here (buildRunRequest's target shape). Absent for
    // the focused composer, which steers the visible chat as before.
    target?: Parameters<typeof buildRunRequest>[2]
  ) => {
    const request = buildRunRequest(overrideModel, existingPrompt, target)
    if (!runRequestHasContent(request)) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      return
    }
    if (
      !existingPrompt &&
      pendingPlanImport &&
      request.chatRecord?.appChatId === currentComposerChatId
    ) {
      setPendingPlanImport(null)
    }

    const targetChatId = request.chatRecord?.appChatId || currentChat?.appChatId
    if (!targetChatId) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      return
    }
    // Steering is a composer gesture in the visible chat — same re-lock as a
    // fresh send (gesture-time only; see handleRun).
    if (!existingPrompt && targetChatId === (currentChatIdRef.current || currentChat?.appChatId)) {
      relockMainTranscriptToLatest()
    }

    const targetChat = request.chatRecord || currentChat
    if (targetChat?.chatKind === 'ensemble') {
      // Single-flight: ignore a re-entrant Steer click for this chat while the
      // previous dispatch's IPC round-trip is still in flight (the button is
      // never disabled on the ensemble path, so a fast double-click would
      // otherwise fire two independent steers).
      if (ensembleSteerInFlightChatIdsRef.current.has(targetChatId)) {
        return
      }
      // A direct composer Steer must preserve the same participant hints as a
      // normal send. MAIN resolves those hints against the current roster and
      // clamps fan-out only after it proves the prompt targets one seat.
      const dmTargetParticipantId = resolveComposerRunDmTarget({
        explicitParticipantId: request.dmTargetParticipantId,
        prompt: request.prompt || '',
        participants: targetChat.ensemble?.participants,
        inferFromPrompt: !existingPrompt
      })
      const fanoutPolicy: EnsembleFanoutPolicy = normalizeEnsembleFanoutPolicy(
        targetChat.ensemble?.fanoutPolicy,
        targetChat.ensemble?.concurrentModeEnabled
      )
      ensembleSteerInFlightChatIdsRef.current.add(targetChatId)
      try {
        await window.api.runEnsembleRound({
          chatId: targetChatId,
          prompt: request.prompt,
          // Keep the explicit steer intent on the wire. Main absorbs a plain
          // text interjection into a genuinely-live round without cancellation;
          // shape-changing requests (attachments/directed routing) retain their
          // separate round boundary, and an idle chat starts normally.
          mode: 'steer',
          concurrentMode: ensembleFanoutPolicyEnabled(fanoutPolicy),
          fanoutPolicy,
          ...(dmTargetParticipantId ? { dmTargetParticipantId } : {}),
          ...(request.exactPickerParticipantId
            ? { exactPickerParticipantId: request.exactPickerParticipantId }
            : {}),
          imageAttachments: request.imageAttachments.map((attachment) => ({
            id: attachment.id,
            path: attachment.path,
            name: attachment.name,
            ...attachmentKindMetadata(attachment),
            ...persistedAttachmentMetadata(attachment)
          }))
        })
        clearComposerAttachmentsForSubmittedRequest(request)
        if (!request.existingPrompt) {
          setChatPromptDraft(targetChatId, '')
        }
        // `isThinking` is the visible main transcript's badge; a pane steer of
        // a non-visible chat must not flip it (same gate as the queued steer).
        if (targetChatId === (currentChatIdRef.current || currentChat?.appChatId)) {
          setIsThinking(true)
        }
        void refreshSingleChat(targetChatId)
      } finally {
        ensembleSteerInFlightChatIdsRef.current.delete(targetChatId)
      }
      return
    }

    // Guard: if there's no active run for this chat, just dispatch
    // normally. The Steer button is only visible while `isChatBusy`
    // returns true, but the predicate can flip between render and
    // click (race with `agent-exit`), so handle that gracefully.
    if (!isChatBusy(targetChatId)) {
      void executeRun(request)
      clearComposerAttachmentsForSubmittedRequest(request)
      if (!request.existingPrompt) {
        setChatPromptDraft(targetChatId, '')
      }
      return
    }

    if (soloSteerInFlightChatIdsRef.current.has(targetChatId)) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      return
    }
    soloSteerInFlightChatIdsRef.current.add(targetChatId)
    try {
      const arrivedAtIso = new Date().toISOString()
      const steerRunId = request.appRunId
      if (!steerRunId) {
        settleProjectReferenceContextForRequest(request, 'rejected')
        appendThreadRawLog(targetChatId, {
          type: 'stderr',
          content: `Failed to queue ${getProviderLabel(request.provider)} steer without a durable run id.`
        })
        return
      }
      const steeringMessageId = midRunQueuedMessageId(steerRunId)
      const preparationReason = `Steer is waiting for the active ${getProviderLabel(request.provider)} turn to reach its natural boundary.`
      const prepareJob = buildRunQueueJobInputForRequest(request, 'paused', preparationReason)
      if (!prepareJob) {
        settleProjectReferenceContextForRequest(request, 'rejected')
        appendThreadRawLog(targetChatId, {
          type: 'stderr',
          content: `Failed to prepare ${getProviderLabel(request.provider)} steer queue state.`
        })
        return
      }
      // First-write solo steering barrier: the dedicated promote IPC validates
      // and persists this request already sealed as a main-owned, non-runnable
      // transcript preparation. There is no renderer crash window containing
      // a generic paused row that restart recovery might have to guess about.
      const barrier = await invokePromoteQueuedRunForSteer({
        runId: steerRunId,
        prepareJob,
        provider: request.provider,
        chatId: targetChatId,
        statusReason: 'Preparing the solo steer durable transcript barrier.',
        queueMessageId: steeringMessageId
      })
      const barrierOwnerToken = barrier?.ownerToken
      const barrierPrepared =
        barrier?.ok === true &&
        barrier.jobStatus === 'steer_promoting' &&
        typeof barrierOwnerToken === 'string'
      if (!barrierPrepared) {
        setQueuedRuns((prev) => prev.filter((candidate) => candidate.appRunId !== steerRunId))
        await window.api
          .transitionRunQueueJob(steerRunId, 'failed', {
            statusReason: 'Steering could not reserve its durable transcript barrier.',
            lastError: barrier?.reason || 'The main-owned steer preparation was not minted.'
          })
          .catch(() => null)
        settleProjectReferenceContextForRequest(request, 'rejected')
        appendThreadRawLog(targetChatId, {
          type: 'stderr',
          content: `Failed to prepare ${getProviderLabel(request.provider)} steer before persisting its transcript row.`
        })
        return
      }
      settleProjectReferenceContextForRequest(request, 'accepted')
      const reservedSteerRequest = attachSteerMetadataToRequest(
        request,
        barrier.promotionToken,
        barrierOwnerToken
      )
      setQueuedRuns((prev) =>
        reserveQueuedRunAtFront(prev, reservedSteerRequest, queuedRunFallbackId)
      )
      let steeringMessage: ChatMessage | null = null
      steeringMessage = await appendMidRunQueuedRequestToTranscript(
        request,
        'soloSteer',
        arrivedAtIso,
        { persistImmediately: true }
      )
      const activeRunId =
        resolveActiveRunContextForChat(targetChatId)?.runId ||
        (activeRunChatIdRef.current === targetChatId
          ? activeRunIdRef.current || undefined
          : undefined)
      const liveOutcome =
        steeringMessage && activeRunId
          ? await attemptLiveSteering(window.api, {
              chatId: targetChatId,
              activeRunId,
              queuedRunId: steerRunId,
              ownerToken: barrierOwnerToken!
            })
          : ({ kind: 'unavailable' } as const)
      // Main owns both accepted live attempts and explicit boundary results.
      // Missing/old preload or IPC failure is the only case where renderer
      // must release the exact barrier itself.
      const released =
        liveOutcome.kind === 'unavailable' && steeringMessage
          ? await invokeFallbackPromotedSteerJob({
              runId: steerRunId,
              ownerToken: barrierOwnerToken!,
              reason: preparationReason,
              fallbackStatus: 'queued'
            })
          : liveOutcome.kind === 'boundary'
            ? { ok: true, jobStatus: 'queued' as const }
            : liveOutcome.kind === 'accepted'
              ? { ok: true, jobStatus: 'steer_promoting' as const }
              : null
      const deliveryOwned =
        released?.ok === true &&
        (released.jobStatus === 'queued' || released.jobStatus === 'steer_promoting')
      if (!deliveryOwned) {
        let durableLookupCompleted = false
        let durableHandoff: RunQueueJob | null = null
        if (typeof window.api.getRunQueueJobs === 'function') {
          try {
            const latestJobs = await window.api.getRunQueueJobs({
              chatId: targetChatId,
              includeTerminal: true
            })
            durableLookupCompleted = true
            durableHandoff = latestJobs.find((candidate) => candidate.runId === steerRunId) || null
          } catch {
            // Lost IPC response is not proof that MAIN failed to admit the
            // steer. Preserve its transcript and exact local reservation.
          }
        }
        if (durableHandoff || !durableLookupCompleted) {
          appendThreadRawLog(targetChatId, {
            type: durableHandoff?.status === 'failed' ? 'stderr' : 'info',
            content: durableHandoff
              ? `Steer handoff reply was unavailable; MAIN retained ${durableHandoff.status} state for the exact request, so no duplicate draft was created.`
              : 'Steer handoff state is unknown; the exact transcript row remains reserved and no duplicate draft was created.'
          })
          clearComposerAttachmentsForSubmittedRequest(request)
          if (!request.existingPrompt) setChatPromptDraft(targetChatId, '')
          return
        }
        setQueuedRuns((prev) => prev.filter((candidate) => candidate.appRunId !== steerRunId))
        const reverted = updateChatById(targetChatId, (chat) => ({
          ...chat,
          messages: chat.messages.filter((message) => message.id !== steeringMessageId),
          updatedAt: Date.now()
        }))
        if (reverted) await window.api.saveChat(reverted).catch(() => {})
        await window.api
          .transitionRunQueueJob(steerRunId, 'failed', {
            statusReason: 'Steering could not cross the durable transcript barrier.',
            lastError: 'The queued steer was not made runnable.'
          })
          .catch(() => null)
        settleProjectReferenceContextForRequest(request, 'rejected')
        appendThreadRawLog(targetChatId, {
          type: 'stderr',
          content: `Failed to queue ${getProviderLabel(request.provider)} steer after persisting its transcript row.`
        })
        return
      }
      appendThreadRawLog(targetChatId, {
        type: 'info',
        content:
          liveOutcome.kind === 'accepted'
            ? `Steer accepted for live ${liveOutcome.result.strategy} delivery; its durable boundary fallback remains reserved until delivery is confirmed.`
            : `Steer appended to the transcript; the active ${getProviderLabel(
                request.provider
              )} turn continues and the message is queued for its natural boundary.`
      })
      clearComposerAttachmentsForSubmittedRequest(request)
      if (!request.existingPrompt) {
        setChatPromptDraft(targetChatId, '')
      }
    } finally {
      soloSteerInFlightChatIdsRef.current.delete(targetChatId)
    }
  }
  // Latest-impl ref (buildRunRequestRef pattern): handleSteer is a fresh
  // closure every render, so memoized pane callbacks dispatch through this to
  // stay identity-stable without stale captures.
  const handleSteerRef = useRef(handleSteer)
  handleSteerRef.current = handleSteer

  const handleSideSteer = (): void => {
    if (!sideChat) return
    void handleSteerRef.current(undefined, undefined, {
      chat: sideChat,
      prompt: sidePrompt,
      imageAttachments:
        imageAttachmentsByChatIdRef.current[sideChat.appChatId] || EMPTY_IMAGE_ATTACHMENTS,
      approvalMode: sideSelectedApprovalMode,
      workflowMode: sideComposerWorkflowMode,
      sessionTrust: sideSelectedPermission === 'full_access',
      claimProjectReferenceContext: true
    })
  }

  const handleScheduleRun = async () => {
    if (!currentWorkspace || !currentChat || !scheduleRunAt) return
    const runAtDate = new Date(scheduleRunAt)
    if (Number.isNaN(runAtDate.getTime())) {
      setRawLogs((prev) => [...prev, { type: 'info', content: 'Scheduled run time is invalid.' }])
      return
    }
    if (runAtDate.getTime() <= Date.now()) {
      setRawLogs((prev) => [
        ...prev,
        { type: 'info', content: 'Choose a future time for scheduled runs.' }
      ])
      return
    }
    setRawLogs((prev) => [
      ...prev,
      {
        type: 'info',
        content: `Schedule enabled for ${formatScheduledRunTime(runAtDate.toISOString())}. Press Run to queue this message.`
      }
    ])
  }

  const refreshWorkflowState = async (workspaceId = currentWorkspace?.id) => {
    setScheduledTasks(await window.api.getScheduledTasks(workspaceId))
    setWorkflowDefinitions(await window.api.getWorkflowDefinitions(workspaceId))
  }

  const buildWorkflowTemplateFromRequest = (
    request: ReturnType<typeof buildRunRequest>,
    chat: ChatRecord,
    workspace: WorkspaceRecord
  ): WorkflowDefinition['template'] => {
    const ensembleSnapshot =
      chat.chatKind === 'ensemble'
        ? buildScheduledEnsembleSnapshot(chat, {
            dmTargetParticipantId: request.dmTargetParticipantId,
            exactPickerParticipantId: request.exactPickerParticipantId
          })
        : null
    return {
      workspaceId: workspace.id,
      workspacePath: workspace.path,
      chatId: chat.appChatId,
      provider: request.provider,
      prompt: request.prompt,
      displayPrompt: request.displayPrompt,
      selectedModelType: request.selectedModelType,
      customModel: request.customModel,
      approvalMode: request.approvalMode,
      workflowMode: request.workflowMode || 'normal',
      sessionTrust: request.sessionTrust,
      imageAttachments: request.imageAttachments,
      externalPathGrants: request.externalPathGrants?.filter(
        (grant) => grant.duration === 'workspace'
      ),
      geminiWorktree: request.geminiWorktree,
      codexReasoningEffort: request.codexReasoningEffort,
      codexServiceTier: request.codexServiceTier,
      claudeReasoningEffort: request.claudeReasoningEffort,
      claudeFastMode: request.claudeFastMode,
      kimiFastMode: request.kimiFastMode,
      kimiReasoningEffort: request.kimiReasoningEffort,
      kimiThinkingEnabled: request.kimiThinkingEnabled,
      grokReasoningEffort: request.grokReasoningEffort,
      museReasoningEffort: request.museReasoningEffort,
      mistralReasoningEffort: request.mistralReasoningEffort,
      piReasoningEffort: request.piReasoningEffort,
      antigravityReasoningEffort: request.antigravityReasoningEffort,
      ollamaReasoningEffort: request.ollamaReasoningEffort,
      cursorReasoningEffort: request.cursorReasoningEffort,
      cursorFastMode: request.cursorFastMode,
      runtimeProfileId: request.runtimeProfileId,
      geminiAuthProfileId: request.geminiAuthProfileId,
      handoffSourceRunId: request.handoffSourceRunId,
      ...(ensembleSnapshot
        ? { kind: 'ensemble' as const, ensembleSnapshot }
        : { kind: 'single' as const })
    }
  }

  // First-class workflow compose: the Workflows "+" opens a fresh chat in
  // workflow-compose mode (welcome screen with the workflow controls) instead of
  // the old modal. The WorkflowDefinition is saved on first send.
  const handleOpenWorkflowCompose = async (
    workspaceOverride?: WorkspaceRecord,
    seed?: { prompt?: string; provider?: ProviderId }
  ) => {
    const workflowWorkspace =
      workspaceOverride ||
      currentWorkspace ||
      (currentChat?.scope === 'workspace' ? getWorkspaceForChat(currentChat) : null) ||
      [...workspaces].sort((a, b) => (b.lastOpenedAt || 0) - (a.lastOpenedAt || 0))[0] ||
      null
    if (!workflowWorkspace) return // workflows are workspace-scoped
    const chat = await handleNewDefaultWorkspaceChat(workflowWorkspace.id, workflowWorkspace.path)
    const chatId = chat?.appChatId || currentChatIdRef.current
    if (!chatId) return
    if (chat && seed?.provider) applyChatComposerSelection(chat, seed.provider)
    if (seed?.prompt?.trim()) setChatPromptDraft(chatId, seed.prompt)
    setWorkflowDraft({
      chatId,
      cadence: 'manual',
      intervalMinutes: 60,
      maxRunsPerDay: 24,
      ensembleEnabled: chat?.chatKind === 'ensemble',
      unattendedLevel: 'safe'
    })
  }

  const handleOpenPluginWorkflowTemplate = async (
    templateId: string,
    workspaceOverride?: WorkspaceRecord
  ) => {
    const entry = pluginActivation?.workflowTemplates.find((template) => template.id === templateId)
    if (!entry) return
    await handleOpenWorkflowCompose(workspaceOverride, {
      prompt: entry.template.prompt,
      provider: entry.template.provider
    })
  }

  /**
   * Switch Ensemble off and continue the thread solo on `survivingParticipant`.
   * No provider modal: the seat passed in IS the answer, and its model /
   * reasoning / permissions ride across so the composer reopens exactly where
   * it left off. `setChatKind` stashes the outgoing roster, so flipping
   * Ensemble back on restores it.
   *
   * Two callers, both cases where the panel has stopped being a panel: the chip
   * strip removing a seat that would leave the roster below its floor, and the
   * Ensemble-off toggle on a roster that only ever had one provider to pick.
   *
   * `chatWithSeatRemoved` (chip strip only) lands BEFORE the mode change, so
   * the roster `setChatKind` stashes is the post-removal one — otherwise
   * flipping Ensemble back on would restore the seat the user just deleted.
   */
  const handleCollapseEnsembleToSoloForChat = async (
    targetChat: ChatRecord,
    survivingParticipant: EnsembleParticipant,
    targetIsRunning: boolean,
    chatWithSeatRemoved?: ChatRecord | null
  ): Promise<void> => {
    if (!targetChat.appChatId || targetChat.parentChatId) return
    if (targetChat.chatKind !== 'ensemble') return
    if (chatKindTogglingRef.current) return
    if (targetIsRunning) {
      appendThreadRawLog(targetChat.appChatId, {
        type: 'info',
        content: 'Finish the current turn first to change chat mode.'
      })
      return
    }
    // A shared thread cannot leave panel mode, and main refuses it. Bail HERE,
    // before the destructive save below.
    //
    // `chatWithSeatRemoved` is persisted BEFORE the mode change on purpose (see
    // the note above — it is what makes setChatKind stash the post-removal
    // roster). So letting main's refusal be the first line of defence would
    // delete the seat and THEN decline the collapse, leaving a shared panel
    // sitting below its own floor with nothing to undo it. Main's guard stays
    // the authority against callers that never come through here; this one
    // exists so the data is never destroyed on the way to being told no.
    if (collaboratingChatIds.has(targetChat.appChatId)) {
      appendThreadRawLog(targetChat.appChatId, {
        type: 'info',
        content: 'This chat is shared. Stop sharing before switching it out of panel mode.'
      })
      return
    }
    chatKindTogglingRef.current = true
    setChatKindMutationBusy(true)
    try {
      if (chatWithSeatRemoved) {
        await window.api.saveChat(chatWithSeatRemoved)
      }
      const updatedChat = applyHydratedChat(
        await window.api.setChatKind({
          chatId: targetChat.appChatId,
          targetKind: 'single',
          canonicalProvider: survivingParticipant.provider,
          canonicalProviderMetadata:
            buildProviderMetadataFromEnsembleParticipant(survivingParticipant)
        })
      )
      if (currentChatIdRef.current === updatedChat.appChatId) {
        applyChatComposerSelection(updatedChat, getChatProvider(updatedChat))
      }
      setSelectedParticipantForChat(updatedChat.appChatId, null)
      setWorkflowDraft((draft) =>
        draft?.chatId === updatedChat.appChatId ? { ...draft, ensembleEnabled: false } : draft
      )
      setPendingEnsembleToSoloChatId(null)
      void refreshChatList()
    } catch (error) {
      appendThreadRawLog(targetChat.appChatId, {
        type: 'stderr',
        content: redactLog(error instanceof Error ? error.message : String(error))
      })
    } finally {
      chatKindTogglingRef.current = false
      setChatKindMutationBusy(false)
    }
  }
  const handleCollapseEnsembleToSolo = async (
    survivingParticipant: EnsembleParticipant,
    chatWithSeatRemoved: ChatRecord | null
  ) => {
    if (!currentChat) return
    await handleCollapseEnsembleToSoloForChat(
      currentChat,
      survivingParticipant,
      isCurrentChatRunning,
      chatWithSeatRemoved
    )
  }

  // Slice C — in-place mid-thread ensemble toggle. The backend `setChatKind`
  // mutation preserves the SAME appChatId + transcript/runs/history; renderer
  // builds the seed participant (solo→ensemble) and the canonical-provider
  // metadata (ensemble→solo), while the backend enforces the idle-only guard.
  const handleToggleEnsembleForChat = async (
    targetChat: ChatRecord,
    enabled: boolean,
    targetIsRunning: boolean
  ): Promise<void> => {
    if (!targetChat.appChatId || targetChat.parentChatId) return
    if (settings?.ensembleModeEnabled === false && enabled) return
    if ((targetChat.chatKind === 'ensemble') === enabled) return
    if (chatKindTogglingRef.current) return
    if (targetIsRunning) {
      appendThreadRawLog(targetChat.appChatId, {
        type: 'info',
        content: 'Finish the current turn first to change chat mode.'
      })
      return
    }
    if (!enabled) {
      const modalChat = isChatSummaryRecord(targetChat)
        ? (await refreshSingleChat(targetChat.appChatId)) || targetChat
        : targetChat
      // The modal exists to ask WHICH agent keeps the thread. A roster the
      // floor exempts (Agent-MCP / imported one-seat panels, and legacy chats
      // that predate the floor) offers exactly one answer, so asking is pure
      // friction — collapse straight onto that seat.
      const soleParticipant = resolveSoleEnsembleSoloCandidate(modalChat)
      if (soleParticipant) {
        await handleCollapseEnsembleToSoloForChat(modalChat, soleParticipant, targetIsRunning)
        return
      }
      setPendingEnsembleToSoloChatId(modalChat.appChatId)
      return
    }
    chatKindTogglingRef.current = true
    setChatKindMutationBusy(true)
    try {
      const baseChat = isChatSummaryRecord(targetChat)
        ? (await refreshSingleChat(targetChat.appChatId)) || targetChat
        : targetChat
      const updatedChat = applyHydratedChat(
        await window.api.setChatKind({
          chatId: baseChat.appChatId,
          targetKind: 'ensemble',
          seedParticipant: buildEnsembleSeedParticipantFromChat(baseChat)
        })
      )
      if (currentChatIdRef.current === updatedChat.appChatId) {
        applyChatComposerSelection(updatedChat, getChatProvider(updatedChat))
      }
      setSelectedParticipantForChat(
        updatedChat.appChatId,
        updatedChat.ensemble?.participants[0]?.id || null
      )
      setWorkflowDraft((draft) =>
        draft?.chatId === updatedChat.appChatId ? { ...draft, ensembleEnabled: true } : draft
      )
      void refreshChatList()
    } catch (error) {
      appendThreadRawLog(targetChat.appChatId, {
        type: 'stderr',
        content: redactLog(error instanceof Error ? error.message : String(error))
      })
    } finally {
      chatKindTogglingRef.current = false
      setChatKindMutationBusy(false)
    }
  }
  const handleToggleWelcomeEnsemble = async (enabled: boolean) => {
    if (!currentChat) return
    await handleToggleEnsembleForChat(currentChat, enabled, isCurrentChatRunning)
  }

  const handleConfirmEnsembleToSolo = async (provider: ProviderId): Promise<void> => {
    const modalChat = ensembleToSoloModalChat
    if (!modalChat) return
    const providerChoice =
      ensembleToSoloCanonicalProviders.find((candidate) => candidate.provider === provider) || null
    chatKindTogglingRef.current = true
    setChatKindMutationBusy(true)
    try {
      const updatedChat = applyHydratedChat(
        await window.api.setChatKind({
          chatId: modalChat.appChatId,
          targetKind: 'single',
          canonicalProvider: provider,
          canonicalProviderMetadata: providerChoice?.metadata
        })
      )
      if (currentChatIdRef.current === updatedChat.appChatId) {
        applyChatComposerSelection(updatedChat, getChatProvider(updatedChat))
      }
      setSelectedParticipantForChat(updatedChat.appChatId, null)
      setWorkflowDraft((draft) =>
        draft?.chatId === updatedChat.appChatId ? { ...draft, ensembleEnabled: false } : draft
      )
      void refreshChatList()
      setPendingEnsembleToSoloChatId(null)
    } catch (error) {
      appendThreadRawLog(modalChat.appChatId, {
        type: 'stderr',
        content: redactLog(error instanceof Error ? error.message : String(error))
      })
    } finally {
      chatKindTogglingRef.current = false
      setChatKindMutationBusy(false)
    }
  }

  // First send on a workflow-compose chat: capture the prompt + run settings into
  // a WorkflowDefinition (reusing the same template/trigger builders as the modal)
  // rather than dispatching a one-off run. The chat becomes the workflow's thread.
  const createWorkflowFromDraft = async (
    request: ReturnType<typeof buildRunRequest>
  ): Promise<void> => {
    const draft = workflowDraft
    const chat = request.chatRecord
    if (!draft || !chat || !currentWorkspace) return
    const derivedName = request.prompt.trim().slice(0, 48) || 'New workflow'
    try {
      const saved = await window.api.saveWorkflowDefinition({
        name: derivedName,
        workspaceId: currentWorkspace.id,
        workspacePath: currentWorkspace.path,
        enabled: true,
        trigger: buildWorkflowCreatorTrigger(draft.cadence, draft.intervalMinutes),
        template: buildWorkflowTemplateFromRequest(request, chat, currentWorkspace),
        missedRunPolicy: 'skip',
        concurrencyPolicy: 'skip',
        limits: { maxRunsPerDay: draft.maxRunsPerDay, maxConsecutiveFailures: 3 }
      })
      setWorkflowDraft(null)
      await refreshWorkflowState(currentWorkspace.id)
      // The ack cannot ride the saved object (sanitizers strip it). Ask MAIN to
      // present the native, non-renderer-forgeable confirmation before minting it.
      if (draft.unattendedLevel && draft.unattendedLevel !== 'safe') {
        try {
          await window.api.setWorkflowUnattendedElevation(saved.id, draft.unattendedLevel)
        } catch (error) {
          setRawLogs((prev) => [
            ...prev,
            {
              type: 'stderr',
              content: `Workflow created, but unattended permissions were not enabled: ${
                error instanceof Error ? error.message : String(error)
              }`
            }
          ])
        }
        await refreshWorkflowState(currentWorkspace.id)
      }
      setRawLogs((prev) => [
        ...prev,
        {
          type: 'info',
          content:
            saved.trigger.kind === 'interval'
              ? `Workflow "${saved.name}" will run every ${Math.round((saved.trigger.intervalMs || 60_000) / 60_000)} minutes.`
              : `Workflow "${saved.name}" was created for manual runs.`
        }
      ])
    } catch (error) {
      // Keep the draft so the user can fix + retry; surface the reason instead
      // of failing silently (the welcome screen has no other error channel).
      setRawLogs((prev) => [
        ...prev,
        {
          type: 'stderr',
          content: `Couldn't create workflow: ${error instanceof Error ? error.message : String(error)}`
        }
      ])
    }
  }

  const handleRunWorkflowNow = async (workflowId: string) => {
    const task = await window.api.runWorkflowNow(workflowId)
    if (!task) return
    await refreshWorkflowState(currentWorkspace?.id)
  }

  const handleToggleWorkflowEnabled = async (workflow: WorkflowDefinition) => {
    await window.api.updateWorkflowDefinition(workflow.id, { enabled: !workflow.enabled })
    await refreshWorkflowState(currentWorkspace?.id)
  }

  const handleEditWorkflowInterval = async (workflow: WorkflowDefinition) => {
    const currentMinutes =
      workflow.trigger.kind === 'interval' && workflow.trigger.intervalMs
        ? Math.max(1, Math.round(workflow.trigger.intervalMs / 60_000))
        : 60
    const intervalText = window.prompt('Run every how many minutes?', String(currentMinutes))
    if (!intervalText) return
    const intervalMinutes = Number(intervalText)
    if (!Number.isFinite(intervalMinutes) || intervalMinutes <= 0) return
    const intervalMs = Math.max(60_000, Math.round(intervalMinutes * 60_000))
    await window.api.updateWorkflowDefinition(workflow.id, {
      trigger: {
        kind: 'interval',
        intervalMs,
        startAt: new Date(Date.now() + intervalMs).toISOString(),
        timezone:
          workflow.trigger.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || 'local'
      }
    })
    await refreshWorkflowState(currentWorkspace?.id)
  }

  const handleDeleteWorkflow = async (workflowId: string) => {
    const workflow = workflowDefinitions.find((item) => item.id === workflowId)
    const confirmed = window.confirm(
      workflow ? `Delete workflow "${workflow.name}"?` : 'Delete this workflow?'
    )
    if (!confirmed) return
    await window.api.deleteWorkflowDefinition(workflowId)
    await refreshWorkflowState(currentWorkspace?.id)
  }

  // No full workflow editor exists yet, so existing workflows get a small
  // "Unattended permissions" affordance in the sidebar. MAIN owns the native
  // confirmation for elevation; revocation remains immediate and fail-safe.
  const handleSetWorkflowUnattended = async (workflow: WorkflowDefinition): Promise<void> => {
    const current = workflow.unattendedElevation
    const level: UnattendedElevationLevel = current && current.level !== 'safe' ? 'safe' : 'default'
    try {
      await window.api.setWorkflowUnattendedElevation(workflow.id, level)
    } catch (error) {
      setRawLogs((prev) => [
        ...prev,
        {
          type: 'stderr',
          content: `Couldn't set unattended permissions: ${
            error instanceof Error ? error.message : String(error)
          }`
        }
      ])
    }
    await refreshWorkflowState(currentWorkspace?.id)
  }

  const handleCancelWorkflowExecution = async (workflow: WorkflowDefinition) => {
    const activeExecution = workflow.history.find(
      (execution) => execution.id === workflow.activeExecutionId
    )
    if (!activeExecution?.scheduledTaskId) return
    await window.api.cancelScheduledTask(
      activeExecution.scheduledTaskId,
      'Cancelled from Workflows.'
    )
    await refreshWorkflowState(currentWorkspace?.id)
  }

  const enterWorkspaceBoardMode = (boardId: string) => {
    setCurrentChatIdForNavigation(null)
    setCurrentChat(null)
    setActiveSidebarChatId(null)
    setSideChatId(null)
    setSideChatMenuOpen(false)
    setActiveWorkspaceBoardId(boardId)
    setActiveProjectGraphId(null)
    setRawLogs([])
    setRunCompleteNotice(null)
    setDiff(null)
    setRunDiff(null)
    setShowGeminiTerminal(false)
  }

  const enterProjectGraphMode = (projectId: string): void => {
    // The node graph is a Work-tab overlay. It deliberately does NOT clear the
    // current chat (so leaving the Work tab or opening a thread restores it) —
    // it only replaces the mutually-exclusive workspace-board overlay. Opening
    // is only reachable from the Work-tab "Node Graphs" section, and leaving the
    // Work tab closes it (handleActiveSidebarTabChange), so it never appears
    // over a chat you're actively reading.
    setActiveWorkspaceBoardId(null)
    setActiveProjectGraphId(projectId)
  }

  const handleOpenProjectGraph = (project: { id: string }): void => {
    enterProjectGraphMode(project.id)
  }

  const handleBackFromProjectGraph = (): void => {
    setActiveProjectGraphId(null)
  }

  const handleOpenThreadFromProjectGraph = (chatId: string): void => {
    const chat = chats.find((candidate) => candidate.appChatId === chatId)
    if (!chat) return
    setActiveProjectGraphId(null)
    void handleSelectChat(chat)
  }

  const handleAddProjectDependency = (fromChatId: string, toChatId: string): void => {
    if (activeProjectGraphId == null) return
    void addProjectGraphEdge({ projectId: activeProjectGraphId, fromChatId, toChatId }).catch(
      (error) => {
        console.error('Failed to add project dependency edge', error)
      }
    )
  }

  const handleRemoveProjectDependency = (edgeId: string): void => {
    void removeProjectGraphEdge(edgeId).catch((error) => {
      console.error('Failed to remove project dependency edge', error)
    })
  }

  const handleCreateWorkspaceBoard = async (input?: WorkspaceBoardCreateInput) => {
    if (!workspaceBoardApiReady) return
    if (!input) {
      setWorkspaceBoardCreatorOpen(true)
      return
    }
    const requestedWorkspace = input?.workspaceId
      ? workspaces.find((item) => item.id === input.workspaceId) || null
      : null
    const workspace =
      requestedWorkspace || (!input?.workspaceId ? currentWorkspace || workspaces[0] || null : null)
    if (!workspace) return
    const name = input?.name?.trim() || `${workspace.displayName} Board`
    const saved = await window.api.saveWorkspaceBoard({
      workspaceId: workspace.id,
      workspacePath: workspace.path,
      name,
      columns: [],
      provenance: createWorkspaceBoardProvenance('manual', {
        sourceId: workspace.id,
        sourceTitle: workspace.displayName,
        note: 'Created from the workspace boards sidebar.'
      })
    })
    if (currentWorkspace?.id !== workspace.id) {
      setCurrentWorkspace(workspace)
      currentWorkspaceIdRef.current = workspace.id
      currentWorkspacePathRef.current = workspace.path
      void refreshWorkspaceTrust(workspace)
    }
    setWorkspaceBoards((prev) => [saved, ...prev.filter((board) => board.id !== saved.id)])
    setWorkspaceBoardCreatorOpen(false)
    enterWorkspaceBoardMode(saved.id)
  }

  const handleOpenWorkspaceBoard = async (board: WorkspaceBoardDefinition) => {
    const workspace = workspaces.find((item) => item.id === board.workspaceId) || null
    if (workspace && currentWorkspace?.id !== workspace.id) {
      setCurrentWorkspace(workspace)
      currentWorkspaceIdRef.current = workspace.id
      currentWorkspacePathRef.current = workspace.path
      void refreshWorkspaceTrust(workspace)
    }
    enterWorkspaceBoardMode(board.id)
  }

  const handleRenameWorkspaceBoard = async (board: WorkspaceBoardDefinition) => {
    if (!workspaceBoardApiReady) return
    const nextName = window.prompt('Rename workspace board', board.name)?.trim()
    if (!nextName || nextName === board.name) return
    const updated = await window.api.updateWorkspaceBoard(board.id, { name: nextName })
    if (!updated) return
    setWorkspaceBoards((prev) => prev.map((item) => (item.id === updated.id ? updated : item)))
  }

  const handleTogglePinWorkspaceBoard = async (board: WorkspaceBoardDefinition) => {
    if (!workspaceBoardApiReady) return
    const updated = await window.api.updateWorkspaceBoard(board.id, { pinned: !board.pinned })
    if (!updated) return
    setWorkspaceBoards((prev) => prev.map((item) => (item.id === updated.id ? updated : item)))
  }

  const handleDuplicateWorkspaceBoard = async (board: WorkspaceBoardDefinition) => {
    if (!workspaceBoardApiReady) return
    const workspace = workspaces.find((item) => item.id === board.workspaceId) || null
    if (!workspace) return
    const nextName = window.prompt('Duplicate workspace board as', `${board.name} Copy`)?.trim()
    if (!nextName) return
    const savedBoard = await window.api.saveWorkspaceBoard({
      workspaceId: workspace.id,
      workspacePath: workspace.path,
      name: nextName,
      description: board.description,
      columns: board.columns,
      pinned: false,
      provenance: createWorkspaceBoardProvenance('duplicate', {
        sourceId: board.id,
        sourceTitle: board.name,
        note: 'Duplicated from an existing workspace board.'
      })
    })
    const sourceCards = workspaceBoardCards.filter(
      (card) => card.boardId === board.id && !card.archived
    )
    const savedCards: WorkspaceBoardCard[] = []
    for (const card of sourceCards) {
      const savedCard = await window.api.saveWorkspaceBoardCard({
        boardId: savedBoard.id,
        workspaceId: savedBoard.workspaceId,
        columnId: card.columnId,
        title: card.title,
        body: card.body,
        sortOrder: card.sortOrder,
        humanOwner: card.humanOwner,
        labels: card.labels,
        link: card.link,
        blockedReason: card.blockedReason,
        nextStep: card.nextStep,
        reminderAt: card.reminderAt,
        provenance: createWorkspaceBoardProvenance('duplicate', {
          sourceId: card.id,
          sourceTitle: card.title,
          note: `Copied from board "${board.name}".`
        })
      })
      savedCards.push(savedCard)
    }
    setWorkspaceBoards((prev) => [savedBoard, ...prev.filter((item) => item.id !== savedBoard.id)])
    setWorkspaceBoardCards((prev) => [
      ...prev.filter((item) => item.boardId !== savedBoard.id),
      ...savedCards
    ])
    if (currentWorkspace?.id !== workspace.id) {
      setCurrentWorkspace(workspace)
      currentWorkspaceIdRef.current = workspace.id
      currentWorkspacePathRef.current = workspace.path
      void refreshWorkspaceTrust(workspace)
    }
    enterWorkspaceBoardMode(savedBoard.id)
  }

  const handleArchiveWorkspaceBoard = async (boardId: string) => {
    if (!workspaceBoardApiReady) return
    const board = workspaceBoards.find((item) => item.id === boardId)
    const confirmed = window.confirm(
      board ? `Archive board "${board.name}"? Cards will stay recoverable.` : 'Archive this board?'
    )
    if (!confirmed) return
    const updated = await window.api.updateWorkspaceBoard(boardId, { archived: true })
    if (updated) {
      setWorkspaceBoards((prev) => prev.map((item) => (item.id === boardId ? updated : item)))
    }
    if (activeWorkspaceBoardId === boardId) setActiveWorkspaceBoardId(null)
  }

  const handleRestoreWorkspaceBoard = async (boardId: string) => {
    if (!workspaceBoardApiReady) return
    const updated = await window.api.updateWorkspaceBoard(boardId, { archived: false })
    if (updated) {
      setWorkspaceBoards((prev) => prev.map((item) => (item.id === boardId ? updated : item)))
    }
  }

  const handleDeleteWorkspaceBoard = async (boardId: string) => {
    if (!workspaceBoardApiReady) return
    const board = workspaceBoards.find((item) => item.id === boardId)
    const confirmed = window.confirm(
      board
        ? `Delete board "${board.name}" permanently? Its cards will also be deleted.`
        : 'Delete this board permanently? Its cards will also be deleted.'
    )
    if (!confirmed) return
    await window.api.deleteWorkspaceBoard(boardId)
    setWorkspaceBoards((prev) => prev.filter((item) => item.id !== boardId))
    setWorkspaceBoardCards((prev) => prev.filter((item) => item.boardId !== boardId))
    if (activeWorkspaceBoardId === boardId) setActiveWorkspaceBoardId(null)
  }

  const handleAddWorkspaceBoardCard = async (
    card: Omit<WorkspaceBoardCard, 'id' | 'createdAt' | 'updatedAt' | 'activity'>
  ) => {
    if (!workspaceBoardApiReady) return
    const saved = await window.api.saveWorkspaceBoardCard(card)
    setWorkspaceBoardCards((prev) => [...prev.filter((item) => item.id !== saved.id), saved])
  }

  const handleUpdateWorkspaceBoardCard = async (
    id: string,
    partial: Partial<WorkspaceBoardCard>
  ) => {
    if (!workspaceBoardApiReady) return
    const updated = await window.api.updateWorkspaceBoardCard(id, partial)
    if (!updated) return
    setWorkspaceBoardCards((prev) => prev.map((item) => (item.id === id ? updated : item)))
  }

  const handleDeleteWorkspaceBoardCard = async (id: string) => {
    if (!workspaceBoardApiReady) return
    await window.api.deleteWorkspaceBoardCard(id)
    setWorkspaceBoardCards((prev) => prev.filter((item) => item.id !== id))
  }

  const addWorkspaceBoardCapture = async (input: WorkspaceBoardCaptureInput): Promise<void> => {
    if (!workspaceBoardApiReady) return
    const workspace =
      (input.workspaceId ? workspaces.find((item) => item.id === input.workspaceId) : null) ||
      (input.workspacePath ? workspaces.find((item) => item.path === input.workspacePath) : null)
    if (!workspace) return

    let board =
      (activeWorkspaceBoardId
        ? workspaceBoards.find(
            (item) =>
              item.id === activeWorkspaceBoardId &&
              item.workspaceId === workspace.id &&
              !item.archived
          )
        : null) ||
      workspaceBoards.find((item) => item.workspaceId === workspace.id && !item.archived) ||
      null

    if (!board) {
      board = await window.api.saveWorkspaceBoard({
        workspaceId: workspace.id,
        workspacePath: workspace.path,
        name: `${workspace.displayName} Board`,
        columns: [],
        provenance: createWorkspaceBoardProvenance('capture', {
          sourceId: input.link ? `${input.link.kind}:${input.link.id}` : undefined,
          sourceTitle: input.title,
          note: 'Created automatically while capturing work to a board.'
        })
      })
      setWorkspaceBoards((prev) => [board!, ...prev.filter((item) => item.id !== board!.id)])
    }

    const targetLinkKey = input.link ? `${input.link.kind}:${input.link.id}` : ''
    const existing = targetLinkKey
      ? workspaceBoardCards.find(
          (card) =>
            card.boardId === board!.id &&
            card.link &&
            `${card.link.kind}:${card.link.id}` === targetLinkKey
        ) || null
      : null

    if (existing) {
      const updated = await window.api.updateWorkspaceBoardCard(existing.id, {
        title: input.title,
        body: input.body || existing.body,
        labels: input.labels || existing.labels,
        blockedReason: input.blockedReason || existing.blockedReason,
        nextStep: input.nextStep || existing.nextStep,
        provenance: input.provenance || existing.provenance,
        archived: false,
        columnId: input.columnId || existing.columnId,
        sortOrder: Date.now()
      })
      if (updated) {
        setWorkspaceBoardCards((prev) =>
          prev.map((item) => (item.id === updated.id ? updated : item))
        )
      }
      return
    }

    const saved = await window.api.saveWorkspaceBoardCard({
      boardId: board.id,
      workspaceId: workspace.id,
      columnId: input.columnId || 'inbox',
      title: input.title,
      body: input.body,
      labels: input.labels,
      link: input.link,
      blockedReason: input.blockedReason,
      nextStep: input.nextStep,
      provenance:
        input.provenance ||
        createWorkspaceBoardProvenance('capture', {
          sourceId: input.link ? `${input.link.kind}:${input.link.id}` : undefined,
          sourceTitle: input.title,
          note: 'Captured from an existing TaskWraith surface.'
        }),
      sortOrder: Date.now()
    })
    setWorkspaceBoardCards((prev) => [...prev.filter((item) => item.id !== saved.id), saved])
  }

  const compactBoardLabels = (...labels: Array<string | undefined | null | false>): string[] =>
    labels.filter((label): label is string => typeof label === 'string' && label.trim().length > 0)

  const chatBoardColumn = (chat: ChatRecord): WorkspaceBoardCard['columnId'] => {
    const run = chat.runs?.[chat.runs.length - 1]
    if (
      runningChatIds.has(chat.appChatId) ||
      run?.status === 'running' ||
      run?.status === 'sleeping'
    ) {
      return 'running'
    }
    if (chat.activeGoal?.status === 'blocked') return 'blocked'
    if (run?.status === 'failed' || run?.status === 'cancelled') return 'needs-input'
    if (
      run?.status === 'success' ||
      run?.status === 'success_with_warnings' ||
      run?.status === 'completed'
    ) {
      return 'review-ready'
    }
    return 'inbox'
  }

  const workflowBoardColumn = (workflow: WorkflowDefinition): WorkspaceBoardCard['columnId'] => {
    if (
      workflow.activeExecutionId ||
      workflow.lastStatus === 'running' ||
      workflow.lastStatus === 'queued'
    ) {
      return 'running'
    }
    if (
      workflow.lastStatus === 'failed' ||
      workflow.lastStatus === 'cancelled' ||
      workflow.failureStreak > 0
    ) {
      return 'needs-input'
    }
    if (workflow.lastStatus === 'completed') return 'review-ready'
    return 'ready'
  }

  const runQueueJobBoardColumn = (job: RunQueueJob): WorkspaceBoardCard['columnId'] => {
    if (
      job.status === 'queued' ||
      job.status === 'starting' ||
      job.status === 'active' ||
      job.status === 'steer_promoting'
    ) {
      return 'running'
    }
    if (job.status === 'failed' || job.status === 'cancelled') return 'needs-input'
    if (job.status === 'completed') return 'done'
    return 'ready'
  }

  const handleAddChatToWorkspaceBoard = (chat: ChatRecord): void => {
    if (!chat.workspaceId || chat.scope === 'global') return
    void addWorkspaceBoardCapture({
      workspaceId: chat.workspaceId,
      workspacePath: chat.workspacePath,
      title: chat.title || 'Workspace thread',
      body: chat.activeGoal?.objective ? `Goal: ${chat.activeGoal.objective}` : undefined,
      labels: compactBoardLabels('thread', chat.provider),
      link: { kind: 'chat', id: chat.appChatId },
      columnId: chatBoardColumn(chat),
      blockedReason:
        chat.activeGoal?.status === 'blocked' ? chat.activeGoal.blockedReason : undefined,
      provenance: createWorkspaceBoardProvenance('thread', {
        sourceId: chat.appChatId,
        sourceTitle: chat.title,
        provider: chat.provider,
        note: 'Captured from a chat row.'
      })
    })
  }

  const handleAddWorkflowToWorkspaceBoard = (workflow: WorkflowDefinition): void => {
    void addWorkspaceBoardCapture({
      workspaceId: workflow.workspaceId,
      workspacePath: workflow.workspacePath,
      title: workflow.name,
      body: workflow.lastError || workflow.template.prompt,
      labels: compactBoardLabels('workflow', workflow.template.provider, workflow.lastStatus),
      link: { kind: 'workflow', id: workflow.id },
      columnId: workflowBoardColumn(workflow),
      provenance: createWorkspaceBoardProvenance('capture', {
        sourceId: workflow.id,
        sourceTitle: workflow.name,
        provider: workflow.template.provider,
        note: 'Captured from a workflow row.'
      })
    })
  }

  const handleAddRunQueueJobToWorkspaceBoard = (job: RunQueueJob): void => {
    if (!job.workspaceId) return
    void addWorkspaceBoardCapture({
      workspaceId: job.workspaceId,
      workspacePath: job.workspacePath,
      title: job.promptPreview || job.request?.displayPrompt || job.request?.prompt || job.runId,
      body: job.lastError || job.statusReason || job.request?.prompt,
      labels: compactBoardLabels('run', job.provider, job.status),
      link: { kind: 'run-queue-job', id: job.id },
      columnId: runQueueJobBoardColumn(job),
      provenance: createWorkspaceBoardProvenance('capture', {
        sourceId: job.id,
        sourceTitle: job.promptPreview || job.runId,
        provider: job.provider,
        runId: job.runId,
        note: 'Captured from a run queue job.'
      })
    })
  }

  const handleAddLocalServerToWorkspaceBoard = (server: LocalServerEntry): void => {
    if (!server.workspaceId) return
    void addWorkspaceBoardCapture({
      workspaceId: server.workspaceId,
      workspacePath: server.workspacePath,
      title: `Local server: ${server.name}`,
      body: [
        server.primaryPort != null ? `http://localhost:${server.primaryPort}` : undefined,
        server.command
      ]
        .filter(Boolean)
        .join('\n'),
      labels: compactBoardLabels('local-server', server.origin),
      link: { kind: 'local-server', id: server.id },
      columnId: 'running',
      provenance: createWorkspaceBoardProvenance('capture', {
        sourceId: server.id,
        sourceTitle: server.name,
        provider: server.provider,
        runId: server.runId,
        note: 'Captured from the local servers list.'
      })
    })
  }

  const handleAddPinnedMessageToWorkspaceBoard = (message: PinnedMessageSummary): void => {
    if (!currentChat?.workspaceId || currentChat.scope === 'global') return
    void addWorkspaceBoardCapture({
      workspaceId: currentChat.workspaceId,
      workspacePath: currentChat.workspacePath,
      title: `Pinned: ${currentChat.title || 'Thread'}`,
      body: message.content.slice(0, 1200),
      labels: compactBoardLabels('pinned-message', message.role),
      link: { kind: 'pinned-message', id: `${currentChat.appChatId}:${message.id}` },
      columnId: 'inbox',
      provenance: createWorkspaceBoardProvenance('capture', {
        sourceId: `${currentChat.appChatId}:${message.id}`,
        sourceTitle: currentChat.title,
        provider: currentChat.provider,
        runId: message.runId,
        note: 'Captured from a pinned message.'
      })
    })
  }

  const getCockpitRunSource = (
    lane: RunLane
  ): { chat: ChatRecord | null; run: ChatRun | null; prompt: string } => {
    return resolveCockpitRunSource(lane, chats, chatByIdRef.current)
  }

  const handleOpenCockpitThread = (chatId?: string) => {
    if (!chatId) return
    const chat = chatByIdRef.current.get(chatId) || chats.find((item) => item.appChatId === chatId)
    if (chat) {
      if (chat.parentChatRelation === 'sideChat' || chat.parentChatRelation === 'subThread') {
        void openLinkedChatAsMain(chat)
      } else {
        void handleSelectChat(chat)
      }
      setShowCockpit(false)
    }
  }

  const handleCancelRunLane = (lane: RunLane) => {
    if (lane.scheduledTaskId) {
      void window.api
        .cancelScheduledTask(lane.scheduledTaskId, 'Cancelled from Cockpit.')
        .then(() => refreshWorkflowState(currentWorkspaceIdRef.current || undefined))
      return
    }
    if (!lane.runId) return
    setQueuedRuns((prev) => prev.filter((request) => request.appRunId !== lane.runId))
    if (lane.phase === 'queued' || lane.phase === 'paused') {
      updateRunQueueJobStatus(lane.runId, 'cancelled', 'Cancelled from Cockpit.')
      return
    }
    void window.api.cancelAgentRun(lane.provider, lane.runId).catch(() => {
      if (lane.provider === 'gemini') {
        void window.api.cancelGemini(lane.runId)
      }
    })
  }

  const handleRetryRunLane = (lane: RunLane) => {
    const { chat, run, prompt: sourcePrompt } = getCockpitRunSource(lane)
    if (!chat || !sourcePrompt.trim()) return
    const workspace = getWorkspaceForChat(chat) || undefined
    const provider = lane.provider || getChatProvider(chat)
    const selection = getChatComposerSelection(chat, provider)
    const requestedRetryModel = run?.requestedModel
    const retryModel = isValidModelForProvider(provider, requestedRetryModel)
      ? requestedRetryModel
      : selection.selectedModelType
    const request: QueuedRunRequest = {
      appRunId: createAppRunId(),
      scope: getChatScope(chat),
      provider,
      prompt: sourcePrompt,
      displayPrompt: `[retry] ${sourcePrompt}`,
      existingPrompt: sourcePrompt,
      selectedModelType: retryModel,
      customModel: selection.customModel,
      approvalMode: run?.approvalMode || selection.approvalMode,
      sessionTrust,
      imageAttachments: [],
      externalPathGrants:
        getChatScope(chat) === 'global'
          ? []
          : normalizeExternalPathGrants(
              collectExternalPathGrantsFromMetadata(chat.providerMetadata)
            ).filter((grant) => grant.provider === provider),
      geminiWorktree:
        getChatScope(chat) === 'global'
          ? undefined
          : resolveGeminiWorktreeConfig(workspace || null),
      codexReasoningEffort: selection.codexReasoningEffort,
      codexServiceTier: selection.codexServiceTier,
      claudeReasoningEffort: selection.claudeReasoningEffort,
      claudeFastMode: selection.claudeFastMode,
      kimiFastMode: selection.kimiFastMode,
      kimiReasoningEffort: selection.kimiReasoningEffort,
      kimiThinkingEnabled: selection.kimiThinkingEnabled,
      grokReasoningEffort: selection.grokReasoningEffort,
      museReasoningEffort: selection.museReasoningEffort,
      mistralReasoningEffort: selection.mistralReasoningEffort,
      piReasoningEffort: selection.piReasoningEffort,
      antigravityReasoningEffort: selection.antigravityReasoningEffort,
      ollamaReasoningEffort: selection.ollamaReasoningEffort,
      cursorReasoningEffort: selection.cursorReasoningEffort,
      cursorFastMode: selection.cursorFastMode,
      runtimeProfileId: lane.runtimeProfileId || getRuntimeProfileIdForChat(chat, provider),
      handoffSourceRunId: lane.handoffSourceRunId,
      workspaceRecord: getChatScope(chat) === 'global' ? undefined : workspace,
      chatRecord: chat
    }
    if (
      shouldQueueRunBeforeDispatch({
        chatKind: chat.chatKind,
        busy: isChatBusy(chat.appChatId)
      })
    ) {
      queueRunRequest(
        request,
        `Retry is waiting for this chat's active ${getProviderLabel(provider)} task to exit.`
      )
      return
    }
    void executeRun(request)
  }

  const handleDuplicateRunLane = async (lane: RunLane) => {
    const { chat, prompt: sourcePrompt } = getCockpitRunSource(lane)
    if (!chat) return
    const provider = lane.provider || getChatProvider(chat)
    if (!isRunnableProvider(provider)) {
      const message = `${getProviderOfferUnavailableReason(provider)} This run lane cannot be duplicated with that provider; choose a currently offered provider first.`
      appendThreadRawLog(chat.appChatId, { type: 'info', content: message })
      window.alert(message)
      return
    }
    const workspace = getWorkspaceForChat(chat)
    const duplicate = isGlobalChat(chat)
      ? await window.api.createGlobalChat()
      : workspace
        ? await window.api.createChat(workspace.id, workspace.path)
        : null
    if (!duplicate) return
    const updatedDuplicate: ChatRecord = {
      ...duplicate,
      provider,
      providerMetadata: {
        ...(duplicate.providerMetadata || {}),
        runtimeProfileId: lane.runtimeProfileId || getRuntimeProfileIdForChat(chat, provider)
      },
      title: `${chat.title || getProviderLabel(provider)} copy`,
      updatedAt: Date.now()
    }
    await window.api.saveChat(updatedDuplicate)
    chatByIdRef.current.set(updatedDuplicate.appChatId, updatedDuplicate)
    setChats((prev) => mergeChatRecord(prev, updatedDuplicate))
    setChatPromptDraft(updatedDuplicate.appChatId, sourcePrompt)
    setRuntimeProfileForChat(
      updatedDuplicate.appChatId,
      typeof updatedDuplicate.providerMetadata?.runtimeProfileId === 'string'
        ? updatedDuplicate.providerMetadata.runtimeProfileId
        : ''
    )
    void handleSelectChat(updatedDuplicate)
    setShowCockpit(false)
  }

  const handleCreateHandoffFromLane = async (lane: RunLane) => {
    const { chat, run, prompt: sourcePrompt } = getCockpitRunSource(lane)
    if (!chat || !run || typeof window.api.saveHandoffCard !== 'function') return
    const latestAssistantMessage = [...chat.messages]
      .reverse()
      .find((message) => message.role === 'assistant')
    const selectedFiles = extractRunTouchedFiles(run)
    const summary = latestAssistantMessage?.content
      ? compactPromptPreview(latestAssistantMessage.content)
      : `Continue work from ${getProviderLabel(lane.provider)} run ${run.runId}.`
    const finalPrompt = [
      `Continue from ${getProviderLabel(lane.provider)} run ${run.runId}.`,
      `Source chat: ${chat.title || chat.appChatId}.`,
      selectedFiles.length > 0
        ? `Files touched: ${selectedFiles.slice(0, 24).join(', ')}`
        : 'Files touched: none recorded.',
      formatOpaqueMarkdownPromptSection('Prior request', sourcePrompt),
      latestAssistantMessage?.content
        ? formatOpaqueMarkdownPromptSection(
            'Latest assistant summary',
            latestAssistantMessage.content
          )
        : ''
    ]
      .filter(Boolean)
      .join('\n\n')
    const card = await window.api.saveHandoffCard({
      sourceChatId: chat.appChatId,
      sourceRunId: run.runId,
      sourceProvider: lane.provider,
      workspaceId: chat.workspaceId,
      workspacePath: chat.workspacePath,
      summary,
      selectedFiles,
      workspaceChangeSetIds: run.workspaceChangeSetId ? [run.workspaceChangeSetId] : [],
      rawEventRunIds: [run.runId],
      recommendedProvider: lane.provider,
      recommendedModel: run.actualModel || run.requestedModel,
      recommendedApprovalMode: run.approvalMode,
      finalPrompt
    })
    setHandoffCards((prev) => [card, ...prev.filter((item) => item.id !== card.id)])
    closeOtherRightDockPanels('run')
    setShowCockpit(true)
    setRightDockTab('run')
  }

  const handleDispatchHandoff = async (card: HandoffCard) => {
    const sourceChat =
      chatByIdRef.current.get(card.sourceChatId) ||
      chats.find((item) => item.appChatId === card.sourceChatId)
    const provider = card.recommendedProvider || card.sourceProvider
    if (!isRunnableProvider(provider)) {
      const message = `${getProviderOfferUnavailableReason(provider)} This handoff cannot be dispatched to that provider; choose a currently offered provider first.`
      appendThreadRawLog(sourceChat?.appChatId || card.sourceChatId, {
        type: 'info',
        content: message
      })
      window.alert(message)
      return
    }
    const workspace = sourceChat ? getWorkspaceForChat(sourceChat) : null
    const targetChat =
      sourceChat && isGlobalChat(sourceChat)
        ? await window.api.createGlobalChat()
        : workspace
          ? await window.api.createChat(workspace.id, workspace.path)
          : null
    if (!targetChat) return
    const updatedTarget: ChatRecord = {
      ...targetChat,
      provider,
      title: `Handoff from ${getProviderLabel(card.sourceProvider)}`,
      updatedAt: Date.now()
    }
    await window.api.saveChat(updatedTarget)
    const updatedCard = await window.api.updateHandoffCard(card.id, {
      status: 'dispatched',
      targetChatId: updatedTarget.appChatId,
      dispatchedAt: new Date().toISOString()
    })
    if (updatedCard) {
      setHandoffCards((prev) =>
        prev.map((item) => (item.id === updatedCard.id ? updatedCard : item))
      )
    }
    chatByIdRef.current.set(updatedTarget.appChatId, updatedTarget)
    setChats((prev) => mergeChatRecord(prev, updatedTarget))
    setChatPromptDraft(updatedTarget.appChatId, card.finalPrompt)
    void handleSelectChat(updatedTarget)
    setShowCockpit(false)
  }

  const handleArchiveHandoff = async (card: HandoffCard) => {
    const updated = await window.api.updateHandoffCard(card.id, { status: 'archived' })
    if (updated) {
      setHandoffCards((prev) => prev.map((item) => (item.id === updated.id ? updated : item)))
    }
  }

  const handlePersistRunAnalysis = (
    chatId: string,
    runId: string,
    snapshot: RunAnalystSnapshot
  ) => {
    const sourceChat =
      chatByIdRef.current.get(chatId) || chats.find((item) => item.appChatId === chatId)
    if (!sourceChat?.runs?.some((run) => run.runId === runId)) return
    const updatedChat: ChatRecord = {
      ...sourceChat,
      runs: sourceChat.runs.map((run) =>
        run.runId === runId ? { ...run, runAnalyst: snapshot } : run
      ),
      updatedAt: Date.now()
    }
    chatByIdRef.current.set(updatedChat.appChatId, updatedChat)
    setChats((prev) =>
      prev.map((item) => (item.appChatId === updatedChat.appChatId ? updatedChat : item))
    )
    setCurrentChat((prev) => (prev?.appChatId === updatedChat.appChatId ? updatedChat : prev))
    void window.api.saveChat(updatedChat).catch(() => {})
  }

  const appendRawInfoOnce = (content: string) => {
    setRawLogs((prev) =>
      prev[prev.length - 1]?.content === content ? prev : [...prev, { type: 'info', content }]
    )
  }

  const markPersistentSessionRestartNeeded = (content: string) => {
    if (!persistentSessionActiveRef.current) {
      return
    }
    setPersistentSessionNeedsRestart(true)
    appendRawInfoOnce(content)
  }

  const stopPersistentGeminiSession = async (
    message = 'Persistent Gemini session stopped.'
  ): Promise<boolean> => {
    const geminiSessionApi = window.api as any
    if (typeof geminiSessionApi.stopGeminiSession !== 'function') {
      persistentSessionActiveRef.current = false
      setIsPersistentSessionEnabled(false)
      setPersistentSessionStatus('unavailable')
      setPersistentSessionNeedsRestart(false)
      return false
    }

    setPersistentSessionStatus('stopping')
    try {
      await geminiSessionApi.stopGeminiSession()
      persistentSessionActiveRef.current = false
      setIsPersistentSessionEnabled(false)
      setPersistentSessionStatus('idle')
      setPersistentSessionNeedsRestart(false)
      if (message) {
        appendRawInfoOnce(message)
      }
      return true
    } catch (error) {
      setPersistentSessionStatus('error')
      setRawLogs((prev) => [
        ...prev,
        {
          type: 'info',
          content: `Failed to stop persistent Gemini session: ${redactLog(String(error))}`
        }
      ])
      return false
    }
  }

  const startPersistentGeminiSession = async (): Promise<boolean> => {
    const geminiSessionApi = window.api as any

    if (persistentSessionActiveRef.current && persistentSessionNeedsRestart) {
      const stopped = await stopPersistentGeminiSession(
        'Persistent Gemini session stopped for restart.'
      )
      if (!stopped) {
        return false
      }
    }

    if (persistentSessionActiveRef.current) {
      setIsPersistentSessionEnabled(true)
      setPersistentSessionStatus('active')
      return true
    }

    const sessionWorkspace = currentChatWorkspace || currentWorkspace
    if (!sessionWorkspace || typeof geminiSessionApi.startGeminiSession !== 'function') {
      setPersistentSessionStatus('unavailable')
      setRawLogs((prev) => [
        ...prev,
        {
          type: 'info',
          content:
            'Persistent Gemini session API is unavailable; command bridge will queue text in chat/raw logs.'
        }
      ])
      return false
    }

    const modelToPass = selectedModelType === 'custom' ? customModel.trim() : selectedModelType
    const worktree = resolveGeminiWorktreeConfig(sessionWorkspace)
    const resumeDecision = currentChat
      ? resolveGeminiResumeForRun(
          currentChat,
          modelToPass,
          approvalMode,
          worktree,
          geminiAuthStatus?.activeProfileId || null
        )
      : {}
    const resumeSessionId = resumeDecision.sessionId
    if (resumeDecision.skippedReason) {
      appendRawInfoOnce(resumeDecision.skippedReason)
      if (currentChat) {
        updateChatById(currentChat.appChatId, (source) => ({
          ...source,
          linkedGeminiSessionId: undefined,
          updatedAt: Date.now()
        }))
      }
    }
    setIsPersistentSessionEnabled(true)
    setPersistentSessionStatus('starting')
    setPersistentSessionNeedsRestart(false)

    try {
      await geminiSessionApi.startGeminiSession(
        sessionWorkspace.path,
        modelToPass,
        approvalMode,
        sessionTrust,
        undefined,
        undefined,
        resumeSessionId,
        worktree
      )
      persistentSessionActiveRef.current = true
      setPersistentSessionStatus('active')
      setPersistentSessionNeedsRestart(false)
      if (isGeminiWorktreeDiffUnavailable(worktree)) {
        setDiff(createWorktreeDiffUnavailable())
        setRunDiff(null)
        setDiffView('workspace')
        setDiffRefreshStatus('Diff disabled: worktree path unknown.')
      }
      setRawLogs((prev) => [
        ...prev,
        {
          type: 'info',
          content: `Persistent Gemini session ${resumeSessionId ? `resumed from ${resumeSessionId}` : 'started'}${modelToPass ? ` with ${modelToPass}` : ''}${worktree?.enabled ? ` in worktree ${worktree.name || 'enabled'}` : ''}.`
        }
      ])
      if (typeof geminiSessionApi.resizeGeminiSession === 'function') {
        const cols = Math.max(80, Math.floor(window.innerWidth / 8))
        const rows = Math.max(24, Math.floor(window.innerHeight / 18))
        geminiSessionApi.resizeGeminiSession(cols, rows).catch?.(() => {})
      }
      return true
    } catch (error) {
      persistentSessionActiveRef.current = false
      setIsPersistentSessionEnabled(false)
      setPersistentSessionStatus('error')
      setPersistentSessionNeedsRestart(false)
      setRawLogs((prev) => [
        ...prev,
        {
          type: 'info',
          content: `Failed to start persistent Gemini session: ${redactLog(String(error))}`
        }
      ])
      return false
    }
  }

  const handleBridgeCommand = async (command: string) => {
    const commandText = command
    const geminiSessionApi = window.api as any
    const sessionReady = await startPersistentGeminiSession()
    if (!sessionReady || typeof geminiSessionApi.writeGeminiSession !== 'function') {
      return
    }

    geminiSessionApi.writeGeminiSession(`${commandText}\n`).catch(() => {})
    openInspectorTab('raw')
    setRawLogs((prev) => [
      ...prev,
      { type: 'info', content: `Sent Gemini command: ${commandText}` }
    ])
  }

  const handlePaletteCommand = (item: CommandPaletteItem) => {
    // 1.0.4-AT6 — when an ensemble chat has a selected participant,
    // route diagnostic slash commands (`/status`, `/model`,
    // `/permissions`, `/mcp`, `/resume`, `/fork`) at THAT
    // participant's provider rather than the chat-level provider.
    // Pre-AT6 these commands always read `currentProvider`, so
    // running `/status` from an ensemble where Codex was the
    // chat-level provider but the selected chip was a Claude
    // participant showed Codex's status, not Claude's. The
    // effective provider is also passed to `refreshProviderMetadata`
    // so the right-tab data reflects the targeted participant.
    const slashTargetProvider: ProviderId =
      isCurrentEnsembleChat && selectedParticipant ? selectedParticipant.provider : currentProvider
    if (slashTargetProvider === 'codex') {
      if (item.command === '/status' || item.command === '/permissions') {
        openInspectorTab('safety')
      } else if (
        item.command === '/model' ||
        item.command === '/mcp' ||
        item.command === '/resume'
      ) {
        openInspectorTab('capabilities')
        if (item.command === '/resume') {
          void refreshCodexThreads()
        }
      } else if (item.command === '/diff') {
        openInspectorTab('diff')
      } else if (item.command === '/review') {
        void handleReviewCurrentDiff()
      } else if (item.command === '/fast') {
        // Was chat-level only, on the reasoning that fast mode is a chat
        // composer pick rather than a per-participant setting. It is both now —
        // the picker patches `fastModeEnabled` on a bound seat — so this routes
        // through the same helper as every other provider and lands wherever
        // the picker's own switch would.
        applyFastModeToggleFromSlash(slashTargetProvider)
      } else if (item.command === '/fork') {
        const threadId =
          isCurrentEnsembleChat && selectedParticipant?.provider === currentProvider
            ? selectedParticipant.linkedProviderSessionId
            : currentChat?.linkedProviderSessionId
        void handleForkAgentThread(currentProvider, threadId || undefined)
      }
      return
    }
    if (
      slashTargetProvider === 'claude' ||
      slashTargetProvider === 'kimi' ||
      slashTargetProvider === 'grok' ||
      slashTargetProvider === 'cursor' ||
      slashTargetProvider === 'ollama'
    ) {
      // Grok/Cursor/Ollama route here too: their slash commands are the
      // generic CLI core. /review dispatches TaskWraith's provider-agnostic
      // read-only diff review (a plan-mode run), not provider-native TUI commands.
      if (item.command === '/status' || item.command === '/permissions') {
        void refreshProviderMetadata(slashTargetProvider)
        openInspectorTab('safety')
      } else if (item.command === '/model') {
        void refreshProviderMetadata(slashTargetProvider)
        openInspectorTab('capabilities')
      } else if (item.command === '/diff') {
        openInspectorTab('diff')
      } else if (item.command === '/review') {
        void handleReviewCurrentDiff()
      } else if (item.command === '/fork') {
        const threadId =
          isCurrentEnsembleChat && selectedParticipant?.provider === slashTargetProvider
            ? selectedParticipant.linkedProviderSessionId
            : currentChat?.linkedProviderSessionId
        void handleForkAgentThread(slashTargetProvider, threadId || undefined)
      } else if (item.command === '/fast') {
        // Fast is a chat-level composer pick here, matching the Codex branch
        // above: it moves live state + the remembered selection rather than a
        // bound participant. `nextFastModeToggle` owns the per-provider
        // mechanics so this never drifts from the picker's own switch. Kimi's
        // service tier rides along inside the descriptor.
        applyFastModeToggleFromSlash(slashTargetProvider)
      }
      return
    }
  }

  // promptWithoutCurrentSlashToken / consumeSlashTokenFromPrompt /
  // handleImportPlanSlashCommand moved INTO <Composer> (Slice C). App-level
  // slash `run()` closures now receive a SlashCommandRunContext
  // ({ promptWithoutSlashToken, consumeSlashToken, setDraft, focusComposer })
  // so they operate on the INVOKING composer instead of the old single shared
  // textarea ref + App `prompt`/`setPrompt`.

  const currentActiveGoal = currentChat?.activeGoal || null
  const currentGoalAllowProviderNative = currentChat?.chatKind !== 'ensemble'
  const currentGoalModeOptions = {
    codexNativeAvailable:
      currentGoalAllowProviderNative &&
      Boolean(currentChat?.providerMetadata?.codexGoalNativeAvailable),
    claudeNativeAvailable:
      currentGoalAllowProviderNative &&
      Boolean(currentChat?.providerMetadata?.claudeGoalNativeAvailable),
    grokNativeAvailable: currentGoalAllowProviderNative && currentProvider === 'grok',
    allowProviderNative: currentGoalAllowProviderNative
  }
  const currentResolvedGoal = resolveActiveGoalForProvider(
    currentActiveGoal,
    currentProvider,
    currentGoalModeOptions
  )
  const currentGoalMode =
    currentResolvedGoal?.mode || resolveActiveGoalMode(currentProvider, currentGoalModeOptions)
  const currentGoalModeLabel = activeGoalModeLabel(currentGoalMode)
  const currentGoalStatus = currentActiveGoal?.status || 'empty'
  const currentGoalButtonTitle = currentActiveGoal
    ? `${currentGoalModeLabel} · ${currentActiveGoal.status}: ${currentActiveGoal.objective}`
    : `${currentGoalModeLabel} · Set an active goal`

  const persistGoalForCurrentChat = (nextGoal: ActiveGoal | null): void => {
    const chat = currentChat
    if (!chat) return
    const updated: ChatRecord = nextGoal
      ? {
          ...chat,
          activeGoal: nextGoal,
          updatedAt: Date.now()
        }
      : {
          ...chat,
          updatedAt: Date.now()
        }
    if (!nextGoal) {
      delete updated.activeGoal
    }
    chatByIdRef.current.set(updated.appChatId, updated)
    setCurrentChat(updated)
    setChats((prev) => mergeChatRecord(prev, updated))
    void window.api.saveChat(updated).catch((err) => {
      console.error('[goal] saveChat failed', err)
    })
  }

  const setGoalFromObjective = (
    rawObjective: string,
    options: { confirmReplace?: boolean } = {}
  ): boolean => {
    const objective = normalizeActiveGoalObjective(rawObjective)
    const existingGoal = currentActiveGoal
    if (!objective) {
      window.alert('Type a goal objective first.')
      return false
    }
    if (
      options.confirmReplace !== false &&
      existingGoal &&
      existingGoal.status !== 'completed' &&
      existingGoal.objective.trim() !== objective
    ) {
      const confirmed = window.confirm(
        'Replace the current active goal?\n\nThe existing goal will stop steering this chat.'
      )
      if (!confirmed) return false
    }
    const now = new Date()
    const mode = resolveActiveGoalMode(currentProvider, {
      codexNativeAvailable:
        currentGoalAllowProviderNative &&
        Boolean(currentChat?.providerMetadata?.codexGoalNativeAvailable),
      claudeNativeAvailable:
        currentGoalAllowProviderNative &&
        Boolean(currentChat?.providerMetadata?.claudeGoalNativeAvailable),
      grokNativeAvailable: currentGoalAllowProviderNative && currentProvider === 'grok',
      allowProviderNative: currentGoalAllowProviderNative
    })
    const shouldStartFreshGoal =
      !existingGoal ||
      existingGoal.status === 'completed' ||
      existingGoal.objective.trim() !== objective
    const goal: ActiveGoal =
      shouldStartFreshGoal || !existingGoal
        ? createActiveGoal(currentProvider, objective, {
            now,
            codexNativeAvailable:
              currentGoalAllowProviderNative &&
              Boolean(currentChat?.providerMetadata?.codexGoalNativeAvailable),
            claudeNativeAvailable:
              currentGoalAllowProviderNative &&
              Boolean(currentChat?.providerMetadata?.claudeGoalNativeAvailable),
            grokNativeAvailable: currentGoalAllowProviderNative && currentProvider === 'grok',
            allowProviderNative: currentGoalAllowProviderNative,
            objectiveSource: 'user'
          })
        : {
            ...updateActiveGoalLifecycle(existingGoal, 'active', undefined, now),
            objective,
            objectiveSource: 'user',
            provider: currentProvider,
            mode,
            updatedAt: now.toISOString()
          }
    persistGoalForCurrentChat(goal)
    setGoalDraft(goal.objective)
    setGoalEditing(false)
    setGoalPopoverOpen(true)
    return true
  }

  const handleGroundImportedPlanFiles = async (): Promise<void> => {
    const review = pendingPlanImport
    const chatId = currentComposerChatId
    if (!review || !chatId || review.contract.fileGroundings.length === 0) return
    if (planImportGroundingBusy) return

    const workspaceForReview = currentChat ? getWorkspaceForChat(currentChat) : currentWorkspace
    if (!workspaceForReview?.path) {
      window.alert('Open a workspace chat before checking path mentions.')
      return
    }

    setPlanImportGroundingBusyForChat(chatId, true)
    try {
      const workspaceFiles = await window.api.listWorkspaceFiles(workspaceForReview.path)
      setPendingPlanImportForChat(chatId, (previous) =>
        previous && previous.id === review.id
          ? {
              ...previous,
              contract: groundPlanImportFileMentions(previous.contract, workspaceFiles, {
                workspacePath: workspaceForReview.path
              })
            }
          : previous
      )
    } catch (error) {
      window.alert(`Could not check file mentions: ${redactLog(String(error))}`)
    } finally {
      setPlanImportGroundingBusyForChat(chatId, false)
    }
  }

  const handleRunImportedPlan = (): void => {
    const review = pendingPlanImport
    if (!review) return
    if (planImportGroundingBusy) {
      window.alert('Wait for path checking to finish before running the imported plan.')
      return
    }

    if (
      currentChat?.chatKind === 'ensemble' ||
      (currentChat && getSideChatMode(currentChat) === 'guestParticipant')
    ) {
      window.alert('Plan Import is available for solo chats in this slice.')
      setPendingPlanImport(null)
      return
    }
    if (prompt.trim() !== review.rawText) {
      setPendingPlanImport(null)
      window.alert('The composer changed after this plan was reviewed. Import the plan again.')
      return
    }
    const objective = normalizeActiveGoalObjective(review.contract.goal)
    if (
      currentActiveGoal &&
      currentActiveGoal.status !== 'completed' &&
      currentActiveGoal.objective.trim() !== objective
    ) {
      const confirmed = window.confirm(
        'Replace the current active goal with the imported plan goal?'
      )
      if (!confirmed) return
    }
    setGoalFromObjective(review.contract.goal, { confirmReplace: false })
    const request = buildRunRequest(undefined, undefined, {
      prompt: buildPlanImportRunPrompt(review),
      displayPrompt: buildPlanImportDisplayPrompt(review),
      imageAttachments,
      claimProjectReferenceContext: true
    })
    if (!runRequestHasContent(request)) {
      settleProjectReferenceContextForRequest(request, 'rejected')
      return
    }

    setPendingPlanImport(null)
    const targetChat = request.chatRecord || currentChat
    const targetChatId = targetChat?.appChatId || currentChat?.appChatId
    if (
      shouldQueueRunBeforeDispatch({
        chatKind: targetChat?.chatKind,
        busy: isChatBusy(targetChatId)
      })
    ) {
      queueRunRequest(request)
      clearComposerAttachmentsForSubmittedRequest(request)
      if (!request.existingPrompt) {
        setChatPromptDraft(targetChatId || currentChatIdRef.current || currentChat?.appChatId, '')
      }
      return
    }

    void executeRun(request)
  }

  const updateCurrentGoalStatus = (status: ActiveGoalStatus, reason?: string): boolean => {
    if (!currentActiveGoal) {
      window.alert('No active goal is set for this chat.')
      return false
    }
    const nextGoal = updateActiveGoalLifecycle(
      currentResolvedGoal || currentActiveGoal,
      status,
      reason
    )
    persistGoalForCurrentChat(nextGoal)
    setGoalDraft(nextGoal.objective)
    setGoalEditing(false)
    return true
  }

  const markCurrentGoalBlocked = (): boolean => {
    if (!currentActiveGoal) {
      window.alert('No active goal is set for this chat.')
      return false
    }
    const reason = window.prompt('Why is this goal blocked?', currentActiveGoal.blockedReason || '')
    if (reason === null) return false
    return updateCurrentGoalStatus('blocked', reason.trim() || 'Blocked by user.')
  }

  const clearCurrentGoal = (): boolean => {
    if (!currentActiveGoal) return false
    if (isUnfinishedActiveGoal(currentActiveGoal)) {
      const confirmed = window.confirm('Clear the current active goal? This stops goal steering.')
      if (!confirmed) return false
    }
    persistGoalForCurrentChat(null)
    setGoalDraft('')
    setGoalEditing(false)
    setGoalPopoverOpen(false)
    return true
  }

  const updateGoalPopoverPosition = useCallback((): void => {
    const trigger = goalButtonRef.current
    if (!trigger) {
      setGoalPopoverPosition(null)
      return
    }
    const margin = 8
    const gap = 8
    const rect = trigger.getBoundingClientRect()
    const surface = trigger.closest('.composer-surface') as HTMLElement | null
    const surfaceRect = surface?.getBoundingClientRect() ?? rect
    const popover = goalPopoverRef.current
    const horizontalInset = 16
    const availableWidth = Math.max(0, window.innerWidth - margin * 2)
    const desiredWidth = Math.max(0, surfaceRect.width - horizontalInset)
    const widthFloor = Math.min(320, availableWidth)
    const width = Math.min(Math.max(desiredWidth, widthFloor), availableWidth)
    const height = Math.min(popover?.offsetHeight || 240, window.innerHeight - margin * 2)
    const preferredLeft = surfaceRect.left + horizontalInset / 2
    const maxLeft = Math.max(margin, window.innerWidth - width - margin)
    const left = Math.min(Math.max(preferredLeft, margin), maxLeft)

    let top = rect.top - height - gap
    if (top < margin) {
      top = rect.bottom + gap
      if (top + height + margin > window.innerHeight) {
        top = Math.max(margin, window.innerHeight - height - margin)
      }
    }

    setGoalPopoverPosition({
      left: Math.round(left),
      top: Math.round(top),
      width: Math.round(width)
    })
  }, [])

  useLayoutEffect(() => {
    if (!goalPopoverOpen) {
      setGoalPopoverPosition(null)
      return
    }
    updateGoalPopoverPosition()
    const frame = window.requestAnimationFrame(updateGoalPopoverPosition)
    return () => window.cancelAnimationFrame(frame)
  }, [
    goalPopoverOpen,
    goalEditing,
    goalDraft,
    currentActiveGoal?.id,
    currentActiveGoal?.status,
    currentActiveGoal?.objective,
    updateGoalPopoverPosition
  ])

  useEffect(() => {
    if (!goalPopoverOpen) return
    const handlePointerDown = (event: MouseEvent): void => {
      const target = event.target as Node | null
      if (!target) return
      if (goalButtonRef.current?.contains(target)) return
      if (goalPopoverRef.current?.contains(target)) return
      setGoalPopoverOpen(false)
    }
    const handleKeyDown = (event: KeyboardEvent): void => {
      if (event.key === 'Escape') setGoalPopoverOpen(false)
    }
    document.addEventListener('mousedown', handlePointerDown, true)
    document.addEventListener('keydown', handleKeyDown, true)
    window.addEventListener('resize', updateGoalPopoverPosition)
    window.addEventListener('scroll', updateGoalPopoverPosition, true)
    return () => {
      document.removeEventListener('mousedown', handlePointerDown, true)
      document.removeEventListener('keydown', handleKeyDown, true)
      window.removeEventListener('resize', updateGoalPopoverPosition)
      window.removeEventListener('scroll', updateGoalPopoverPosition, true)
    }
  }, [goalPopoverOpen, updateGoalPopoverPosition])

  const openGoalPopover = (editing = false, draftOverride?: string): void => {
    const fallbackDraft = draftOverride !== undefined ? draftOverride : prompt.trim()
    setGoalDraft(currentActiveGoal?.objective || fallbackDraft)
    setGoalEditing(editing)
    setGoalPopoverOpen(true)
  }

  const handleGoalSlashCommand = (
    promptWithoutSlashToken: string,
    rawPrompt: string = prompt,
    options: { activateInlinePrompt?: boolean } = {}
  ): boolean => {
    const trimmed = rawPrompt.trim()
    if (trimmed && !/^\/goal(?=\s|$)/i.test(trimmed)) {
      if (options.activateInlinePrompt) {
        return setGoalFromObjective(promptWithoutSlashToken)
      } else {
        openGoalPopover(false, promptWithoutSlashToken.trim())
        return true
      }
    }
    const args = trimmed.replace(/^\/goal(?=\s|$)/i, '').trim()
    if (!args) {
      openGoalPopover(false, '')
      return true
    }
    const [verbToken, ...restTokens] = args.split(/\s+/)
    const verb = verbToken.toLowerCase()
    const remainder = restTokens.join(' ').trim()
    if (verb === 'pause') {
      return updateCurrentGoalStatus('paused', remainder)
    } else if (verb === 'resume') {
      return updateCurrentGoalStatus('active', remainder)
    } else if (verb === 'clear') {
      return clearCurrentGoal()
    } else if (verb === 'complete' || verb === 'done') {
      return updateCurrentGoalStatus('completed', remainder)
    } else if (verb === 'blocked' || verb === 'block') {
      return updateCurrentGoalStatus('blocked', remainder || 'Blocked by user slash command.')
    } else if (verb === 'edit') {
      openGoalPopover(true)
      return true
    } else {
      return setGoalFromObjective(args)
    }
  }

  const openSideChatFromSlashCommand = (sideCommand: SideSlashCommand): false => {
    if (currentChat && currentChatIsLinkedChild) {
      void openCurrentSideChatPresentation(
        sideCommand.presentation,
        undefined,
        null,
        sideCommand.seedPrompt
      )
      return false
    }
    void ensureSideChatForCurrentChat(
      sideCommand.seedPrompt,
      true,
      sideCommand.presentation === 'drawer' ? 'drawer' : 'split',
      {},
      undefined,
      sideCommand.presentation !== 'popout' && sideCommand.presentation !== 'main'
    ).then((linkedChat) => {
      if (!linkedChat) return
      if (sideCommand.presentation === 'popout') {
        popOutLinkedChat(linkedChat, sideCommand.seedPrompt)
      } else if (sideCommand.presentation === 'main') {
        void handleSelectChat(linkedChat)
      }
    })
    return false
  }

  // tryHandleSideSlashSubmit / handleComposerSlash moved INTO <Composer>
  // (Slice C). They drive the composer-local slash-token machinery and build
  // the SlashCommandRunContext handed to each action command's run(). The
  // App-level openSideChatFromSlashCommand (above) is passed to <Composer> as a
  // prop so the side-slash submit path keeps working from any pane.

  const syncPersistentModelSelection = (nextModel: string) => {
    if (!persistentSessionActiveRef.current) {
      return
    }
    const currentModel =
      selectedModelType === 'custom' ? customModel.trim() || 'custom' : selectedModelType
    const nextModelLabel = nextModel === 'custom' ? 'custom model' : nextModel
    if (normalizeProviderModelKey(currentModel) === normalizeProviderModelKey(nextModel)) {
      return
    }
    markPersistentSessionRestartNeeded(
      `Gemini model changed to ${nextModelLabel}. Restart the persistent session to apply the new model.`
    )
  }

  // 1.0.4-AQ4 — Copy message content to clipboard. 1.0.8: routed
  // through the shared `useCopyFeedback` hook so the originating
  // message chip shows a transient "Copied" confirmation (keyed on
  // `messageId`) instead of copying silently. The hook owns the
  // clipboard write + the reset timer.
  const handleCopyMessage = useCallback(
    (messageId: string, content: string) => {
      if (!content) return
      copy(messageId, content)
    },
    [copy]
  )
  const handleAddTranscriptMessageToPrompt = useCallback(
    (chatId: string | null | undefined, content: string) => {
      handleAddMessageToPrompt(chatId, content)
    },
    [handleAddMessageToPrompt]
  )

  const handleCopyCurrentTranscript = useCallback(async () => {
    if (!currentChat?.appChatId) {
      return { ok: false as const, reason: 'empty' as const }
    }
    return window.api.copyChatMarkdownTranscript(currentChat.appChatId)
  }, [currentChat?.appChatId])

  const refreshSettingsPinnedMessages = useCallback(async () => {
    if (typeof window.api.getPinnedMessages !== 'function') return
    try {
      setSettingsPinnedMessageGroups(await window.api.getPinnedMessages())
    } catch {
      setSettingsPinnedMessageGroups([])
    }
  }, [])

  useEffect(() => {
    if (!showSettings || settingsActiveTab !== 'pinned-messages') return
    void refreshSettingsPinnedMessages()
  }, [showSettings, settingsActiveTab, refreshSettingsPinnedMessages])

  const togglePinMessageInChat = useCallback(
    (chat: ChatRecord | null | undefined, messageId: string) => {
      if (!chat || !messageId) return
      updateChatById(chat.appChatId, (source) => {
        let changed = false
        const pinnedAt = Date.now()
        const messages = source.messages.map((message) => {
          if (message.id !== messageId) return message
          changed = true
          return toggleChatMessagePin(message, pinnedAt)
        })
        return changed ? { ...source, messages, updatedAt: Date.now() } : source
      })
    },
    [updateChatById]
  )

  const toggleFeedbackMessageInChat = useCallback(
    (
      chat: ChatRecord | null | undefined,
      messageId: string,
      vote: 'up' | 'down',
      details?: MessageFeedbackDetails
    ) => {
      if (!chat || !messageId) return
      const at = Date.now()
      updateChatById(chat.appChatId, (source) => {
        let changed = false
        const messages = source.messages.map((message) => {
          if (message.id !== messageId) return message
          changed = true
          return applyChatMessageFeedback(message, vote, at, details)
        })
        return changed ? { ...source, messages, updatedAt: Date.now() } : source
      })
    },
    [updateChatById]
  )

  const updatePinnedNotesForChat = useCallback(
    (chatId: string | null | undefined, notes: string) => {
      if (!chatId) return
      updateChatById(chatId, (source) => ({
        ...source,
        pinnedNotes: notes,
        updatedAt: Date.now()
      }))
    },
    [updateChatById]
  )

  const jumpToTranscriptMessage = useCallback(
    (chatId: string | null | undefined, messageId: string, rowKey?: string) => {
      if (!chatId || !messageId) return
      prepareMainTranscriptMessageJump(chatId)
      transcriptJumpRequestIdRef.current =
        (transcriptJumpRequestIdRef.current + 1) % Number.MAX_SAFE_INTEGER
      setTranscriptJumpRequest({
        chatId,
        messageId,
        rowKey,
        requestId: transcriptJumpRequestIdRef.current
      })
    },
    [prepareMainTranscriptMessageJump]
  )

  const deleteMessageFromChat = useCallback(
    (chat: ChatRecord | null | undefined, messageId: string) => {
      if (!chat || !messageId) return
      const target = chat.messages.find((m) => m.id === messageId)
      if (!target) return
      const chatId = chat.appChatId
      if (
        agentQuestionQueueHasMessage(pendingAgentQuestionsByChatId[chatId], messageId) ||
        messageAnchorsActivePrompt(messageId, null, pendingPlanChoiceByChatId[chatId]?.messageId)
      ) {
        if (typeof window !== 'undefined' && typeof window.alert === 'function') {
          window.alert(
            'This message has an open prompt waiting on it. Answer or dismiss the prompt before deleting the message.'
          )
        }
        return
      }
      const preview =
        target.content && target.content.length > 80
          ? `${target.content.slice(0, 77)}…`
          : target.content || `(${target.role} message)`
      const ok =
        typeof window !== 'undefined' && typeof window.confirm === 'function'
          ? window.confirm(`Delete this message from the transcript?\n\n${preview}`)
          : true
      if (!ok) return
      updateChatById(chat.appChatId, (source) => ({
        ...source,
        messages: source.messages.filter((m) => m.id !== messageId)
      }))
    },
    [updateChatById, pendingAgentQuestionsByChatId, pendingPlanChoiceByChatId]
  )

  // 1.0.4-AQ4 — Delete a single message from the current chat's
  // transcript. Gates on `confirm()` because the action is
  // destructive and the user can't undo from the UI (no
  // tombstone). The orphan-pending guard below blocks deleting a
  // message that's currently the anchor of an in-flight
  // `pendingAgentQuestions` / `pendingPlanChoice` — deleting it
  // would strand the modal (its messageId would point at a row
  // that no longer exists in the transcript).
  const handleDeleteMessage = useCallback(
    (messageId: string) => {
      deleteMessageFromChat(currentChat, messageId)
    },
    [currentChat, deleteMessageFromChat]
  )

  const handleOpenSideChatFromMessage = useCallback(
    (message: ChatMessage) => {
      if (!canCreateSideChatFromCurrent || !currentChat || !message?.id) return
      if (message.metadata?.kind === 'channelInbound') return
      setSideChatSeedMessageId(message.id)
      const roleLabel =
        message.role === 'user'
          ? 'user message'
          : message.role === 'assistant'
            ? 'assistant message'
            : `${message.role} message`
      const seedPrompt = [
        `Use this selected ${roleLabel} from the parent chat as the starting point.`,
        'This isolated side chat does not have the rest of the parent transcript unless I paste it here.',
        '',
        message.content.trim()
      ].join('\n')
      void ensureSideChatForCurrentChat(seedPrompt, false, sideChatPresentationForCurrentParent, {
        originMessageId: message.id
      })
    },
    [
      canCreateSideChatFromCurrent,
      currentChat,
      ensureSideChatForCurrentChat,
      sideChatPresentationForCurrentParent
    ]
  )
  const handleOpenSideChatFromRunResult = useCallback(
    (runId: string) => {
      if (!canCreateSideChatFromCurrent || !currentChat || !runId) return
      const seedPrompt = buildSideChatRunResultSeedPrompt(currentChat, runId)
      void ensureSideChatForCurrentChat(seedPrompt, false, sideChatPresentationForCurrentParent, {
        originRunId: runId
      })
    },
    [
      canCreateSideChatFromCurrent,
      currentChat,
      ensureSideChatForCurrentChat,
      sideChatPresentationForCurrentParent
    ]
  )
  const latestSideChatRunResultSeed = useMemo(() => {
    if (!currentChat?.runs?.length) return null
    const sourceRun = [...currentChat.runs].reverse().find((run) => run.runId && run.endedAt)
    if (!sourceRun) return null
    const providerLabel = getProviderLabel(sourceRun.provider || getChatProvider(currentChat))
    return {
      runId: sourceRun.runId,
      label: `${providerLabel} run${sourceRun.status ? ` · ${sourceRun.status}` : ''}`
    }
  }, [currentChat])
  const handleOpenSideChatFromLatestRunResult = useCallback(() => {
    if (!latestSideChatRunResultSeed?.runId) return
    handleOpenSideChatFromRunResult(latestSideChatRunResultSeed.runId)
    setSideChatMenuOpen(false)
  }, [handleOpenSideChatFromRunResult, latestSideChatRunResultSeed])
  const sideChatSummarySeed = useMemo(() => {
    const ensembleSummary = currentChat?.ensemble?.lastRoundSummary?.trim()
    if (ensembleSummary) {
      return {
        label: 'Latest ensemble summary',
        content: ensembleSummary
      }
    }
    const latestAssistantMessage = [...(currentChat?.messages || [])]
      .reverse()
      .find((message) => message.role === 'assistant' && message.content.trim())
    if (!latestAssistantMessage?.content) return null
    return {
      label: 'Latest assistant response',
      content: compactPromptPreview(latestAssistantMessage.content)
    }
  }, [currentChat])
  const handleOpenSideChatFromSummary = useCallback(() => {
    if (!canCreateSideChatFromCurrent || !currentChat || !sideChatSummarySeed?.content) return
    const seedPrompt = [
      `Use this ${sideChatSummarySeed.label.toLowerCase()} from the parent chat as the starting point.`,
      'This isolated side chat only receives the pasted summary below, not the full parent transcript.',
      '',
      sideChatSummarySeed.content
    ].join('\n')
    void ensureSideChatForCurrentChat(seedPrompt, false, sideChatPresentationForCurrentParent, {
      transcriptVisibility: 'summary'
    })
    setSideChatMenuOpen(false)
  }, [
    canCreateSideChatFromCurrent,
    currentChat,
    ensureSideChatForCurrentChat,
    sideChatPresentationForCurrentParent,
    sideChatSummarySeed
  ])
  const selectedSideChatSeedMessage =
    sideChatSeedMessageId && currentChat?.messages
      ? currentChat.messages.find((message) => message.id === sideChatSeedMessageId) || null
      : null
  const handleMessageSelectionCandidate = useCallback((message: ChatMessage) => {
    if (!message?.id) return
    setSideChatSeedMessageId(message.id)
  }, [])
  const handleOpenSideChatFromSelectedMessage = useCallback(() => {
    if (!selectedSideChatSeedMessage) return
    handleOpenSideChatFromMessage(selectedSideChatSeedMessage)
    setSideChatMenuOpen(false)
  }, [handleOpenSideChatFromMessage, selectedSideChatSeedMessage])

  const handlePlanChoiceSubmit = (messageId: string, option: string) => {
    if (!currentWorkspace || !currentChat || !option.trim()) return

    setCurrentChat((prev) => {
      if (!prev) return prev
      const nextMessage: ChatMessage = {
        id: createMessageId(),
        role: 'user',
        content: option,
        timestamp: new Date().toISOString()
      }
      const updated = { ...prev, messages: [...prev.messages, nextMessage] }
      window.api.saveChat(updated)
      return updated
    })

    setPendingPlanChoice((prev) => (prev?.messageId === messageId ? null : prev))
    handleRun(undefined, option)
  }

  // Plan-mode proposed-plan decisions (the ProposedPlanCard action row).
  // Approve leaves read-only and implements; Respond/Dismiss stay in plan mode.
  // The decision is persisted on the plan's message so the card shows the
  // outcome (collapsed) and survives reload.
  const markProposedPlan = (
    messages: ChatMessage[],
    messageId: string,
    status: 'approved' | 'dismissed'
  ): ChatMessage[] =>
    messages.map((m) =>
      m.id === messageId && m.metadata?.proposedPlan
        ? {
            ...m,
            metadata: { ...m.metadata, proposedPlan: { ...m.metadata.proposedPlan, status } }
          }
        : m
    )

  const handleProposedPlanApprove = (messageId: string, planBody: string) => {
    if (!currentChat) return
    const original =
      currentChat.messages.find((m) => m.id === messageId)?.metadata?.proposedPlan?.body ?? null
    const trimmed = planBody.trim()
    const isEdited = original != null && trimmed !== original.trim()
    const prompt = isEdited
      ? `The plan above is approved with edits — implement this version now:\n\n${trimmed}`
      : 'The plan above is approved — implement it now.'
    // Approving LEAVES plan mode. Persist 'default' on the chat FIRST: the
    // main-side posture cap is downgrade-only, so a sticky 'plan' pill would
    // otherwise outrank the per-dispatch 'default' override and silently keep
    // the implement run read-only. This makes the trusted posture 'default'.
    rememberCurrentChatComposerSelection({
      approvalMode: 'default',
      workflowMode: 'normal',
      permissionPresetId: 'default'
    })
    setApprovalMode('default')
    setCurrentChat((prev) => {
      if (!prev) return prev
      const chatWithDefaultRoster =
        prev.ensemble && prev.ensemble.participants.length
          ? withSessionActivityLedger(prev, {
              ...prev,
              ensemble: {
                ...prev.ensemble,
                participants: prev.ensemble.participants.map((participant) => ({
                  ...participant,
                  permissionPresetId: 'default'
                }))
              }
            })
          : prev
      const nextMessage: ChatMessage = {
        id: createMessageId(),
        role: 'user',
        content: prompt,
        timestamp: new Date().toISOString()
      }
      const updated = {
        ...chatWithDefaultRoster,
        workflowMode: 'normal' as const,
        messages: [
          ...markProposedPlan(chatWithDefaultRoster.messages, messageId, 'approved'),
          nextMessage
        ]
      }
      chatByIdRef.current.set(updated.appChatId, updated)
      setChats((chatsState) =>
        chatsState.map((chat) => (chat.appChatId === updated.appChatId ? updated : chat))
      )
      window.api.saveChat(updated)
      return updated
    })
    // Elevate off plan/read-only so the implementation run can write files.
    handleRun(undefined, prompt, undefined, 'default', 'normal')
  }

  const handleProposedPlanDismiss = (messageId: string) => {
    if (!currentChat) return
    setCurrentChat((prev) => {
      if (!prev) return prev
      const updated = { ...prev, messages: markProposedPlan(prev.messages, messageId, 'dismissed') }
      window.api.saveChat(updated)
      return updated
    })
  }

  const handleProposedPlanCustom = (messageId: string, feedback: string) => {
    if (!currentChat || !feedback.trim()) return
    setCurrentChat((prev) => {
      if (!prev) return prev
      const nextMessage: ChatMessage = {
        id: createMessageId(),
        role: 'user',
        content: feedback,
        timestamp: new Date().toISOString()
      }
      const updated = {
        ...prev,
        messages: [...markProposedPlan(prev.messages, messageId, 'dismissed'), nextMessage]
      }
      window.api.saveChat(updated)
      return updated
    })
    // Respond = revise the plan; STAY in plan mode (no permission elevation).
    handleRun(undefined, feedback)
  }

  // QMOD (1.0.3) — user picked an answer (or typed free-text) for an
  // `ask_user_question` modal. Forward to main via IPC so the parked
  // MCP tool call resolves with the answer; also append a user-reply
  // message into the chat for transcript continuity so the trail of
  // "agent asked, user said X" stays visible after the modal closes.
  const handleAgentQuestionSubmit = useCallback(
    async (questionId: string, answer: string, isCustom: boolean) => {
      const trimmed = answer.trim()
      if (!trimmed) return
      const located = findQueuedAgentQuestion(pendingAgentQuestionsByChatId, questionId)
      if (!located) return
      const { chatId: targetChatId, question: pending } = located
      const response = await window.api.answerAgentQuestion({
        questionId,
        answer: trimmed,
        isCustom,
        appChatId: targetChatId,
        appRunId: pending.appRunId
      })
      if (!response.ok) {
        needsInputBanner.dismiss(questionId)
        setPendingAgentQuestionsForChat(targetChatId, (prev) =>
          removeAgentQuestionFromQueue(prev, questionId)
        )
        return
      }
      updateChatById(targetChatId, (prev) => {
        // The reply inherits the marker's round id so round grouping keeps
        // the Q&A trail inside one round group — an unstamped reply used to
        // split its round into two headers. (Legacy unstamped rows are
        // adopted by groupEnsembleMessagesByRound instead.)
        const markerRoundId = prev.messages?.find((m) => m.id === pending.messageId)?.metadata
          ?.ensembleRoundId
        const replyMsg: ChatMessage = {
          id: `agent-question-reply-${questionId}`,
          role: 'user',
          content: trimmed,
          timestamp: new Date().toISOString(),
          metadata: {
            kind: 'agentQuestionReply',
            questionId,
            respondedToMessageId: pending.messageId,
            isCustomAnswer: isCustom,
            ...(typeof markerRoundId === 'string' && markerRoundId
              ? { ensembleRoundId: markerRoundId }
              : {})
          }
        }
        // Idempotent: don't append a duplicate if the user double-
        // clicked the button before state updates settle.
        if (prev.messages?.some((m) => m.id === replyMsg.id)) return prev
        return { ...prev, messages: [...(prev.messages || []), replyMsg] }
      })
      needsInputBanner.dismiss(questionId)
      setPendingAgentQuestionsForChat(targetChatId, (prev) =>
        removeAgentQuestionFromQueue(prev, questionId)
      )
    },
    [
      pendingAgentQuestionsByChatId,
      updateChatById,
      setPendingAgentQuestionsForChat,
      needsInputBanner
    ]
  )

  // QMOD (1.0.3) — user dismissed the modal without answering. The
  // agent's tool call resolves with `cancelled: true`; agent should
  // treat that as "skip / continue without answer" so the run isn't
  // pinned waiting forever (the 10-min timeout is the safety net).
  const handleAgentQuestionDismiss = useCallback(
    async (questionId: string) => {
      const located = findQueuedAgentQuestion(pendingAgentQuestionsByChatId, questionId)
      if (!located) return
      const { chatId: targetChatId, question } = located
      await window.api.cancelAgentQuestion({
        questionId,
        reason: 'user-dismissed',
        appChatId: targetChatId,
        appRunId: question.appRunId
      })
      needsInputBanner.dismiss(questionId)
      setPendingAgentQuestionsForChat(targetChatId, (prev) =>
        removeAgentQuestionFromQueue(prev, questionId)
      )
    },
    [pendingAgentQuestionsByChatId, setPendingAgentQuestionsForChat, needsInputBanner]
  )

  const handleEnsemblePollVote = useCallback(
    async (chatId: string, pollId: string, choice: string) => {
      if (typeof window.api.answerEnsemblePoll !== 'function') return
      await window.api.answerEnsemblePoll({ appChatId: chatId, pollId, choice })
    },
    []
  )

  const findPendingApprovalRoute = (
    requestId: string
  ): { chatId: string; location: 'head' | 'queue' } | null => {
    const live = locatePendingApproval(
      requestId,
      pendingApprovalsLiveRef.current.byChatId,
      pendingApprovalsLiveRef.current.queueByChatId
    )
    if (!live) return null
    // Prefer head when the id is present in both (should not happen).
    return { chatId: live.chatId, location: live.inHead ? 'head' : 'queue' }
  }

  const handleAgentApprovalAction = async (
    requestId: string,
    action: AgentApprovalAction,
    intentNoteOverride?: string
  ): Promise<boolean> => {
    // Order-4 — capture the optional intent note (trimmed) at decision
    // time and pass it down to the IPC, which stamps it onto the ledger
    // row's metadata. Empty stays undefined so we never persist a blank
    // note. Always optional — never gates the decision.
    const noteForDecision = (intentNoteOverride ?? intentNote).trim() || undefined
    const usesIntentNoteOverride = intentNoteOverride !== undefined
    // Snapshot chatId before await for fallback only; dismiss re-locates live.
    const pendingRoute = findPendingApprovalRoute(requestId)
    let responseAccepted:
      | boolean
      | {
          ok: boolean
          resolvedAction?: AgentApprovalAction
          decisionSource?: 'user' | 'system'
          reason?: string
          message?: string
        } = false
    try {
      responseAccepted = await window.api.respondAgentApproval(requestId, action, noteForDecision)
      if (!shouldDismissAgentApproval(responseAccepted)) {
        setRawLogs((prev) => [
          ...prev,
          {
            type: 'stderr',
            content:
              'Approval response was not accepted. The request remains open for exact review or a different decision.'
          }
        ])
        return false
      }
      const remapped =
        responseAccepted &&
        typeof responseAccepted === 'object' &&
        responseAccepted.reason === 'stale-grant-binding'
          ? responseAccepted
          : null
      setRawLogs((prev) => [
        ...prev,
        {
          type: remapped ? 'stderr' : 'info',
          content: remapped
            ? remapped.message ||
              'Grant cancelled: the chat workspace changed while the prompt was open. Re-approve from the current workspace if still needed.'
            : `${getProviderLabel(pendingAgentApproval?.provider || currentProvider)} approval response sent: ${
                typeof responseAccepted === 'object' && responseAccepted.resolvedAction
                  ? responseAccepted.resolvedAction
                  : action
              }`
        }
      ])
      if (action === 'acceptForWorkspace') {
        const settings = await window.api.getSettings()
        setAgenticWorkspaceGrantCount(
          Array.isArray(settings.agenticWorkspaceGrants)
            ? settings.agenticWorkspaceGrants.length
            : 0
        )
      }
    } catch (error) {
      setRawLogs((prev) => [
        ...prev,
        { type: 'stderr', content: `Failed to send approval response: ${redactLog(String(error))}` }
      ])
    } finally {
      if (shouldDismissAgentApproval(responseAccepted)) {
        // Re-locate against live maps after await — sequential Allow-all may
        // have promoted this id from queue → head while we were in flight.
        const liveRoute = findPendingApprovalRoute(requestId)
        const targetChatId =
          liveRoute?.chatId || pendingRoute?.chatId || getCurrentComposerStateChatId()
        // Order-4 — reset the intent note so the next queued approval
        // (or the next request entirely) starts with an empty field.
        if (!usesIntentNoteOverride) setIntentNote('')
        if (!targetChatId) {
          setPendingAgentApproval((prev) => (prev?.id === requestId ? null : prev))
        } else {
          // Dismiss by id: scrub queue always, and clear+advance head when it
          // matches — never trust a pre-await head/queue location alone.
          setPendingApprovalQueueByChatId((prev) => {
            const existing = prev[targetChatId] || []
            const next = existing.filter((approval) => approval.id !== requestId)
            if (next.length === existing.length) return prev
            if (next.length === 0) {
              const { [targetChatId]: _omit, ...without } = prev
              return without
            }
            return { ...prev, [targetChatId]: next }
          })
          let clearedHead = false
          setPendingAgentApprovalForChatId(targetChatId, (prev) => {
            if (prev?.id !== requestId) return prev
            clearedHead = true
            return null
          })
          if (clearedHead) {
            advanceApprovalQueueForChat(targetChatId)
          }
        }
      }
    }
    return shouldDismissAgentApproval(responseAccepted)
  }

