  useEffect(() => {
    const queuedRequests = getQueuedDesktopRunJobs(runQueueJobs)
      .map((job) => resolveQueuedDesktopRunRequest(job))
      .filter((request): request is QueuedRunRequest => Boolean(request))
    const nowMs = Date.now()
    const nextRunAtMs = queuedRequests.reduce<number | null>((next, request) => {
      const runAtMs = getScheduledQueueRunAtMs(request)
      if (runAtMs === null || runAtMs <= nowMs) return next
      return next === null || runAtMs < next ? runAtMs : next
    }, null)
    if (nextRunAtMs === null) return
    const delayMs = Math.max(250, nextRunAtMs - nowMs)
    const timeout = window.setTimeout(() => {
      setScheduledQueueWakeTick((tick) => tick + 1)
    }, delayMs)
    return () => window.clearTimeout(timeout)
  }, [queuedRuns, runQueueJobs, workspaces, currentWorkspace, currentChat, scheduledQueueWakeTick])

  useEffect(() => {
    const nowMs = Date.now()
    for (const job of getQueuedDesktopRunJobs(runQueueJobs)) {
      const request = resolveQueuedDesktopRunRequest(job)
      const chatId = request?.chatRecord?.appChatId || job.chatId
      const liveChat = chatId
        ? chatByIdRef.current.get(chatId) || request?.chatRecord
        : request?.chatRecord
      if (
        !request?.appRunId ||
        !request.scheduledRunAt ||
        !chatId ||
        !shouldAppendDueScheduledRun({
          scheduledRunAt: request.scheduledRunAt,
          nowMs,
          chatBusy: isChatBusy(chatId, { ignoreQueueRunId: request.appRunId }),
          chatKind: liveChat?.chatKind === 'ensemble' || liveChat?.ensemble ? 'ensemble' : 'single'
        })
      ) {
        continue
      }
      if (findMidRunQueuedMessage(liveChat?.messages || [], request.appRunId)) continue
      void appendMidRunQueuedRequestToTranscript(
        { ...request, chatRecord: liveChat || request.chatRecord },
        'scheduledRun',
        request.scheduledRunAt
      )
    }
  }, [queuedRuns, runQueueJobs, workspaces, currentWorkspace, currentChat, scheduledQueueWakeTick])

  useEffect(() => {
    const queuedJobs = getQueuedDesktopRunJobs(runQueueJobs)
    queuedDispatchLeaseClaimsRef.current.retainQueuedRunIds(queuedJobs.map((job) => job.runId))
    if (queuedJobs.length === 0) return

    // Pure scheduling decision lives in main (Phase B3.3 extraction). The
    // renderer pump still orchestrates the lease + execute side effects, but
    // the "which job runs next" choice is now shared with future remote
    // pumpers via `findNextRunnableQueueIndex`.
    //
    // Phase J3: per-chat busy predicate. A queued job dispatches as soon
    // as its TARGET chat is idle, even if the same provider is busy in a
    // different chat. Parallel-per-chat dispatch matches both Codex's
    // app-server thread model and the user's mental model ("I queued
    // this in chat B; chat A finishing shouldn't be the trigger").
    const queuedRequests = queuedJobs
      .map((job) => resolveQueuedDesktopRunRequest(job))
      .filter((request): request is QueuedRunRequest => Boolean(request))
      .filter(
        (request) =>
          !request.appRunId || !queuedDispatchLeaseClaimsRef.current.has(request.appRunId)
      )
    if (queuedRequests.length === 0) return
    const nowMs = Date.now()
    const nextIndex = findNextRunnableQueueIndex(
      queuedRequests,
      (job) =>
        isQueuedRunReadyToDispatch(job, nowMs) &&
        !shouldQueueRunBeforeDispatch({
          chatKind: job.chatRecord?.chatKind,
          busy: isChatBusy(job.chatRecord?.appChatId)
        })
    )
    if (nextIndex < 0) return

    const nextRun = queuedRequests[nextIndex]
    const nextRunId = nextRun.appRunId
    if (!nextRunId || !queuedDispatchLeaseClaimsRef.current.tryClaim(nextRunId)) return
    const remainingRuns = queuedRequests.filter((_, index) => index !== nextIndex)
    void window.api
      .leaseRunQueueJob({
        runId: nextRunId,
        provider: nextRun.provider,
        statusReason: 'Dequeued by TaskWraith scheduler.'
      })
      .then(
        (leased) => {
          if (!leased) {
            queuedDispatchLeaseClaimsRef.current.release(nextRunId)
            return
          }
          setQueuedRuns((prev) => removeExactQueuedRunRequest(prev, nextRunId))
          let dispatchChat = nextRun.chatRecord
          if (
            dispatchChat &&
            (hasPendingProviderChange(dispatchChat) ||
              hasPendingEnsembleRosterPresetApply(dispatchChat))
          ) {
            const appliedChat = updateChatById(dispatchChat.appChatId, (source) => ({
              ...applyPendingProviderChangeOnFinalize(
                applyPendingEnsembleRosterPresetOnFinalize(source)
              ),
              updatedAt: Date.now()
            }))
            if (appliedChat) {
              dispatchChat = appliedChat
              if (currentChatIdRef.current === appliedChat.appChatId) {
                applyChatComposerSelection(appliedChat, getChatProvider(appliedChat))
              }
            }
          }
          const dispatchProvider = getChatProvider(dispatchChat || nextRun.chatRecord)
          appEventHandlersRef.current.appendThreadRawLog(nextRun.chatRecord?.appChatId, {
            type: 'info',
            content: `Starting ${nextRun.scheduledRunAt ? 'scheduled ' : 'queued '}${getProviderLabel(
              dispatchProvider
            )} run. ${remainingRuns.length} queued task${remainingRuns.length === 1 ? '' : 's'} remain.`
          })
          void executeRunRef.current({
            ...nextRun,
            appRunId: leased.runId,
            provider: dispatchProvider,
            chatRecord: dispatchChat || nextRun.chatRecord
          })
        },
        () => {
          queuedDispatchLeaseClaimsRef.current.release(nextRunId)
        }
      )
  }, [
    queuedRuns,
    runningChatIds,
    runQueueJobs,
    workspaces,
    currentWorkspace,
    currentChat,
    scheduledQueueWakeTick
  ])

