  const activeWorkspaceBoard =
    activeWorkspaceBoardId != null
      ? workspaceBoards.find((board) => board.id === activeWorkspaceBoardId && !board.archived) ||
        null
      : null
  const activeWorkspaceBoardWorkspace =
    activeWorkspaceBoard != null
      ? workspaces.find((workspace) => workspace.id === activeWorkspaceBoard.workspaceId) || null
      : null
  const activeWorkspaceBoardCards = activeWorkspaceBoard
    ? workspaceBoardCards.filter((card) => card.boardId === activeWorkspaceBoard.id)
    : []

  const activeProjectGraphProjection = useMemo(() => {
    void projectsRevision
    if (activeProjectGraphId == null) return null
    const project = listProjects().find(
      (candidate) => candidate.id === activeProjectGraphId && !candidate.archived
    )
    if (!project) return null
    const homeChatId = getProjectWorkProfile(project.id)?.homeChatId
    return buildProjectThreadGraphProjection({
      projectId: project.id,
      projectName: project.name,
      memberChatIds: project.memberChatIds,
      chats,
      graphEdges: listProjectGraphEdges(project.id),
      runningChatIds,
      ...(homeChatId ? { homeChatId } : {})
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeProjectGraphId, projectsRevision, chats, runningChatIds])

  // Computed inline (not memoized): the projects store's member lists can
  // settle a beat after the project rows appear, and a projectsRevision-keyed
  // memo can miss that second update. Recomputing each render keeps the
  // "Node Graphs" section in step with the tree, which does the same.
  const projectGraphEntries = listProjects()
    .filter((project) => !project.archived && project.memberChatIds.length > 0)
    .map((project) => ({
      id: project.id,
      name: project.name,
      memberCount: project.memberChatIds.length
    }))

